window.QUESTIONS_PLUS=[
{id:"LG-6E-501",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Suite : 3, 8, 13, 18, … Quel est le terme suivant ?",rep:"23",choix:["21", "23", "24", "26"],diff:2,hint:"Calcule l'écart entre deux termes qui se suivent.",expl:"On ajoute 5 à chaque fois : 18 + 5 = 23. Dans une suite, cherche d'abord l'écart constant entre les termes."},
{id:"LG-6E-502",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Suite : 81, 27, 9, 3, … Quel est le terme suivant ?",rep:"1",choix:["0", "1", "2", "6"],diff:2,hint:"Compare chaque terme au précédent : addition ou division ?",expl:"Chaque terme est le précédent divisé par 3 : 3 ÷ 3 = 1. Si l'écart change, teste une multiplication ou une division."},
{id:"LG-6E-503",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Suite de lettres : B, D, F, H, … Quelle est la lettre suivante ?",rep:"J",choix:["I", "J", "K", "L"],diff:2,hint:"Regarde combien de lettres on saute à chaque fois.",expl:"On avance de 2 lettres dans l'alphabet en sautant une lettre : après H, on saute I et on arrive à J."},
{id:"LG-6E-504",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Suite : 1, 2, 4, 7, 11, … Quel est le terme suivant ?",rep:"16",choix:["15", "16", "17", "18"],diff:3,hint:"Les écarts ne sont pas constants : écris-les.",expl:"Les écarts sont +1, +2, +3, +4, donc ensuite +5 : 11 + 5 = 16. Quand l'écart change, cherche la règle des écarts."},
{id:"LG-6E-505",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Léa est plus âgée que Tom, Tom plus âgé que Sami, Sami plus âgé que Nour. Qui est le 2e plus jeune ?",rep:"Sami",choix:["Léa", "Tom", "Sami", "Nour"],diff:3,hint:"Range les quatre enfants du plus âgé au plus jeune.",expl:"Ordre : Léa > Tom > Sami > Nour. La plus jeune est Nour, juste avant elle vient Sami. Range toujours les éléments dans l'ordre."},
{id:"LG-6E-506",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Aujourd'hui, c'est mercredi. Quel jour serons-nous dans 10 jours ?",rep:"samedi",choix:["vendredi", "samedi", "dimanche", "lundi"],diff:2,hint:"Dans 7 jours, on retombe sur le même jour de la semaine.",expl:"10 = 7 + 3 : dans 7 jours c'est encore mercredi, puis 3 jours de plus donnent samedi. Retire les semaines entières."},
{id:"LG-6E-507",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Le 1er mars est un lundi. Quel jour de la semaine est le 1er avril ?",rep:"jeudi",choix:["mardi", "mercredi", "jeudi", "vendredi"],diff:3,hint:"Mars compte 31 jours. Combien de semaines entières ?",expl:"Du 1er mars au 1er avril, il y a 31 jours = 4 semaines + 3 jours. Lundi + 3 jours donne jeudi."},
{id:"LG-6E-508",classe:"6ème",cat:"🧠",type:"Logique",enonce:"On lance un dé à 6 faces. L'événement « obtenir un nombre inférieur à 7 » est…",rep:"certain",choix:["certain", "impossible", "peu probable", "très rare"],diff:2,hint:"Regarde toutes les faces possibles du dé.",expl:"Toutes les faces (1 à 6) sont inférieures à 7 : l'événement se produit à coup sûr, il est certain."},
{id:"LG-6E-509",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Une roue a 8 cases égales : 3 rouges et 5 bleues. Quelle est la probabilité de tomber sur rouge ?",rep:"3/8",choix:["3/8", "3/5", "5/8", "1/3"],diff:2,hint:"Probabilité = cas favorables ÷ nombre total de cases.",expl:"Il y a 3 cases rouges sur 8 cases en tout, donc 3/8. On divise par le total, pas par le nombre de cases bleues."},
{id:"LG-6E-510",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Un menu propose 2 entrées, 3 plats et 2 desserts. Combien de menus entrée-plat-dessert différents ?",rep:"12",choix:["7", "10", "12", "14"],diff:3,hint:"Pour chaque entrée, combien de choix de plats, puis de desserts ?",expl:"On multiplie les choix : 2 × 3 × 2 = 12. On n'additionne pas : chaque entrée peut aller avec chaque plat et chaque dessert."},
{id:"LG-6E-511",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Aucun poisson ne marche. Le saumon est un poisson. Que peut-on conclure ?",rep:"Le saumon ne marche pas",choix:["Le saumon ne marche pas", "Le saumon marche parfois", "Certains saumons marchent", "On ne peut rien conclure"],diff:2,hint:"Ce qui est vrai pour tous les poissons l'est pour chacun.",expl:"La règle concerne tous les poissons, sans exception. Le saumon en est un, donc il ne marche pas."},
{id:"LG-6E-512",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Certains élèves de la classe ont un chat. Tom est dans la classe. Que peut-on dire ?",rep:"On ne sait pas si Tom a un chat",choix:["Tom a un chat", "Tom n'a pas de chat", "On ne sait pas si Tom a un chat", "Tous les élèves ont un chat"],diff:3,hint:"« Certains » ne veut pas dire « tous ».",expl:"« Certains » signifie « au moins un », pas tous. Tom peut faire partie de ceux qui ont un chat… ou non : on ne peut pas conclure."},
{id:"LG-6E-513",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Quel est l'intrus : 15, 25, 35, 42, 55 ?",rep:"42",choix:["15", "35", "42", "55"],diff:2,hint:"Regarde le chiffre des unités de chaque nombre.",expl:"15, 25, 35 et 55 sont des multiples de 5 (ils finissent par 5). 42 ne l'est pas : c'est l'intrus."},
{id:"LG-6E-514",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Dans 5 ans, Lina aura le double de l'âge qu'elle avait il y a 5 ans. Quel âge a-t-elle ?",rep:"15 ans",choix:["10 ans", "15 ans", "20 ans", "25 ans"],diff:4,hint:"Teste chaque réponse : calcule son âge passé et futur.",expl:"Avec 15 ans : il y a 5 ans elle avait 10 ans, dans 5 ans elle aura 20 ans, soit le double de 10. Tester les réponses est une bonne méthode."},
{id:"LG-6E-515",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Tu plantes un piquet tous les 2 m sur une clôture droite de 10 m, aux deux bouts compris. Combien de piquets ?",rep:"6",choix:["4", "5", "6", "10"],diff:3,hint:"Fais un petit schéma : compte les intervalles puis les piquets.",expl:"10 ÷ 2 = 5 intervalles. Il y a toujours un piquet de plus que d'intervalles sur une ligne ouverte : 5 + 1 = 6."},
{id:"LG-6E-516",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Un chat et un chien pèsent 15 kg ensemble. Le chien pèse 9 kg de plus que le chat. Combien pèse le chat ?",rep:"3 kg",choix:["3 kg", "4 kg", "6 kg", "12 kg"],diff:3,hint:"Enlève d'abord la différence de 9 kg au total.",expl:"15 − 9 = 6 kg, partagés en deux parts égales : le chat pèse 3 kg et le chien 12 kg. Vérifie : 3 + 12 = 15."},
{id:"LG-6E-517",classe:"6ème",cat:"🧠",type:"Logique",enonce:"« Il pleut OU il fait froid » est vraie. Or il ne pleut pas. Que peut-on conclure ?",rep:"Il fait froid",choix:["Il fait froid", "Il ne fait pas froid", "Il va pleuvoir", "On ne peut rien dire"],diff:3,hint:"Pour qu'un « OU » soit vrai, au moins une partie doit l'être.",expl:"« A OU B » vrai veut dire qu'au moins une des deux est vraie. Comme il ne pleut pas, c'est forcément qu'il fait froid."},
{id:"LG-6E-518",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Code secret : A = 1, B = 2, C = 3, etc. Quel mot s'écrit 3-1-6-5 ?",rep:"CAFE",choix:["CADE", "CAFE", "CAGE", "BAFE"],diff:2,hint:"Retrouve la lettre qui correspond à chaque nombre.",expl:"3 = C, 1 = A, 6 = F, 5 = E : le mot est CAFE. Chaque nombre donne la position de la lettre dans l'alphabet."},
{id:"LG-6E-519",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Il est 14 h 50. Quelle heure sera-t-il dans 1 h 25 ?",rep:"16 h 15",choix:["15 h 15", "16 h 05", "16 h 15", "16 h 25"],diff:2,hint:"Ajoute d'abord 10 minutes pour arriver à une heure ronde.",expl:"14 h 50 + 10 min = 15 h, il reste 1 h 15 à ajouter : 16 h 15. Passer par l'heure ronde évite les erreurs."},
{id:"LG-6E-520",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Combien de carrés en tout vois-tu dans une grille de 2 cases sur 2 cases ?",rep:"5",choix:["4", "5", "6", "8"],diff:3,hint:"N'oublie pas le grand carré formé par toute la grille.",expl:"Il y a 4 petits carrés et 1 grand carré qui les entoure : 4 + 1 = 5. Compte les carrés de chaque taille."},
{id:"LG-6E-521",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Un tiroir contient des chaussettes rouges et bleues. Dans le noir, combien en prendre au minimum pour être sûr d'avoir deux chaussettes de même couleur ?",rep:"3",choix:["2", "3", "4", "5"],diff:3,hint:"Imagine le pire des cas avec les deux premières chaussettes.",expl:"Au pire, les 2 premières sont de couleurs différentes. La 3e est forcément rouge ou bleue et forme une paire."},
{id:"LG-6E-522",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Paul a lu la moitié de son livre puis 20 pages. Il lui reste 40 pages. Combien de pages a le livre ?",rep:"120",choix:["80", "100", "120", "140"],diff:3,hint:"Que représentent les 20 + 40 pages par rapport au livre ?",expl:"Après la moitié, il reste l'autre moitié : 20 + 40 = 60 pages. Le livre fait donc 2 × 60 = 120 pages."},
{id:"LG-6E-523",classe:"6ème",cat:"🧠",type:"Logique",enonce:"Figures : 1 carré, puis 3, puis 5, puis 7… Combien de carrés à la 10e figure ?",rep:"19",choix:["17", "19", "20", "21"],diff:3,hint:"On ajoute 2 carrés à chaque figure. Combien d'ajouts jusqu'à la 10e ?",expl:"De la 1re à la 10e figure, on ajoute 9 fois 2 carrés : 1 + 9 × 2 = 19. Compte bien le nombre d'étapes."},
{id:"LG-5E-501",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Suite : 2, 3, 5, 8, 12, 17, … Quel est le terme suivant ?",rep:"23",choix:["22", "23", "24", "25"],diff:2,hint:"Écris les écarts entre les termes successifs.",expl:"Les écarts sont +1, +2, +3, +4, +5, donc ensuite +6 : 17 + 6 = 23."},
{id:"LG-5E-502",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Suite : 1, 2, 4, 8, 16, … Quel est le 10e terme ?",rep:"512",choix:["20", "256", "512", "1 024"],diff:3,hint:"Chaque terme est le double du précédent. Compte bien les rangs.",expl:"Le 1er terme est 1 ; on double 9 fois pour atteindre le 10e : 256 × 2 = 512. Attention au décalage d'un rang."},
{id:"LG-5E-503",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Suite : 100, 95, 85, 70, 50, … Quel est le terme suivant ?",rep:"25",choix:["20", "25", "30", "35"],diff:3,hint:"Calcule les écarts : ils changent de façon régulière.",expl:"Les écarts sont −5, −10, −15, −20, donc ensuite −25 : 50 − 25 = 25."},
{id:"LG-5E-504",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Suite de lettres : Z, X, V, T, … Quelle est la lettre suivante ?",rep:"R",choix:["P", "Q", "R", "S"],diff:2,hint:"On recule dans l'alphabet. De combien de lettres ?",expl:"On recule de 2 lettres à chaque fois en en sautant une : après T, on saute S et on arrive à R."},
{id:"LG-5E-505",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Suite : 1, 4, 2, 5, 3, 6, … Quel est le terme suivant ?",rep:"4",choix:["4", "5", "7", "8"],diff:3,hint:"Sépare les termes de rang impair et ceux de rang pair.",expl:"Deux suites s'alternent : 1, 2, 3, … et 4, 5, 6, … Le 7e terme appartient à la première : c'est 4."},
{id:"LG-5E-506",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Suite : 2, 6, 12, 20, 30, … Quel est le terme suivant ?",rep:"42",choix:["36", "40", "42", "44"],diff:3,hint:"Les écarts augmentent de 2 à chaque fois.",expl:"Écarts : +4, +6, +8, +10, puis +12 : 30 + 12 = 42. On peut aussi voir 1×2, 2×3, 3×4… et 6×7 = 42."},
{id:"LG-5E-507",classe:"5ème",cat:"🧠",type:"Logique",enonce:"On tire au hasard une carte numérotée de 1 à 10. Probabilité d'obtenir un nombre premier ?",rep:"2/5",choix:["1/3", "3/10", "2/5", "1/2"],diff:3,hint:"Liste les nombres premiers entre 1 et 10 (1 n'en est pas un).",expl:"Les nombres premiers sont 2, 3, 5 et 7 : 4 cas sur 10, soit 4/10 = 2/5. Rappel : 1 n'est pas premier."},
{id:"LG-5E-508",classe:"5ème",cat:"🧠",type:"Logique",enonce:"On lance un dé équilibré à 6 faces. Quelle est la probabilité d'obtenir un multiple de 3 ?",rep:"1/3",choix:["1/6", "1/3", "1/2", "2/3"],diff:2,hint:"Quelles faces du dé sont des multiples de 3 ?",expl:"Les multiples de 3 sont 3 et 6 : 2 cas sur 6, soit 2/6 = 1/3."},
{id:"LG-5E-509",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Sur 50 lancers d'une pièce, on obtient 28 fois pile. Quelle est la fréquence de pile ?",rep:"0,56",choix:["0,28", "0,44", "0,5", "0,56"],diff:3,hint:"Fréquence = nombre d'apparitions ÷ nombre total de lancers.",expl:"28 ÷ 50 = 0,56. La fréquence observée peut différer de la probabilité théorique 0,5."},
{id:"LG-5E-510",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Quel nombre est un contre-exemple à « tout nombre impair est premier » ?",rep:"9",choix:["7", "9", "11", "13"],diff:2,hint:"Cherche un nombre impair qui a d'autres diviseurs que 1 et lui-même.",expl:"9 est impair mais divisible par 3, donc pas premier. Un seul contre-exemple suffit pour prouver qu'une affirmation est fausse."},
{id:"LG-5E-511",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Quel nombre contredit « le carré d'un nombre est toujours plus grand que ce nombre » ?",rep:"0,5",choix:["2", "3", "0,5", "10"],diff:4,hint:"Calcule le carré de chaque proposition et compare.",expl:"0,5² = 0,25, qui est plus petit que 0,5. Pour un nombre entre 0 et 1, le carré est plus petit que le nombre."},
{id:"LG-5E-512",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Chevaliers : toujours vrai ; menteurs : toujours faux. Bob dit : « Ana et moi sommes menteurs. » Que sont-ils ?",rep:"Bob menteur, Ana chevalier",choix:["Bob chevalier, Ana menteuse", "Bob menteur, Ana chevalier", "Tous deux menteurs", "Tous deux chevaliers"],diff:4,hint:"Un chevalier pourrait-il dire qu'il est menteur ?",expl:"Bob ne peut pas être chevalier (il dirait un mensonge), donc il ment. Sa phrase est fausse : ils ne sont pas tous deux menteurs, donc Ana est chevalier."},
{id:"LG-5E-513",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Quelle est la négation de « Au moins un élève est absent » ?",rep:"Aucun élève n'est absent",choix:["Aucun élève n'est absent", "Tous les élèves sont absents", "Un seul élève est absent", "Au moins un élève est présent"],diff:3,hint:"La négation doit être vraie exactement quand la phrase est fausse.",expl:"« Au moins un absent » est faux seulement si personne n'est absent. La négation de « au moins un » est « aucun »."},
{id:"LG-5E-514",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Classe de 28 : 15 font du foot, 10 du judo, 5 font les deux. Combien ne font ni l'un ni l'autre ?",rep:"8",choix:["3", "5", "8", "13"],diff:3,hint:"Les 5 élèves qui font les deux sont comptés deux fois.",expl:"Élèves sportifs : 15 + 10 − 5 = 20. Il reste 28 − 20 = 8 élèves qui ne font aucun des deux."},
{id:"LG-5E-515",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Un père a 40 ans et son fils 10 ans. Dans combien d'années le père aura-t-il le triple de l'âge du fils ?",rep:"5 ans",choix:["5 ans", "10 ans", "15 ans", "20 ans"],diff:4,hint:"Teste chaque proposition : ajoute les années aux deux âges.",expl:"Dans 5 ans : père 45 ans, fils 15 ans, et 45 = 3 × 15. Les deux vieillissent du même nombre d'années."},
{id:"LG-5E-516",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Il faut 30 s pour monter du 1er au 3e étage. Combien pour monter du 1er au 6e, au même rythme ?",rep:"75 s",choix:["60 s", "75 s", "90 s", "105 s"],diff:4,hint:"Compte les étages à franchir, pas les numéros d'étage.",expl:"Du 1er au 3e : 2 étages en 30 s, soit 15 s par étage. Du 1er au 6e : 5 étages, donc 5 × 15 = 75 s."},
{id:"LG-5E-517",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Couper une bûche prend 2 min par coupe. Combien de temps pour la couper en 5 morceaux ?",rep:"8 min",choix:["6 min", "8 min", "10 min", "12 min"],diff:3,hint:"Combien de coupes faut-il pour obtenir 5 morceaux ?",expl:"Il faut 4 coupes pour obtenir 5 morceaux (une de moins que de morceaux) : 4 × 2 = 8 minutes."},
{id:"LG-5E-518",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Une année de 365 jours commence un lundi. Quel jour de la semaine est le 31 décembre ?",rep:"lundi",choix:["dimanche", "lundi", "mardi", "mercredi"],diff:4,hint:"365 = 52 × 7 + 1. Le 31 décembre est le 365e jour.",expl:"Le 365e jour arrive 364 jours après le 1er, soit 52 semaines pile : c'est donc le même jour, un lundi."},
{id:"LG-5E-519",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Un nombre est divisible par 6. Il est donc forcément divisible par…",rep:"3",choix:["3", "4", "9", "12"],diff:2,hint:"Décompose 6 en un produit de deux nombres.",expl:"6 = 2 × 3 : tout multiple de 6 est aussi multiple de 2 et de 3. Ce n'est pas forcément vrai pour 4, 9 ou 12 (ex. : 6)."},
{id:"LG-5E-520",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Quel nombre est un multiple de 4 mais pas de 8 ?",rep:"12",choix:["12", "16", "24", "32"],diff:2,hint:"Divise chaque nombre par 8 et regarde le reste.",expl:"12 = 4 × 3, mais 12 ÷ 8 ne tombe pas juste. 16, 24 et 32 sont tous des multiples de 8."},
{id:"LG-5E-521",classe:"5ème",cat:"🧠",type:"Logique",enonce:"8 pièces identiques, dont une plus lourde. Combien de pesées au minimum sur une balance à plateaux pour la trouver à coup sûr ?",rep:"2",choix:["1", "2", "3", "4"],diff:4,hint:"Fais des groupes de 3, 3 et 2 pièces.",expl:"Pèse 3 contre 3. Si équilibre, la lourde est parmi les 2 restantes ; sinon parmi les 3 du plateau lourd. Une 2e pesée suffit dans les deux cas."},
{id:"LG-5E-522",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Deux cyclistes à 30 km l'un de l'autre roulent l'un vers l'autre à 10 km/h et 20 km/h. Quand se croisent-ils ?",rep:"Après 1 h",choix:["Après 30 min", "Après 1 h", "Après 1 h 30", "Après 2 h"],diff:3,hint:"De combien de kilomètres se rapprochent-ils chaque heure ?",expl:"Ensemble, ils se rapprochent de 10 + 20 = 30 km par heure. Les 30 km sont donc parcourus en 1 h."},
{id:"LG-5E-523",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Dans une grille de 3 cases sur 3, combien de carrés de toutes tailles peut-on compter ?",rep:"14",choix:["9", "10", "13", "14"],diff:4,hint:"Compte séparément les carrés de 1×1, de 2×2 et de 3×3.",expl:"9 petits carrés + 4 carrés de 2×2 + 1 grand carré = 14. Il faut compter chaque taille sans en oublier."},
{id:"LG-5E-524",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Avec les chiffres 1, 2, 3, 4, sans répéter, combien de nombres à 2 chiffres peux-tu écrire ?",rep:"12",choix:["6", "8", "12", "16"],diff:3,hint:"Combien de choix pour les dizaines, puis pour les unités ?",expl:"4 choix pour les dizaines, puis 3 restants pour les unités : 4 × 3 = 12."},
{id:"LG-5E-525",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Un cadenas a 3 molettes, chacune avec les chiffres 0 à 9. Combien de codes différents ?",rep:"1 000",choix:["30", "999", "1 000", "10 000"],diff:3,hint:"Chaque molette a 10 positions possibles.",expl:"10 × 10 × 10 = 1 000 codes, de 000 à 999. On multiplie les possibilités de chaque molette."},
{id:"LG-5E-526",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Tournoi à élimination directe de 8 équipes (le perdant sort). Combien de matchs pour avoir un vainqueur ?",rep:"7",choix:["7", "8", "14", "28"],diff:4,hint:"Chaque match élimine exactement une équipe.",expl:"Il faut éliminer 7 équipes, et chaque match en élimine une : 7 matchs (4 + 2 + 1)."},
{id:"LG-5E-527",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Tiroir : 10 chaussettes blanches et 10 noires. Combien en prendre au minimum, dans le noir, pour être sûr d'avoir 2 noires ?",rep:"12",choix:["3", "11", "12", "20"],diff:4,hint:"Pense au pire cas : on tire d'abord toutes les blanches.",expl:"Au pire, on prend les 10 blanches d'abord. Il faut ensuite 2 noires : 10 + 2 = 12."},
{id:"LG-5E-528",classe:"5ème",cat:"🧠",type:"Logique",enonce:"La somme de deux nombres impairs est toujours…",rep:"paire",choix:["paire", "impaire", "un multiple de 4", "un nombre premier"],diff:2,hint:"Teste plusieurs exemples : 3 + 5, 7 + 9, 1 + 5…",expl:"Impair + impair = pair (ex. : 3 + 5 = 8). Ce n'est pas toujours un multiple de 4 : 1 + 5 = 6."},
{id:"LG-5E-529",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Ali, Béa et Cyril sont assis en ligne. Ali n'est pas tout à gauche. Cyril est tout à droite. Qui est au milieu ?",rep:"Ali",choix:["Ali", "Béa", "Cyril"],diff:2,hint:"Place d'abord Cyril, puis élimine les places impossibles pour Ali.",expl:"Cyril occupe la droite. Ali n'est pas à gauche, donc il est au milieu, et Béa est à gauche."},
{id:"LG-5E-530",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Mia, Noé et Zoé ont un chat, un chien ou un lapin. Mia n'a pas le chien, Noé a le lapin. Qui a le chien ?",rep:"Zoé",choix:["Mia", "Noé", "Zoé"],diff:2,hint:"Commence par placer l'information sûre sur Noé.",expl:"Noé a le lapin. Le chien ne peut être ni à Noé ni à Mia : c'est donc Zoé qui l'a."},
{id:"LG-5E-531",classe:"5ème",cat:"🧠",type:"Logique",enonce:"« Si je suis à Paris, alors je suis en France. » Tu es en France. Que peux-tu conclure ?",rep:"Rien de sûr sur Paris",choix:["Tu es à Paris", "Tu n'es pas à Paris", "Rien de sûr sur Paris", "Tu es près de Paris"],diff:3,hint:"On peut être en France sans être à Paris.",expl:"L'implication va de Paris vers la France, pas l'inverse. Être en France n'oblige pas à être à Paris : on ne peut pas conclure."},
{id:"LG-5E-532",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Quel est l'intrus : 3, 5, 7, 9, 11, 13 ?",rep:"9",choix:["5", "9", "11", "13"],diff:2,hint:"Cherche les diviseurs de chaque nombre.",expl:"3, 5, 7, 11 et 13 sont premiers. 9 = 3 × 3 n'est pas premier : c'est l'intrus."},
{id:"LG-5E-533",classe:"5ème",cat:"🧠",type:"Logique",enonce:"La moyenne de 3 notes est 12. Deux des notes sont 10 et 11. Quelle est la troisième ?",rep:"15",choix:["12", "13", "14", "15"],diff:3,hint:"Calcule d'abord la somme totale des 3 notes.",expl:"Somme = 3 × 12 = 36. Troisième note : 36 − 10 − 11 = 15."},
{id:"LG-5E-534",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Un réservoir est plein au quart. On ajoute 30 L, il est plein aux trois quarts. Quelle est sa capacité ?",rep:"60 L",choix:["40 L", "60 L", "90 L", "120 L"],diff:3,hint:"Quelle fraction du réservoir représentent les 30 L ajoutés ?",expl:"3/4 − 1/4 = 1/2 : les 30 L remplissent la moitié du réservoir. Capacité : 2 × 30 = 60 L."},
{id:"LG-5E-535",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Un seul dit vrai. A : « B ment. » B : « C ment. » C : « A et B mentent. » Qui dit vrai ?",rep:"B",choix:["A", "B", "C"],diff:4,hint:"Suppose qu'un seul dit vrai et vérifie que tout est cohérent.",expl:"Si B dit vrai, C ment et A ment (car B ne ment pas) : un seul dit vrai, c'est cohérent. Les autres hypothèses mènent à une contradiction."},
{id:"LG-5E-536",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Urne : 5 boules vertes et 3 rouges. Combien de rouges ajouter pour avoir autant de chances de tirer rouge que vert ?",rep:"2",choix:["1", "2", "3", "5"],diff:3,hint:"Les chances sont égales quand il y a autant de boules de chaque couleur.",expl:"Il faut 5 rouges pour égaler les 5 vertes : 5 − 3 = 2 boules rouges à ajouter."},
{id:"LG-5E-537",classe:"5ème",cat:"🧠",type:"Logique",enonce:"« Au plus 3 élèves sont absents. » Quelle situation est possible ?",rep:"3 élèves absents",choix:["3 élèves absents", "4 élèves absents", "5 élèves absents", "7 élèves absents"],diff:2,hint:"« Au plus 3 » veut dire « 3 ou moins ».",expl:"« Au plus 3 » signifie 0, 1, 2 ou 3 absents. 3 est donc autorisé, mais pas 4 ou plus."},
{id:"LG-5E-538",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Un nénuphar double de surface chaque jour et couvre tout l'étang le 20e jour. Quel jour en couvrait-il la moitié ?",rep:"Le 19e jour",choix:["Le 10e jour", "Le 15e jour", "Le 18e jour", "Le 19e jour"],diff:3,hint:"Raisonne à l'envers : que se passe-t-il la veille du 20e jour ?",expl:"La surface double chaque jour : la veille de l'étang couvert, il en couvrait la moitié, soit le 19e jour."},
{id:"LG-5E-539",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Dans une file, Sam est 7e en partant du début et 5e en partant de la fin. Combien de personnes dans la file ?",rep:"11",choix:["10", "11", "12", "13"],diff:3,hint:"Attention : Sam est compté dans les deux classements.",expl:"6 personnes devant Sam, 4 derrière, plus Sam : 6 + 4 + 1 = 11. Sinon, 7 + 5 − 1 = 11."},
{id:"LG-5E-540",classe:"5ème",cat:"🧠",type:"Logique",enonce:"Combien de fois écris-tu le chiffre 1 en écrivant tous les nombres de 1 à 20 ?",rep:"12",choix:["10", "11", "12", "13"],diff:4,hint:"N'oublie pas que 11 contient deux fois le chiffre 1.",expl:"1 et 10 : 2 fois ; 11 : 2 fois ; 12 à 19 : 8 fois. Total : 2 + 2 + 8 = 12."},
{id:"LG-4E-501",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Quelle est la réciproque de « Si un nombre finit par 0, alors il est pair » ?",rep:"Si un nombre est pair, il finit par 0",choix:["Si un nombre est pair, il finit par 0", "Si un nombre n'est pas pair, il ne finit pas par 0", "Si un nombre ne finit pas par 0, il est impair", "Si un nombre finit par 0, il est impair"],diff:3,hint:"La réciproque échange la condition et la conclusion.",expl:"« Si A, alors B » a pour réciproque « Si B, alors A ». Ici A = finir par 0 et B = être pair."},
{id:"LG-4E-502",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Quelle est la contraposée de « S'il pleut, alors le sol est mouillé » ?",rep:"Si le sol n'est pas mouillé, il ne pleut pas",choix:["Si le sol est mouillé, alors il pleut", "S'il ne pleut pas, le sol n'est pas mouillé", "Si le sol n'est pas mouillé, il ne pleut pas", "S'il pleut, le sol n'est pas mouillé"],diff:3,hint:"La contraposée échange et nie les deux parties.",expl:"« Si A, alors B » a pour contraposée « Si non B, alors non A ». Elle est toujours vraie quand la phrase de départ l'est."},
{id:"LG-4E-503",classe:"4ème",cat:"🧠",type:"Logique",enonce:"« Si un nombre est multiple de 4, il est pair. » La réciproque est-elle vraie ?",rep:"Non, 6 est un contre-exemple",choix:["Oui, toujours", "Oui, car 8 est pair et multiple de 4", "Non, 6 est un contre-exemple", "Non, 8 est un contre-exemple"],diff:3,hint:"Écris la réciproque, puis cherche un nombre pair particulier.",expl:"Réciproque : « tout nombre pair est multiple de 4 ». 6 est pair mais pas multiple de 4 : elle est fausse."},
{id:"LG-4E-504",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Suite : 3, 6, 12, 24, … Quel est le 8e terme ?",rep:"384",choix:["48", "192", "384", "768"],diff:3,hint:"Chaque terme est le double du précédent ; compte bien jusqu'au 8e.",expl:"On multiplie par 2 à chaque rang : 3 × 2⁷ = 3 × 128 = 384."},
{id:"LG-4E-505",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Suite : 2, 4, 8, 16, … Quel rang occupe le terme 1 024 ?",rep:"10e",choix:["9e", "10e", "11e", "12e"],diff:3,hint:"Le terme de rang n vaut 2 puissance n.",expl:"Le terme de rang n est 2ⁿ, et 2¹⁰ = 1 024 : c'est donc le 10e terme."},
{id:"LG-4E-506",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Suite : 0, 7, 26, 63, … Quel est le terme suivant ?",rep:"124",choix:["99", "100", "124", "125"],diff:4,hint:"Ajoute 1 à chaque terme : reconnais-tu ces nombres ?",expl:"Les termes valent n³ − 1 : 1 − 1, 8 − 1, 27 − 1, 64 − 1. Le suivant est 5³ − 1 = 125 − 1 = 124."},
{id:"LG-4E-507",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Le 1er terme vaut 2 ; chaque terme = double du précédent moins 1. Que vaut le 4e terme ?",rep:"9",choix:["7", "9", "15", "17"],diff:3,hint:"Calcule les termes un par un, sans sauter d'étape.",expl:"2 × 2 − 1 = 3, puis 3 × 2 − 1 = 5, puis 5 × 2 − 1 = 9. Le 4e terme est 9."},
{id:"LG-4E-508",classe:"4ème",cat:"🧠",type:"Logique",enonce:"On lance deux dés équilibrés. Quelle est la probabilité que la somme fasse 7 ?",rep:"1/6",choix:["1/12", "1/11", "1/6", "7/36"],diff:4,hint:"Il y a 6 × 6 = 36 issues. Liste les couples qui donnent 7.",expl:"Couples : (1;6), (2;5), (3;4), (4;3), (5;2), (6;1), soit 6 issues sur 36 = 1/6."},
{id:"LG-4E-509",classe:"4ème",cat:"🧠",type:"Logique",enonce:"La probabilité qu'un tireur rate la cible est 0,35. Quelle est la probabilité qu'il la touche ?",rep:"0,65",choix:["0,35", "0,55", "0,65", "0,75"],diff:2,hint:"Toucher et rater sont des événements contraires.",expl:"P(contraire) = 1 − P(événement) : 1 − 0,35 = 0,65."},
{id:"LG-4E-510",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Dé équilibré : quelle est la probabilité d'obtenir un nombre pair ou un 5 ?",rep:"2/3",choix:["1/6", "1/2", "2/3", "5/6"],diff:3,hint:"Liste toutes les faces qui conviennent.",expl:"Faces qui conviennent : 2, 4, 6 et 5, soit 4 sur 6 = 2/3."},
{id:"LG-4E-511",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Une roue : P(rouge) = 0,2 et P(bleu) = 0,5. Les autres cases sont vertes. Que vaut P(vert) ?",rep:"0,3",choix:["0,3", "0,5", "0,7", "0,8"],diff:2,hint:"La somme des probabilités de toutes les issues vaut 1.",expl:"1 − 0,2 − 0,5 = 0,3. La somme des probabilités de toutes les issues possibles est toujours égale à 1."},
{id:"LG-4E-512",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Une pièce équilibrée tombe 5 fois de suite sur face. Probabilité d'obtenir face au 6e lancer ?",rep:"1/2",choix:["1/64", "1/2", "Moins de 1/2", "Plus de 1/2"],diff:3,hint:"La pièce se souvient-elle des lancers précédents ?",expl:"Les lancers sont indépendants : la pièce n'a pas de mémoire. La probabilité reste 1/2 à chaque lancer."},
{id:"LG-4E-513",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Quelle phrase est vraie ?",rep:"Il existe un nombre premier pair",choix:["Tout nombre pair est multiple de 4", "Il existe un nombre premier pair", "Tout multiple de 3 est impair", "Aucun carré n'est pair"],diff:3,hint:"Cherche un contre-exemple pour chacune des phrases.",expl:"2 est premier et pair. Les autres sont fausses : 6 n'est pas multiple de 4, 6 est multiple de 3 et pair, 4 est un carré pair."},
{id:"LG-4E-514",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Quelle est la négation de « Léo a un vélo ET un skate » ?",rep:"Léo n'a pas de vélo ou pas de skate",choix:["Léo n'a ni vélo ni skate", "Léo n'a pas de vélo ou pas de skate", "Léo a un vélo mais pas de skate", "Léo a un skate mais pas de vélo"],diff:4,hint:"Il suffit qu'il manque l'un des deux pour que la phrase soit fausse.",expl:"« A et B » est faux dès que l'un manque. La négation de « A ET B » est « non A OU non B »."},
{id:"LG-4E-515",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Chevaliers : toujours vrai ; menteurs : toujours faux. A : « B est menteur. » B : « A et moi sommes pareils. » Qui est chevalier ?",rep:"A seulement",choix:["A seulement", "B seulement", "Les deux", "Aucun des deux"],diff:4,hint:"Suppose que A est menteur et cherche une contradiction.",expl:"Si A mentait, B serait chevalier et dirait vrai : ils seraient pareils, contradiction. Donc A est chevalier, B menteur, et B ment bien."},
{id:"LG-4E-516",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Combien de personnes faut-il au minimum pour être sûr que deux soient nées le même mois ?",rep:"13",choix:["12", "13", "24", "25"],diff:3,hint:"Il y a 12 mois. Imagine le pire cas.",expl:"Au pire, 12 personnes naissent chacune un mois différent. La 13e tombe forcément dans un mois déjà pris."},
{id:"LG-4E-517",classe:"4ème",cat:"🧠",type:"Logique",enonce:"n est un entier. Que peut-on dire de n × (n + 1) ?",rep:"Il est toujours pair",choix:["Il est toujours pair", "Il est toujours impair", "Il est pair seulement si n l'est", "Il est toujours multiple de 3"],diff:3,hint:"n et n + 1 sont deux entiers consécutifs.",expl:"Parmi deux entiers consécutifs, l'un est pair : leur produit est donc toujours pair."},
{id:"LG-4E-518",classe:"4ème",cat:"🧠",type:"Logique",enonce:"La somme de trois entiers consécutifs est toujours un multiple de…",rep:"3",choix:["2", "3", "4", "6"],diff:3,hint:"Écris les nombres n − 1, n et n + 1, puis additionne.",expl:"(n − 1) + n + (n + 1) = 3n : c'est toujours un multiple de 3. Exemple : 4 + 5 + 6 = 15."},
{id:"LG-4E-519",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Comment s'écrit le nombre 6 en binaire (base 2) ?",rep:"110",choix:["011", "101", "110", "111"],diff:3,hint:"Décompose 6 avec des puissances de 2 : 4, 2, 1.",expl:"6 = 4 + 2 = 1 × 4 + 1 × 2 + 0 × 1, donc 110 en binaire."},
{id:"LG-4E-520",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Programme : x = 1, puis répéter 4 fois « x = x × 3 ». Que vaut x à la fin ?",rep:"81",choix:["12", "27", "81", "243"],diff:3,hint:"Suis la valeur de x à chaque tour de boucle.",expl:"x devient 3, puis 9, puis 27, puis 81 : on a multiplié 4 fois par 3, soit 3⁴ = 81."},
{id:"LG-4E-521",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Programme : choisis un nombre, ajoute 3, multiplie par 2, retire 6. Que donne-t-il toujours ?",rep:"Le double du nombre choisi",choix:["Le nombre choisi", "Le double du nombre choisi", "Le nombre choisi plus 6", "Le triple du nombre choisi"],diff:3,hint:"Appelle x le nombre choisi et développe.",expl:"(x + 3) × 2 − 6 = 2x + 6 − 6 = 2x : le résultat est toujours le double du nombre choisi."},
{id:"LG-4E-522",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Avec les lettres A, B, C, D (répétitions permises), combien de « mots » de 3 lettres peut-on former ?",rep:"64",choix:["12", "24", "64", "81"],diff:3,hint:"Combien de choix pour chacune des 3 positions ?",expl:"4 choix pour chaque position : 4 × 4 × 4 = 64 mots."},
{id:"LG-4E-523",classe:"4ème",cat:"🧠",type:"Logique",enonce:"8 coureurs participent à une course. Combien de podiums (1er, 2e, 3e) différents sont possibles ?",rep:"336",choix:["24", "56", "336", "512"],diff:4,hint:"Combien de choix pour le 1er, puis le 2e, puis le 3e ?",expl:"8 choix pour le 1er, 7 pour le 2e, 6 pour le 3e : 8 × 7 × 6 = 336."},
{id:"LG-4E-524",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Combien de triangles ont pour sommets 3 des 5 sommets d'un pentagone ?",rep:"10",choix:["5", "10", "15", "20"],diff:4,hint:"Choisir 3 sommets revient à en écarter 2.",expl:"Choisir 3 sommets sur 5 revient à choisir les 2 écartés : 5 × 4 ÷ 2 = 10 triangles."},
{id:"LG-4E-525",classe:"4ème",cat:"🧠",type:"Logique",enonce:"J'ai le double de ton âge. Il y a 10 ans, j'avais le triple de ton âge. Quel âge ai-je ?",rep:"40 ans",choix:["30 ans", "40 ans", "50 ans", "60 ans"],diff:4,hint:"Appelle x ton âge et écris une équation, ou teste les réponses.",expl:"Avec x ton âge : 2x − 10 = 3(x − 10), donc x = 20. J'ai 40 ans ; il y a 10 ans : 30 = 3 × 10."},
{id:"LG-4E-526",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Une horloge retarde de 3 min par heure. Réglée à midi, quelle heure indique-t-elle à 20 h ?",rep:"19 h 36",choix:["19 h 24", "19 h 36", "19 h 57", "20 h 24"],diff:3,hint:"Combien d'heures se sont écoulées depuis midi ?",expl:"De 12 h à 20 h : 8 heures, donc 8 × 3 = 24 min de retard. Elle indique 20 h − 24 min = 19 h 36."},
{id:"LG-4E-527",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Un prix augmente de 10 %, puis encore de 10 %. Quelle est la hausse totale ?",rep:"21 %",choix:["11 %", "20 %", "21 %", "22 %"],diff:4,hint:"Pars d'un prix de 100 € et applique les deux hausses.",expl:"100 € → 110 € → 121 €. La 2e hausse s'applique au nouveau prix : la hausse totale est de 21 %."},
{id:"LG-4E-528",classe:"4ème",cat:"🧠",type:"Logique",enonce:"On suppose le contraire de ce qu'on veut prouver et on arrive à une contradiction. C'est un raisonnement…",rep:"par l'absurde",choix:["par l'absurde", "par analogie", "par contre-exemple", "par induction"],diff:2,hint:"On montre qu'une hypothèse mène à quelque chose d'impossible.",expl:"Le raisonnement par l'absurde suppose le contraire, aboutit à une contradiction, et conclut que l'affirmation de départ est vraie."},
{id:"LG-4E-529",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Pour prouver qu'une affirmation « pour tout nombre… » est fausse, il suffit de trouver…",rep:"un seul contre-exemple",choix:["un seul contre-exemple", "deux exemples qui marchent", "un exemple qui marche", "dix contre-exemples"],diff:2,hint:"Une règle générale doit marcher pour tous les nombres.",expl:"Une affirmation générale doit être vraie pour tous. Un seul cas où elle échoue (un contre-exemple) suffit à la réfuter."},
{id:"LG-4E-530",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Tout multiple de 6 est-il multiple de 3 ? Tout multiple de 3 est-il multiple de 6 ?",rep:"Oui ; non",choix:["Oui ; oui", "Oui ; non", "Non ; oui", "Non ; non"],diff:2,hint:"Teste avec 6, 12, puis avec 9 ou 15.",expl:"6 = 2 × 3, donc les multiples de 6 sont multiples de 3. Mais 9 est multiple de 3 sans être multiple de 6."},
{id:"LG-4E-531",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Maisons rouge, verte, bleue alignées. La verte est à droite de la rouge. La bleue n'est ni à gauche ni au milieu. Laquelle est au milieu ?",rep:"La verte",choix:["La rouge", "La verte", "La bleue"],diff:3,hint:"Place d'abord la maison bleue.",expl:"La bleue est à droite. La verte étant à droite de la rouge, la rouge est à gauche et la verte au milieu."},
{id:"LG-4E-532",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Une classe compte 12 filles et 18 garçons. On tire un élève au hasard. Probabilité que ce soit une fille ?",rep:"2/5",choix:["1/2", "2/5", "3/5", "2/3"],diff:2,hint:"Divise par le nombre total d'élèves, pas par le nombre de garçons.",expl:"12 filles sur 30 élèves : 12/30 = 2/5. Le dénominateur est toujours le nombre total d'issues."},
{id:"LG-4E-533",classe:"4ème",cat:"🧠",type:"Logique",enonce:"On lance une pièce puis un dé à 6 faces. Combien d'issues possibles en tout ?",rep:"12",choix:["6", "8", "12", "36"],diff:2,hint:"Pour chaque côté de la pièce, combien de résultats du dé ?",expl:"2 issues pour la pièce × 6 pour le dé = 12 issues possibles. On peut les visualiser avec un arbre."},
{id:"LG-4E-534",classe:"4ème",cat:"🧠",type:"Logique",enonce:"La phrase « A OU B » est fausse. Que sait-on ?",rep:"A et B sont faux tous les deux",choix:["A et B sont faux tous les deux", "A est vrai et B est faux", "Un seul des deux est faux", "On ne sait rien sur A et B"],diff:3,hint:"Quand un « OU » est-il vrai ?",expl:"« A OU B » est vrai dès qu'une des deux l'est. S'il est faux, c'est que A et B sont faux tous les deux."},
{id:"LG-4E-535",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Quelle implication est FAUSSE ?",rep:"Si x² = 9, alors x = 3",choix:["Si x = 3, alors x² = 9", "Si x² = 9, alors x = 3", "Si x = −3, alors x² = 9", "Si x = 3, alors 2x = 6"],diff:4,hint:"Pense aux nombres négatifs.",expl:"x² = 9 a deux solutions : 3 et −3. Avec x = −3, x² = 9 mais x n'est pas égal à 3 : l'implication est fausse."},
{id:"LG-4E-536",classe:"4ème",cat:"🧠",type:"Logique",enonce:"Par combien de zéros se termine le produit 1 × 2 × 3 × … × 10 ?",rep:"2",choix:["1", "2", "3", "10"],diff:4,hint:"Un zéro final vient d'un facteur 10 = 2 × 5. Compte les 5.",expl:"Les facteurs 5 viennent de 5 et 10 : deux 5, et assez de 2. Le produit, 3 628 800, finit par 2 zéros."},
{id:"LG-3E-501",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Suite : 7, 11, 15, 19… Quel est le 10e terme ?",rep:"43",choix:["43", "47", "39", "40"],diff:2,hint:"On ajoute toujours le même nombre : combien de fois du 1er au 10e ?",expl:"On ajoute 4 à chaque fois. Du 1er au 10e terme il y a 9 ajouts : 7 + 9 × 4 = 43."},
{id:"LG-3E-502",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Suite : 3, 6, 12, 24… Quel est le 8e terme ?",rep:"384",choix:["384", "192", "768", "256"],diff:3,hint:"Chaque terme est le double du précédent.",expl:"On multiplie par 2 à chaque fois : 8e terme = 3 × 2⁷ = 3 × 128 = 384."},
{id:"LG-3E-503",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Suite : 2, 5, 10, 17, 26… Quel est le terme suivant ?",rep:"37",choix:["37", "35", "36", "39"],diff:3,hint:"Compare chaque terme aux carrés 1, 4, 9, 16, 25…",expl:"Chaque terme vaut n² + 1 : 1+1, 4+1, 9+1, 16+1, 25+1, puis 36 + 1 = 37."},
{id:"LG-3E-504",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Suite : 1, 3, 7, 15, 31… Quel est le terme suivant ?",rep:"63",choix:["63", "62", "47", "61"],diff:3,hint:"Regarde le lien entre un terme et le double du précédent.",expl:"Chaque terme est le double du précédent plus 1 : 31 × 2 + 1 = 63."},
{id:"LG-3E-505",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Suite : 2, 3, 5, 7, 11, 13… Quel est le terme suivant ?",rep:"17",choix:["17", "15", "19", "16"],diff:2,hint:"Ces nombres n'ont que deux diviseurs : 1 et eux-mêmes.",expl:"C'est la suite des nombres premiers. Après 13, 14, 15 et 16 ne sont pas premiers : le suivant est 17."},
{id:"LG-3E-506",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Suite de lettres : B, E, H, K… Quelle lettre vient ensuite ?",rep:"N",choix:["N", "M", "O", "L"],diff:2,hint:"Compte combien de lettres on avance à chaque fois.",expl:"On avance de 3 lettres à chaque fois : K, L, M, N. La lettre suivante est N."},
{id:"LG-3E-507",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Suite : 1, −2, 4, −8… Quel est le terme suivant ?",rep:"16",choix:["16", "−16", "32", "−32"],diff:3,hint:"Par quel nombre multiplie-t-on à chaque étape ?",expl:"On multiplie par −2 à chaque fois : −8 × (−2) = 16, positif car moins par moins donne plus."},
{id:"LG-3E-508",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Combien de termes compte la suite 5, 8, 11, …, 62 ?",rep:"20",choix:["20", "19", "21", "18"],diff:4,hint:"Calcule le nombre de « pas » de 3 entre 5 et 62, puis pense au premier terme.",expl:"(62 − 5) ÷ 3 = 19 pas de 3, donc 19 + 1 = 20 termes : on n'oublie pas de compter le premier."},
{id:"LG-3E-509",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Combien vaut la somme 1 + 2 + 3 + … + 100 ?",rep:"5050",choix:["5050", "5000", "10100", "5100"],diff:3,hint:"Associe 1 et 100, 2 et 99, 3 et 98…",expl:"On forme 50 paires de somme 101 (1+100, 2+99…) : 50 × 101 = 5050. C'est l'astuce de Gauss."},
{id:"LG-3E-510",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Allumettes : 1 carré en utilise 4, 2 carrés en ligne 7, 3 carrés 10. Combien pour 10 carrés en ligne ?",rep:"31",choix:["31", "40", "30", "34"],diff:3,hint:"Chaque nouveau carré ajoute combien d'allumettes ?",expl:"Chaque carré ajouté demande 3 allumettes : 4 + 9 × 3 = 31, soit 3n + 1 allumettes pour n carrés."},
{id:"LG-3E-511",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Un dé équilibré est lancé. Quelle est la probabilité d'obtenir un nombre premier ?",rep:"1/2",choix:["1/2", "1/3", "2/3", "1/6"],diff:2,hint:"Liste les nombres premiers entre 1 et 6 (1 n'est pas premier).",expl:"Les nombres premiers du dé sont 2, 3 et 5 : 3 issues favorables sur 6, soit 3/6 = 1/2."},
{id:"LG-3E-512",classe:"3ème",cat:"🧠",type:"Logique",enonce:"On lance deux pièces équilibrées. Quelle est la probabilité d'obtenir deux fois face ?",rep:"1/4",choix:["1/4", "1/2", "1/3", "3/4"],diff:2,hint:"Écris toutes les issues possibles : PP, PF…",expl:"Il y a 4 issues équiprobables (PP, PF, FP, FF) et une seule est FF : probabilité 1/4."},
{id:"LG-3E-513",classe:"3ème",cat:"🧠",type:"Logique",enonce:"On lance deux dés équilibrés. Quelle est la probabilité que la somme fasse 7 ?",rep:"1/6",choix:["1/6", "1/12", "7/36", "1/11"],diff:3,hint:"Fais un tableau 6 × 6 et compte les cases de somme 7.",expl:"Il y a 36 issues et 6 donnent 7 : (1;6), (2;5), (3;4), (4;3), (5;2), (6;1). Donc 6/36 = 1/6."},
{id:"LG-3E-514",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Une urne contient 3 boules rouges et 5 bleues. Probabilité de ne PAS tirer une rouge ?",rep:"5/8",choix:["5/8", "3/8", "3/5", "1/2"],diff:2,hint:"Combien de boules au total ? Combien ne sont pas rouges ?",expl:"Il y a 8 boules dont 5 non rouges : 5/8. C'est aussi 1 − 3/8, la probabilité de l'événement contraire."},
{id:"LG-3E-515",classe:"3ème",cat:"🧠",type:"Logique",enonce:"On choisit une lettre au hasard dans le mot LOGIQUE. Probabilité que ce soit une voyelle ?",rep:"4/7",choix:["4/7", "3/7", "1/2", "5/7"],diff:2,hint:"Compte les lettres du mot, puis les voyelles.",expl:"LOGIQUE a 7 lettres dont 4 voyelles (O, I, U, E) : la probabilité est 4/7."},
{id:"LG-3E-516",classe:"3ème",cat:"🧠",type:"Logique",enonce:"On lance deux fois une pièce. Probabilité d'obtenir au moins une fois pile ?",rep:"3/4",choix:["3/4", "1/2", "1/4", "2/3"],diff:3,hint:"Pense à l'événement contraire : aucun pile.",expl:"Le contraire est « deux faces », de probabilité 1/4. Donc P(au moins un pile) = 1 − 1/4 = 3/4."},
{id:"LG-3E-517",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Une pièce équilibrée est tombée 5 fois de suite sur pile. Probabilité d'avoir pile au 6e lancer ?",rep:"1/2",choix:["1/2", "1/32", "1/64", "1/6"],diff:3,hint:"La pièce se souvient-elle des lancers précédents ?",expl:"Les lancers sont indépendants : la pièce n'a pas de mémoire. La probabilité reste 1/2 à chaque lancer."},
{id:"LG-3E-518",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Urne : 2 rouges, 1 bleue. On tire 2 boules AVEC remise. Probabilité d'avoir 2 rouges ?",rep:"4/9",choix:["4/9", "1/3", "2/3", "2/9"],diff:3,hint:"Avec remise, l'urne est identique au 2e tirage : multiplie les probabilités.",expl:"Avec remise, chaque tirage donne rouge avec 2/3. On multiplie le long de l'arbre : 2/3 × 2/3 = 4/9."},
{id:"LG-3E-519",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Urne : 2 rouges, 1 bleue. On tire 2 boules SANS remise. Probabilité d'avoir 2 rouges ?",rep:"1/3",choix:["1/3", "4/9", "2/9", "1/2"],diff:4,hint:"Au 2e tirage, il ne reste que 2 boules dont une seule rouge.",expl:"1er tirage rouge : 2/3. Il reste 1 rouge sur 2 boules : 1/2. Donc 2/3 × 1/2 = 1/3."},
{id:"LG-3E-520",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Quelle est la négation de « Il pleut et il fait froid » ?",rep:"Il ne pleut pas ou il ne fait pas froid",choix:["Il ne pleut pas ou il ne fait pas froid", "Il ne pleut pas et il ne fait pas froid", "Il pleut ou il fait froid", "Il ne pleut pas et il fait froid"],diff:3,hint:"Il suffit qu'une des deux conditions manque pour que la phrase soit fausse.",expl:"La phrase est fausse dès qu'une partie est fausse. La négation de « A et B » est « non A ou non B »."},
{id:"LG-3E-521",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Quelle est la négation de « Certains élèves aiment les maths » ?",rep:"Aucun élève n'aime les maths",choix:["Aucun élève n'aime les maths", "Certains élèves n'aiment pas les maths", "Tous les élèves aiment les maths", "Peu d'élèves aiment les maths"],diff:3,hint:"Dans quel cas la phrase de départ serait-elle fausse ?",expl:"« Certains » veut dire « au moins un ». La phrase est fausse seulement si personne n'aime les maths : aucun élève."},
{id:"LG-3E-522",classe:"3ème",cat:"🧠",type:"Logique",enonce:"« Tout nombre premier est impair. » Quel nombre est un contre-exemple ?",rep:"2",choix:["2", "9", "1", "15"],diff:2,hint:"Cherche un nombre premier qui n'est pas impair.",expl:"2 est premier (diviseurs 1 et 2) et pair : il prouve que l'affirmation est fausse. 9 et 15 ne sont pas premiers, 1 non plus."},
{id:"LG-3E-523",classe:"3ème",cat:"🧠",type:"Logique",enonce:"« Si un nombre est divisible par 6, il l'est par 3. » Quel nombre prouve que la réciproque est fausse ?",rep:"9",choix:["9", "12", "18", "6"],diff:3,hint:"La réciproque dit : divisible par 3 ⇒ divisible par 6.",expl:"9 est divisible par 3 mais pas par 6 : la réciproque est fausse. 6, 12 et 18 sont divisibles par les deux."},
{id:"LG-3E-524",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Quelle est la réciproque de « Si je suis à Paris, alors je suis en France » ?",rep:"Si je suis en France, alors je suis à Paris",choix:["Si je suis en France, alors je suis à Paris", "Si je ne suis pas en France, je ne suis pas à Paris", "Si je ne suis pas à Paris, je ne suis pas en France", "Je suis à Paris et je suis en France"],diff:3,hint:"La réciproque échange la condition et la conséquence.",expl:"La réciproque de « si A alors B » est « si B alors A ». Ici elle est fausse : on peut être à Lyon."},
{id:"LG-3E-525",classe:"3ème",cat:"🧠",type:"Logique",enonce:"« S'il pleut, le sol est mouillé. » Le sol est mouillé. Que peut-on conclure ?",rep:"On ne peut pas savoir s'il a plu",choix:["On ne peut pas savoir s'il a plu", "Il a forcément plu", "Il n'a sûrement pas plu", "Il pleut encore"],diff:3,hint:"Le sol pourrait-il être mouillé pour une autre raison ?",expl:"« Si A alors B » ne dit pas que B entraîne A. Le sol peut être mouillé par un arrosage : impossible de conclure."},
{id:"LG-3E-526",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Quelle affirmation est vraie ?",rep:"Tout carré est un losange",choix:["Tout carré est un losange", "Tout losange est un carré", "Tout rectangle est un carré", "Tout parallélogramme est un rectangle"],diff:2,hint:"Un carré a 4 côtés égaux : quelle figure exige seulement cela ?",expl:"Un losange a 4 côtés égaux ; un carré les a aussi, donc c'est un losange. L'inverse est faux : un losange n'a pas forcément d'angle droit."},
{id:"LG-3E-527",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Un père a 40 ans et son fils 10 ans. Dans combien d'années le père aura-t-il le double de l'âge du fils ?",rep:"20",choix:["20", "10", "15", "30"],diff:3,hint:"Écris 40 + x = 2 × (10 + x).",expl:"40 + x = 2(10 + x) donne 40 + x = 20 + 2x, donc x = 20. Vérification : 60 ans = 2 × 30 ans."},
{id:"LG-3E-528",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Dans une ferme, 10 animaux (poules et lapins) ont 28 pattes. Combien y a-t-il de lapins ?",rep:"4",choix:["4", "6", "5", "3"],diff:3,hint:"Imagine que tous sont des poules : combien de pattes manque-t-il ?",expl:"Si les 10 étaient des poules : 20 pattes. Il manque 8 pattes, chaque lapin en ajoute 2 : 4 lapins (16 + 12 = 28)."},
{id:"LG-3E-529",classe:"3ème",cat:"🧠",type:"Logique",enonce:"La somme des âges de deux sœurs est 20 ans et leur différence 4 ans. Quel âge a l'aînée ?",rep:"12",choix:["12", "16", "10", "14"],diff:2,hint:"Ajoute la somme et la différence, puis partage en deux.",expl:"Aînée = (20 + 4) ÷ 2 = 12 ans, cadette = 8 ans. Vérification : 12 + 8 = 20 et 12 − 8 = 4."},
{id:"LG-3E-530",classe:"3ème",cat:"🧠",type:"Logique",enonce:"6 personnes se serrent toutes la main une seule fois. Combien de poignées de main ?",rep:"15",choix:["15", "30", "36", "12"],diff:3,hint:"Chacun serre 5 mains, mais chaque poignée concerne 2 personnes.",expl:"6 × 5 = 30 compte chaque poignée deux fois. Donc 30 ÷ 2 = 15 poignées de main."},
{id:"LG-3E-531",classe:"3ème",cat:"🧠",type:"Logique",enonce:"8 coureurs sont en finale. Combien de podiums différents (1er, 2e, 3e) sont possibles ?",rep:"336",choix:["336", "24", "512", "56"],diff:4,hint:"8 choix pour l'or, puis combien pour l'argent ? et le bronze ?",expl:"8 choix pour la 1re place, 7 pour la 2e, 6 pour la 3e : 8 × 7 × 6 = 336 podiums."},
{id:"LG-3E-532",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Avec les chiffres 1, 2, 3, 4, combien de nombres à 2 chiffres DIFFÉRENTS peut-on écrire ?",rep:"12",choix:["12", "16", "8", "6"],diff:3,hint:"4 choix pour les dizaines, puis combien pour les unités ?",expl:"4 choix pour les dizaines puis 3 pour les unités (chiffre différent) : 4 × 3 = 12 nombres."},
{id:"LG-3E-533",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Le 1er janvier d'une année non bissextile est un lundi. Quel jour est le 1er mars ?",rep:"jeudi",choix:["jeudi", "mercredi", "vendredi", "mardi"],diff:4,hint:"Compte les jours de janvier et février, puis le reste de la division par 7.",expl:"Il y a 31 + 28 = 59 jours entre les deux dates. 59 = 8 × 7 + 3 : lundi + 3 jours = jeudi."},
{id:"LG-3E-534",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Aujourd'hui, c'est mercredi. Quel jour serons-nous dans 100 jours ?",rep:"vendredi",choix:["vendredi", "jeudi", "samedi", "mercredi"],diff:3,hint:"Les jours reviennent tous les 7 jours : cherche le reste de 100 ÷ 7.",expl:"100 = 14 × 7 + 2. Après 14 semaines on retombe sur mercredi, puis 2 jours de plus : vendredi."},
{id:"LG-3E-535",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Les chevaliers disent toujours vrai, les fripons mentent toujours. A dit : « B et moi sommes tous les deux fripons. » Que sont A et B ?",rep:"A fripon, B chevalier",choix:["A fripon, B chevalier", "A chevalier, B fripon", "Deux fripons", "Deux chevaliers"],diff:4,hint:"Un chevalier pourrait-il dire « je suis un fripon » ?",expl:"Un chevalier ne peut pas se dire fripon : A ment, donc A est fripon. Sa phrase est fausse : ils ne sont pas deux fripons, B est chevalier."},
{id:"LG-3E-536",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Un prix augmente de 10 %, puis baisse de 10 %. Par rapport au prix de départ, il…",rep:"baisse de 1 %",choix:["baisse de 1 %", "ne change pas", "augmente de 1 %", "baisse de 10 %"],diff:3,hint:"Essaie avec un prix de 100 €.",expl:"100 € × 1,1 = 110 €, puis 110 € × 0,9 = 99 €. Les 10 % de baisse portent sur un prix plus grand : −1 %."},
{id:"LG-3E-537",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Aller à 60 km/h, retour à 30 km/h sur la même route. Quelle est la vitesse moyenne sur le trajet total ?",rep:"40 km/h",choix:["40 km/h", "45 km/h", "50 km/h", "35 km/h"],diff:4,hint:"Prends une distance de 60 km et calcule le temps total.",expl:"Pour 60 km : 1 h à l'aller, 2 h au retour. 120 km en 3 h donne 40 km/h, et non la moyenne 45."},
{id:"LG-3E-538",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Combien de nombres différents peut-on coder avec 4 bits (chiffres 0 ou 1) ?",rep:"16",choix:["16", "8", "4", "15"],diff:3,hint:"Chaque bit a 2 valeurs : multiplie pour les 4 bits.",expl:"2 × 2 × 2 × 2 = 2⁴ = 16 codes différents, de 0000 à 1111 (soit les nombres 0 à 15)."},
{id:"LG-3E-539",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Le produit de trois entiers consécutifs est toujours divisible par…",rep:"6",choix:["6", "4", "5", "9"],diff:4,hint:"Parmi trois entiers qui se suivent, y a-t-il toujours un pair ? un multiple de 3 ?",expl:"Parmi 3 entiers consécutifs, il y a un pair et un multiple de 3 : le produit est divisible par 6. 1 × 2 × 3 = 6 exclut 4, 5, 9."},
{id:"LG-3E-540",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Programme : choisir un nombre, ajouter 3, multiplier par 2, enlever 6. On obtient toujours…",rep:"le double du nombre",choix:["le double du nombre", "le nombre de départ", "le triple du nombre", "le double plus 3"],diff:3,hint:"Appelle x le nombre et développe.",expl:"(x + 3) × 2 − 6 = 2x + 6 − 6 = 2x : on obtient toujours le double du nombre choisi."},
{id:"LG-3E-541",classe:"3ème",cat:"🧠",type:"Logique",enonce:"On part de 5 et on répète 3 fois : « multiplier par 2 puis enlever 1 ». Quel résultat obtient-on ?",rep:"33",choix:["33", "27", "37", "17"],diff:3,hint:"Fais les trois étapes une par une.",expl:"5 → 9 → 17 → 33 : à chaque tour on double puis on retire 1."},
{id:"LG-3E-542",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Classe de 30 élèves : 18 font du foot, 15 du basket, 7 les deux. Combien ne font aucun des deux ?",rep:"4",choix:["4", "3", "7", "0"],diff:3,hint:"Les 7 élèves qui font les deux sont comptés deux fois.",expl:"18 + 15 − 7 = 26 élèves font au moins un sport. Il reste 30 − 26 = 4 élèves."},
{id:"LG-3E-543",classe:"3ème",cat:"🧠",type:"Logique",enonce:"24 billes rouges et 36 bleues sont réparties en paquets identiques, sans reste. Combien de paquets au maximum ?",rep:"12",choix:["12", "6", "4", "60"],diff:3,hint:"Cherche le plus grand diviseur commun à 24 et 36.",expl:"Le nombre de paquets doit diviser 24 et 36 : le maximum est leur PGCD, 12 (paquets de 2 rouges et 3 bleues)."},
{id:"LG-3E-544",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Un tiroir contient 10 chaussettes noires et 10 blanches. Dans le noir, combien en prendre pour être sûr d'avoir une paire ?",rep:"3",choix:["3", "2", "11", "4"],diff:3,hint:"Imagine le pire cas pour les deux premières chaussettes.",expl:"Au pire, les 2 premières sont de couleurs différentes. La 3e est forcément noire ou blanche : elle forme une paire."},
{id:"LG-3E-545",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Combien de personnes faut-il au minimum pour être SÛR que deux sont nées le même mois ?",rep:"13",choix:["13", "12", "24", "7"],diff:3,hint:"Il y a 12 mois : imagine que chacun soit né un mois différent.",expl:"Avec 12 personnes, chacune peut avoir son mois. La 13e tombe forcément dans un mois déjà pris : principe des tiroirs."},
{id:"LG-3E-546",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Parmi 9 pièces, une est plus lourde. Combien de pesées au minimum sur une balance à plateaux pour la trouver ?",rep:"2",choix:["2", "3", "4", "1"],diff:4,hint:"Fais 3 groupes de 3 pièces.",expl:"On compare deux groupes de 3 : on sait quel groupe contient la lourde. Puis on compare 2 pièces de ce groupe : 2 pesées."},
{id:"LG-3E-547",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Quel est le chiffre des unités de 7¹⁰⁰ ?",rep:"1",choix:["1", "7", "9", "3"],diff:4,hint:"Regarde les unités de 7¹, 7², 7³, 7⁴… elles se répètent.",expl:"Les unités suivent le cycle 7, 9, 3, 1 de longueur 4. 100 est multiple de 4, donc 7¹⁰⁰ se termine par 1."},
{id:"LG-3E-548",classe:"3ème",cat:"🧠",type:"Logique",enonce:"Combien de diagonales possède un hexagone (6 côtés) ?",rep:"9",choix:["9", "6", "12", "18"],diff:4,hint:"De chaque sommet partent des diagonales vers les sommets non voisins.",expl:"Chaque sommet est relié à 3 sommets non voisins : 6 × 3 = 18, compté deux fois, donc 9 diagonales."},
{id:"LG-LY-501",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Suite arithmétique : u₀ = 3 et raison 5. Combien vaut u₂₀ ?",rep:"103",choix:["103", "100", "108", "98"],diff:2,hint:"Pour une suite arithmétique, uₙ = u₀ + n × r.",expl:"uₙ = u₀ + n × r, donc u₂₀ = 3 + 20 × 5 = 103."},
{id:"LG-LY-502",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Suite géométrique : u₀ = 2 et raison 3. Combien vaut u₄ ?",rep:"162",choix:["162", "54", "486", "24"],diff:2,hint:"Pour une suite géométrique, uₙ = u₀ × qⁿ.",expl:"uₙ = u₀ × qⁿ, donc u₄ = 2 × 3⁴ = 2 × 81 = 162."},
{id:"LG-LY-503",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Suite arithmétique avec u₃ = 10 et u₇ = 22. Quelle est sa raison ?",rep:"3",choix:["3", "4", "12", "2"],diff:3,hint:"Entre u₃ et u₇, combien de fois ajoute-t-on la raison ?",expl:"De u₃ à u₇ on ajoute 4 fois la raison : 22 − 10 = 12 = 4r, donc r = 3."},
{id:"LG-LY-504",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Combien vaut 1 + 2 + 4 + 8 + … + 2⁹ ?",rep:"1023",choix:["1023", "1024", "512", "2047"],diff:3,hint:"Calcule 1 + 2, 1 + 2 + 4, 1 + 2 + 4 + 8… et compare aux puissances de 2.",expl:"Somme géométrique : 1 + 2 + … + 2⁹ = (2¹⁰ − 1)/(2 − 1) = 1024 − 1 = 1023."},
{id:"LG-LY-505",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Combien vaut la somme des nombres impairs 1 + 3 + 5 + … + 99 ?",rep:"2500",choix:["2500", "2450", "5000", "2550"],diff:3,hint:"1 = 1², 1 + 3 = 2², 1 + 3 + 5 = 3²…",expl:"Il y a 50 impairs de 1 à 99, et la somme des n premiers impairs vaut n² : 50² = 2500."},
{id:"LG-LY-506",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"u₀ = 0 et uₙ₊₁ = uₙ + 2n + 1. Combien vaut u₅ ?",rep:"25",choix:["25", "36", "16", "30"],diff:3,hint:"Calcule u₁, u₂, u₃ et observe.",expl:"On obtient 0, 1, 4, 9, 16, 25 : uₙ = n², car (n + 1)² = n² + 2n + 1. Donc u₅ = 25."},
{id:"LG-LY-507",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"u₀ = 3 et uₙ₊₁ = 2uₙ − 1. Combien vaut u₃ ?",rep:"17",choix:["17", "9", "33", "15"],diff:2,hint:"Calcule les termes un par un.",expl:"u₁ = 2 × 3 − 1 = 5, u₂ = 2 × 5 − 1 = 9, u₃ = 2 × 9 − 1 = 17."},
{id:"LG-LY-508",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Laquelle de ces suites est arithmétique ?",rep:"uₙ = 3n − 2",choix:["uₙ = 3n − 2", "uₙ = n²", "uₙ = 2ⁿ", "uₙ = 1/(n + 1)"],diff:2,hint:"Cherche celle où uₙ₊₁ − uₙ est constant.",expl:"uₙ₊₁ − uₙ = 3(n + 1) − 2 − (3n − 2) = 3, constant : suite arithmétique de raison 3."},
{id:"LG-LY-509",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"1000 € placés à 2 % d'intérêts composés par an. Quelle suite modélise le capital ?",rep:"géométrique de raison 1,02",choix:["géométrique de raison 1,02", "arithmétique de raison 20", "géométrique de raison 0,02", "arithmétique de raison 1,02"],diff:3,hint:"Augmenter de 2 %, c'est multiplier par combien ?",expl:"Chaque année le capital est multiplié par 1 + 2/100 = 1,02 : c'est une suite géométrique de raison 1,02."},
{id:"LG-LY-510",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"500 € placés à 3 % d'intérêts simples (calculés sur 500 € chaque année). Quelle suite modélise le capital ?",rep:"arithmétique de raison 15",choix:["arithmétique de raison 15", "géométrique de raison 1,03", "arithmétique de raison 3", "géométrique de raison 15"],diff:3,hint:"Les intérêts annuels sont-ils toujours les mêmes ?",expl:"Chaque année on ajoute 3 % de 500 €, soit 15 € fixes : on ajoute une constante, suite arithmétique de raison 15."},
{id:"LG-LY-511",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Une valeur de 1000 baisse de 10 % par an. Au bout de combien d'années passe-t-elle sous 500 ?",rep:"7",choix:["7", "6", "5", "8"],diff:4,hint:"Calcule 0,9ⁿ pour n = 5, 6, 7.",expl:"On cherche 0,9ⁿ < 0,5. 0,9⁶ ≈ 0,531 et 0,9⁷ ≈ 0,478 : c'est au bout de 7 ans."},
{id:"LG-LY-512",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Une feuille de 0,1 mm d'épaisseur est pliée en deux 10 fois. Quelle épaisseur obtient-on ?",rep:"environ 10 cm",choix:["environ 10 cm", "environ 1 cm", "environ 2 mm", "environ 1 m"],diff:3,hint:"Chaque pliage double l'épaisseur : calcule 2¹⁰.",expl:"L'épaisseur est multipliée par 2¹⁰ = 1024 : 0,1 × 1024 ≈ 102 mm, soit environ 10 cm."},
{id:"LG-LY-513",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Une population de bactéries double toutes les 20 minutes. Par combien est-elle multipliée en 2 heures ?",rep:"64",choix:["64", "6", "12", "32"],diff:3,hint:"Combien de périodes de 20 min dans 2 heures ?",expl:"2 h = 6 périodes de 20 min. On double 6 fois : 2⁶ = 64."},
{id:"LG-LY-514",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"1 + 1/2 + 1/4 + 1/8 + … : quand on ajoute de plus en plus de termes, la somme s'approche de…",rep:"2",choix:["2", "1", "1,5", "l'infini"],diff:3,hint:"Il manque toujours un peu pour atteindre une valeur : laquelle ?",expl:"1 + 1/2 + … + 1/2ⁿ = 2 − 1/2ⁿ. Il manque 1/2ⁿ, qui devient minuscule : la somme s'approche de 2 sans le dépasser."},
{id:"LG-LY-515",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Échiquier : 1 grain sur la 1re case, puis on double à chaque case. Combien de grains au total sur 64 cases ?",rep:"2⁶⁴ − 1",choix:["2⁶⁴ − 1", "2⁶⁴", "64²", "2⁶³"],diff:3,hint:"Pour 2 cases : 1 + 2 = 3 = 2² − 1. Pour 3 cases ?",expl:"Somme géométrique : 1 + 2 + … + 2⁶³ = 2⁶⁴ − 1. La dernière case à elle seule contient 2⁶³ grains."},
{id:"LG-LY-516",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Syracuse : si n est pair on le divise par 2, sinon on fait 3n + 1. Partant de 6, combien d'étapes pour atteindre 1 ?",rep:"8",choix:["8", "7", "9", "6"],diff:3,hint:"Écris la suite : 6, 3, 10…",expl:"6 → 3 → 10 → 5 → 16 → 8 → 4 → 2 → 1 : il faut 8 étapes."},
{id:"LG-LY-517",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"On monte un escalier de 5 marches, 1 ou 2 marches à la fois. Combien de façons différentes ?",rep:"8",choix:["8", "5", "10", "13"],diff:4,hint:"Pour n marches, le dernier pas fait 1 ou 2 marches.",expl:"Le nombre de façons pour n marches = façons pour n − 1 + pour n − 2 : 1, 2, 3, 5, 8. Pour 5 marches : 8."},
{id:"LG-LY-518",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"A et B : P(A ∩ B) = 0,12 et P(A) = 0,4. Que vaut la probabilité de B sachant A ?",rep:"0,3",choix:["0,3", "0,048", "0,52", "0,28"],diff:3,hint:"P_A(B) = P(A ∩ B) ÷ P(A).",expl:"P_A(B) = P(A ∩ B) / P(A) = 0,12 / 0,4 = 0,3."},
{id:"LG-LY-519",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"A et B sont indépendants, P(A) = 0,5 et P(B) = 0,4. Que vaut P(A ∩ B) ?",rep:"0,2",choix:["0,2", "0,9", "0,1", "0,45"],diff:2,hint:"Pour des événements indépendants, on multiplie.",expl:"A et B indépendants ⇔ P(A ∩ B) = P(A) × P(B) = 0,5 × 0,4 = 0,2."},
{id:"LG-LY-520",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"P(A) = 0,5, P(B) = 0,4 et P(A ∩ B) = 0,1. Que vaut P(A ∪ B) ?",rep:"0,8",choix:["0,8", "0,9", "0,7", "0,2"],diff:2,hint:"Si on additionne P(A) et P(B), on compte A ∩ B deux fois.",expl:"P(A ∪ B) = P(A) + P(B) − P(A ∩ B) = 0,5 + 0,4 − 0,1 = 0,8."},
{id:"LG-LY-521",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Arbre : P(A) = 0,3 ; P_A(B) = 0,5 ; P_Ā(B) = 0,2. Que vaut P(B) ?",rep:"0,29",choix:["0,29", "0,7", "0,35", "0,15"],diff:3,hint:"Additionne les chemins de l'arbre qui mènent à B.",expl:"Probabilités totales : P(B) = 0,3 × 0,5 + 0,7 × 0,2 = 0,15 + 0,14 = 0,29."},
{id:"LG-LY-522",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Deux événements A et B sont dits incompatibles lorsque…",rep:"A ∩ B = ∅",choix:["A ∩ B = ∅", "P(A ∩ B) = P(A) × P(B)", "A ∪ B = Ω", "P(A) = P(B)"],diff:2,hint:"Incompatibles : peuvent-ils se produire en même temps ?",expl:"Incompatibles signifie qu'ils ne peuvent pas se réaliser ensemble : leur intersection est vide. Ne pas confondre avec indépendants."},
{id:"LG-LY-523",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"On tire une carte dans un jeu de 32. A : « as », B : « cœur ». A et B sont-ils indépendants ?",rep:"Oui, car P(A ∩ B) = P(A) × P(B)",choix:["Oui, car P(A ∩ B) = P(A) × P(B)", "Non, car l'as de cœur est dans les deux", "Non, car ils ne sont pas incompatibles", "Oui, car ils sont incompatibles"],diff:4,hint:"Calcule P(A), P(B) et P(A ∩ B) (l'as de cœur).",expl:"P(A) = 4/32 = 1/8, P(B) = 8/32 = 1/4, P(A ∩ B) = 1/32 = 1/8 × 1/4 : ils sont indépendants."},
{id:"LG-LY-524",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"1 % de la population est malade. Le test est positif pour 99 % des malades et pour 1 % des personnes saines. Testé positif : probabilité d'être malade ?",rep:"50 %",choix:["50 %", "99 %", "1 %", "90 %"],diff:4,hint:"Sur 10 000 personnes, compte les vrais et les faux positifs.",expl:"Sur 10 000 : 100 malades dont 99 positifs ; 9 900 sains dont 99 faux positifs. Parmi 198 positifs, 99 sont malades : 50 %."},
{id:"LG-LY-525",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Jeu télévisé : 3 portes, 1 voiture. Tu choisis, l'animateur ouvre une porte perdante. Si tu changes, ta chance de gagner est…",rep:"2/3",choix:["2/3", "1/2", "1/3", "1"],diff:4,hint:"Quelle est la probabilité que ton premier choix soit perdant ?",expl:"Ton premier choix est perdant avec probabilité 2/3 ; dans ce cas, changer fait gagner à coup sûr. Changer gagne donc 2 fois sur 3."},
{id:"LG-LY-526",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Une famille a deux enfants, dont au moins un garçon. Probabilité que les deux soient des garçons ?",rep:"1/3",choix:["1/3", "1/2", "1/4", "2/3"],diff:4,hint:"Liste les cas GG, GF, FG, FF et élimine celui qui est exclu.",expl:"Restent 3 cas équiprobables : GG, GF, FG. Un seul a deux garçons : 1/3."},
{id:"LG-LY-527",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Dans un groupe de 23 personnes, la probabilité qu'au moins deux aient le même anniversaire est d'environ…",rep:"50 %",choix:["50 %", "6 %", "23 %", "90 %"],diff:4,hint:"Compte les paires de personnes possibles : il y en a 253.",expl:"Avec 23 personnes il y a 253 paires possibles. La probabilité que tous les anniversaires diffèrent tombe à environ 49 %, donc environ 50 % pour une coïncidence."},
{id:"LG-LY-528",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"On lance 3 pièces équilibrées. Probabilité d'obtenir exactement 2 piles ?",rep:"3/8",choix:["3/8", "1/2", "2/3", "1/4"],diff:3,hint:"Il y a 8 issues ; lesquelles ont exactement 2 piles ?",expl:"8 issues équiprobables ; PPF, PFP, FPP ont exactement 2 piles : probabilité 3/8."},
{id:"LG-LY-529",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"On lance un dé 4 fois. Quelle est la probabilité d'obtenir au moins un 6 ?",rep:"1 − (5/6)⁴",choix:["1 − (5/6)⁴", "4/6", "(1/6)⁴", "1 − (1/6)⁴"],diff:3,hint:"Passe par l'événement contraire : aucun 6.",expl:"« Aucun 6 » a pour probabilité (5/6)⁴ car les lancers sont indépendants. Donc P(au moins un 6) = 1 − (5/6)⁴ ≈ 0,52."},
{id:"LG-LY-530",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"On tire 2 cartes sans remise dans un jeu de 32. Probabilité d'avoir 2 as ?",rep:"3/248",choix:["3/248", "1/64", "1/8", "3/256"],diff:4,hint:"Au 2e tirage, il reste 3 as parmi 31 cartes.",expl:"4/32 pour le premier as, puis 3/31 : 4/32 × 3/31 = 12/992 = 3/248."},
{id:"LG-LY-531",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Un code de 4 chiffres. En essayant 3 codes différents au hasard, probabilité de trouver le bon ?",rep:"3/10000",choix:["3/10000", "1/10000", "3/1000", "1/3"],diff:3,hint:"Combien de codes à 4 chiffres existe-t-il ?",expl:"Il y a 10⁴ = 10 000 codes équiprobables. 3 essais différents couvrent 3 codes : 3/10 000."},
{id:"LG-LY-532",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Un point est choisi au hasard dans un carré de côté 2. Probabilité qu'il soit dans le disque inscrit ?",rep:"π/4",choix:["π/4", "1/2", "π/2", "3/4"],diff:4,hint:"Compare l'aire du disque de rayon 1 à l'aire du carré.",expl:"Aire du disque : π × 1² = π. Aire du carré : 4. Probabilité = π/4 ≈ 0,785."},
{id:"LG-LY-533",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"X est le résultat d'un dé équilibré à 6 faces. Quelle est l'espérance de X ?",rep:"3,5",choix:["3,5", "3", "4", "2,5"],diff:2,hint:"Fais la moyenne des valeurs pondérée par leurs probabilités.",expl:"E(X) = (1 + 2 + 3 + 4 + 5 + 6) × 1/6 = 21/6 = 3,5."},
{id:"LG-LY-534",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Dé : tu gagnes 6 € si tu fais 6, sinon tu perds 1 €. Quelle est l'espérance de gain ?",rep:"1/6 €",choix:["1/6 €", "−1/6 €", "5/6 €", "0 €"],diff:3,hint:"E = gain × probabilité + perte × probabilité.",expl:"E = 6 × 1/6 + (−1) × 5/6 = 6/6 − 5/6 = 1/6 € par partie : le jeu est favorable au joueur."},
{id:"LG-LY-535",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Loterie : 100 billets à 2 €, un lot de 100 € et deux lots de 20 €. Espérance du gain net d'un billet ?",rep:"−0,60 €",choix:["−0,60 €", "1,40 €", "−2 €", "0 €"],diff:4,hint:"Calcule l'espérance des lots, puis retire le prix du billet.",expl:"Lots : (100 + 20 + 20)/100 = 1,40 € en moyenne. Gain net : 1,40 − 2 = −0,60 €."},
{id:"LG-LY-536",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Échantillon de taille 100 : de combien la fréquence s'écarte-t-elle au plus de p, dans environ 95 % des cas ?",rep:"0,1",choix:["0,1", "0,01", "0,05", "0,2"],diff:3,hint:"La marge vaut environ 1/√n.",expl:"Dans environ 95 % des échantillons, la fréquence est à moins de 1/√n de p : 1/√100 = 0,1."},
{id:"LG-LY-537",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Combien d'anagrammes (mots possibles, même sans sens) peut-on former avec MATHS ?",rep:"120",choix:["120", "25", "60", "3125"],diff:3,hint:"5 lettres distinctes : 5 choix pour la 1re place, puis…",expl:"5 lettres différentes : 5 × 4 × 3 × 2 × 1 = 5! = 120 anagrammes."},
{id:"LG-LY-538",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Combien d'anagrammes différentes peut-on former avec le mot ANNA ?",rep:"6",choix:["6", "24", "12", "4"],diff:4,hint:"Échanger les deux A ne crée pas un nouveau mot.",expl:"4! = 24 permutations, mais échanger les 2 A ou les 2 N ne change rien : 24 ÷ (2 × 2) = 6."},
{id:"LG-LY-539",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Combien de sous-ensembles (vide compris) a un ensemble de 5 éléments ?",rep:"32",choix:["32", "25", "120", "10"],diff:3,hint:"Pour chaque élément : on le prend ou pas.",expl:"Chaque élément est pris ou non : 2 choix pour chacun des 5, soit 2⁵ = 32 sous-ensembles."},
{id:"LG-LY-540",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Combien de façons de choisir 2 délégués (sans ordre) dans une classe de 30 ?",rep:"435",choix:["435", "870", "60", "900"],diff:3,hint:"Compte avec un ordre, puis divise par le nombre d'ordres possibles.",expl:"Avec ordre : 30 × 29 = 870. Chaque paire est comptée 2 fois : 870 ÷ 2 = 435."},
{id:"LG-LY-541",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"De (0;0) à (3;2), en ne faisant que des pas d'une unité vers la droite ou vers le haut, combien de chemins ?",rep:"10",choix:["10", "6", "5", "32"],diff:4,hint:"Un chemin = 5 pas dont 2 vers le haut : où les placer ?",expl:"Chaque chemin a 5 pas dont 2 vers le haut. Choisir leurs 2 places parmi 5 : (5 × 4) ÷ 2 = 10 chemins."},
{id:"LG-LY-542",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"8 équipes ; chacune joue 2 fois (aller et retour) contre chaque autre. Combien de matchs ?",rep:"56",choix:["56", "28", "64", "16"],diff:3,hint:"Chaque équipe reçoit chacune des 7 autres une fois.",expl:"Chaque équipe reçoit les 7 autres : 8 × 7 = 56 matchs (28 paires, jouées 2 fois)."},
{id:"LG-LY-543",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Tournoi à élimination directe avec 32 équipes. Combien de matchs faut-il pour désigner le vainqueur ?",rep:"31",choix:["31", "16", "32", "63"],diff:4,hint:"Chaque match élimine exactement une équipe.",expl:"Chaque match élimine une équipe et il faut en éliminer 31 : 31 matchs (16 + 8 + 4 + 2 + 1)."},
{id:"LG-LY-544",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Quelle est la contraposée de « Si n est pair, alors n² est pair » ?",rep:"Si n² est impair, alors n est impair",choix:["Si n² est impair, alors n est impair", "Si n² est pair, alors n est pair", "Si n est impair, alors n² est impair", "Si n est pair, alors n² est impair"],diff:3,hint:"La contraposée de « A ⇒ B » est « non B ⇒ non A ».",expl:"La contraposée de A ⇒ B est non B ⇒ non A, toujours équivalente à l'implication. « Si n² est pair… » serait la réciproque."},
{id:"LG-LY-545",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Quelle est la négation de « ∀x ∈ ℝ, f(x) > 0 » ?",rep:"∃x ∈ ℝ, f(x) ≤ 0",choix:["∃x ∈ ℝ, f(x) ≤ 0", "∀x ∈ ℝ, f(x) ≤ 0", "∃x ∈ ℝ, f(x) < 0", "∀x ∈ ℝ, f(x) < 0"],diff:3,hint:"« Pour tout » devient « il existe », et le contraire de > est…",expl:"On échange ∀ et ∃, et on nie la propriété : le contraire de f(x) > 0 est f(x) ≤ 0 (pas < 0)."},
{id:"LG-LY-546",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Quelle est la négation de « ∃x ∈ ℝ, x² = −1 » ?",rep:"∀x ∈ ℝ, x² ≠ −1",choix:["∀x ∈ ℝ, x² ≠ −1", "∃x ∈ ℝ, x² ≠ −1", "∀x ∈ ℝ, x² = 1", "∀x ∈ ℝ, x² = −1"],diff:3,hint:"« Il existe » devient « pour tout ».",expl:"Nier « il existe x tel que P » donne « pour tout x, non P » : ∀x, x² ≠ −1 (qui est d'ailleurs vraie)."},
{id:"LG-LY-547",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Négation de « Tout élève de la classe a au moins un frère » ?",rep:"Un élève au moins n'a aucun frère",choix:["Un élève au moins n'a aucun frère", "Aucun élève n'a de frère", "Tout élève a au plus un frère", "Un élève au moins a un frère"],diff:3,hint:"Pour contredire « tous », un seul cas contraire suffit.",expl:"Pour que « tout élève a un frère » soit faux, il suffit d'un élève sans frère : ∀ devient ∃ et la propriété est niée."},
{id:"LG-LY-548",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Pour x réel, « x = 2 » est pour « x² = 4 » une condition…",rep:"suffisante mais pas nécessaire",choix:["suffisante mais pas nécessaire", "nécessaire mais pas suffisante", "nécessaire et suffisante", "ni nécessaire ni suffisante"],diff:3,hint:"x = 2 entraîne-t-il x² = 4 ? Et x² = 4 entraîne-t-il x = 2 ?",expl:"x = 2 ⇒ x² = 4, donc suffisante. Mais x = −2 donne aussi x² = 4 : elle n'est pas nécessaire."},
{id:"LG-LY-549",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Pour un entier, « être divisible par 2 » est pour « être divisible par 6 » une condition…",rep:"nécessaire mais pas suffisante",choix:["nécessaire mais pas suffisante", "suffisante mais pas nécessaire", "nécessaire et suffisante", "ni nécessaire ni suffisante"],diff:3,hint:"Un multiple de 6 est-il pair ? Un nombre pair est-il multiple de 6 ?",expl:"Divisible par 6 ⇒ divisible par 2 : condition nécessaire. Mais 4 est pair sans être multiple de 6 : pas suffisante."},
{id:"LG-LY-550",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Pour x réel, quelle équivalence est vraie ?",rep:"x² = 9 ⇔ x = 3 ou x = −3",choix:["x² = 9 ⇔ x = 3 ou x = −3", "x² = 9 ⇔ x = 3", "x² > 4 ⇔ x > 2", "√(x²) = x ⇔ x ≠ 0"],diff:3,hint:"N'oublie pas les nombres négatifs.",expl:"x² = 9 a deux solutions, 3 et −3. Les autres oublient les négatifs : x = −3 donne x² > 4 sans x > 2."},
{id:"LG-LY-551",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Quel nombre est un contre-exemple à « pour tout réel x, x² > 9 ⇒ x > 3 » ?",rep:"−4",choix:["−4", "4", "−3", "0"],diff:3,hint:"Cherche x avec x² > 9 mais x ≤ 3.",expl:"(−4)² = 16 > 9 mais −4 n'est pas > 3 : l'implication est fausse. Pour −3, x² = 9 n'est pas > 9."},
{id:"LG-LY-552",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Une implication « P ⇒ Q » est fausse uniquement quand…",rep:"P est vraie et Q fausse",choix:["P est vraie et Q fausse", "P est fausse et Q vraie", "P et Q sont fausses", "P et Q sont vraies"],diff:3,hint:"Une promesse « si P alors Q » est trahie dans quel cas ?",expl:"« P ⇒ Q » n'est trahie que si P se réalise sans Q. Si P est fausse, l'implication est vraie quel que soit Q."},
{id:"LG-LY-553",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Combien de couples de valeurs (P ; Q) rendent l'implication « P ⇒ Q » vraie ?",rep:"3",choix:["3", "1", "2", "4"],diff:3,hint:"Il y a 4 couples possibles ; un seul rend l'implication fausse.",expl:"Sur les 4 couples (V;V), (V;F), (F;V), (F;F), seul (V;F) rend P ⇒ Q fausse : 3 la rendent vraie."},
{id:"LG-LY-554",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Pour prouver par l'absurde que √2 est irrationnel, on suppose d'abord que…",rep:"√2 = p/q avec p/q irréductible",choix:["√2 = p/q avec p/q irréductible", "√2 est irrationnel", "√2 est un entier", "√2 = 1,414 exactement"],diff:3,hint:"Dans un raisonnement par l'absurde, on suppose le contraire de ce qu'on veut prouver.",expl:"On suppose √2 rationnel, √2 = p/q irréductible. On montre alors que p et q sont pairs : contradiction, donc √2 est irrationnel."},
{id:"LG-LY-555",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Pourquoi n(n + 1) est-il toujours pair pour un entier n ?",rep:"Un des deux entiers consécutifs est pair",choix:["Un des deux entiers consécutifs est pair", "n² est toujours pair", "n + 1 est toujours pair", "Un produit d'entiers est toujours pair"],diff:3,hint:"Distingue le cas n pair et le cas n impair.",expl:"Disjonction de cas : si n est pair, n(n + 1) l'est ; si n est impair, n + 1 est pair. Le produit est toujours pair."},
{id:"LG-LY-556",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Si n est un entier impair, n² − 1 est toujours divisible par…",rep:"8",choix:["8", "3", "6", "5"],diff:4,hint:"Factorise n² − 1 et regarde n − 1 et n + 1.",expl:"n² − 1 = (n − 1)(n + 1) : deux pairs consécutifs, dont un multiple de 4. Le produit est multiple de 8 (8, 24, 48…)."},
{id:"LG-LY-557",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Pour savoir si 97 est premier, quel est le plus grand nombre premier qu'il suffit de tester ?",rep:"7",choix:["7", "47", "11", "13"],diff:3,hint:"Si 97 = a × b, l'un des deux facteurs est au plus √97.",expl:"Un diviseur éventuel serait ≤ √97 ≈ 9,8. On teste 2, 3, 5, 7 : aucun ne divise 97, donc 97 est premier."},
{id:"LG-LY-558",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Quel est le chiffre des unités de 2²⁰²⁶ ?",rep:"4",choix:["4", "2", "6", "8"],diff:4,hint:"Les unités de 2, 4, 8, 16, 32… se répètent par cycles.",expl:"Les unités suivent le cycle 2, 4, 8, 6 de longueur 4. 2026 = 4 × 506 + 2 : 2ᵉ du cycle, donc 4."},
{id:"LG-LY-559",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Combien d'entiers faut-il au minimum pour être sûr que deux ont le même reste dans la division par 4 ?",rep:"5",choix:["5", "4", "8", "3"],diff:3,hint:"Combien de restes possibles dans une division par 4 ?",expl:"Il n'y a que 4 restes possibles (0, 1, 2, 3). Avec 5 entiers, deux partagent forcément un reste : principe des tiroirs."},
{id:"LG-LY-560",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"A = {1;2;3;4} et B = {3;4;5}. Combien d'éléments contient A ∪ B ?",rep:"5",choix:["5", "7", "2", "4"],diff:2,hint:"Dans une réunion, on ne compte pas deux fois les éléments communs.",expl:"A ∪ B = {1;2;3;4;5} : 5 éléments. On a 4 + 3 − 2, car 3 et 4 sont dans les deux ensembles."},
{id:"LG-LY-561",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Quelle est l'intersection des intervalles [1 ; 5] et [3 ; 8] ?",rep:"[3 ; 5]",choix:["[3 ; 5]", "[1 ; 8]", "[1 ; 3]", "]5 ; 8]"],diff:2,hint:"Cherche les réels qui sont à la fois dans les deux intervalles.",expl:"Un réel est dans les deux s'il est ≥ 3 et ≤ 5 : l'intersection est [3 ; 5]. [1 ; 8] est la réunion."},
{id:"LG-LY-562",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"En Python : s = 0 puis « for i in range(5): s = s + i ». Que vaut s à la fin ?",rep:"10",choix:["10", "15", "5", "4"],diff:3,hint:"range(5) donne i = 0, 1, 2, 3, 4.",expl:"range(5) parcourt 0, 1, 2, 3, 4 (sans 5) : s = 0 + 1 + 2 + 3 + 4 = 10."},
{id:"LG-LY-563",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"n = 1, puis « tant que n < 100 : n = n × 3 ». Quelle est la valeur finale de n ?",rep:"243",choix:["243", "81", "100", "729"],diff:3,hint:"Écris les valeurs successives de n et vérifie la condition à chaque fois.",expl:"n prend les valeurs 1, 3, 9, 27, 81, 243. À 81 la condition est vraie, on passe à 243 et la boucle s'arrête."},
{id:"LG-LY-564",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"A dit : « B ment ». B dit : « C ment ». C dit : « A et B mentent ». Qui dit la vérité ?",rep:"B seulement",choix:["B seulement", "A seulement", "C seulement", "A et C"],diff:4,hint:"Suppose que B ment et cherche une contradiction.",expl:"Si B mentait, C dirait vrai, donc A et B mentiraient ; mais alors « B ment » serait vrai : contradiction. B dit vrai, A et C mentent."},
{id:"LG-LY-565",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Chevaliers : toujours vrai ; fripons : toujours faux. A dit « B est fripon », B dit « A et moi sommes pareils ». Conclusion ?",rep:"A chevalier, B fripon",choix:["A chevalier, B fripon", "A fripon, B chevalier", "Deux chevaliers", "Deux fripons"],diff:4,hint:"Teste l'hypothèse « A est un fripon ».",expl:"Si A était fripon, B serait chevalier et dirait vrai : ils seraient pareils, contradiction. A est chevalier, B fripon (et B ment bien)."},
{id:"LG-LY-566",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"« Aucun reptile n'a de poils. Certains animaux à poils nagent. » Quelle conclusion est sûre ?",rep:"Certains nageurs ne sont pas des reptiles",choix:["Certains nageurs ne sont pas des reptiles", "Aucun reptile ne nage", "Tous les nageurs ont des poils", "Certains reptiles nagent"],diff:4,hint:"Que sait-on des animaux à poils qui nagent ?",expl:"Les animaux à poils qui nagent ne peuvent pas être des reptiles : il existe donc des nageurs non reptiles. Le reste n'est pas déductible."},
{id:"LG-LY-567",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"« Tous les A sont des B. Certains B sont des C. » Que peut-on conclure sur A et C ?",rep:"Rien de certain",choix:["Rien de certain", "Certains A sont des C", "Tous les A sont des C", "Aucun A n'est un C"],diff:3,hint:"Les B qui sont C sont-ils forcément des A ?",expl:"Les B qui sont des C peuvent tous être hors de A. Exemple : tous les chats sont des animaux, certains animaux volent."},
{id:"LG-LY-568",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Peut-on tracer sans lever le crayon (ni repasser) une figure où 4 sommets ont un nombre impair de traits ?",rep:"Non : il faut 0 ou 2 sommets impairs",choix:["Non : il faut 0 ou 2 sommets impairs", "Oui, en partant d'un sommet impair", "Oui, c'est toujours possible", "Non : tous doivent être impairs"],diff:4,hint:"À chaque passage par un sommet, on entre et on ressort.",expl:"Hors départ et arrivée, on entre et sort de chaque sommet : nombre de traits pair. Au plus 2 sommets impairs sont permis (théorème d'Euler)."},
{id:"LG-LY-569",classe:"Lycée",cat:"🧠",type:"Logique",enonce:"Vrai ou faux : « Il existe un réel y tel que, pour tout réel x, y > x » ?",rep:"Faux : x = y + 1 la contredit",choix:["Faux : x = y + 1 la contredit", "Vrai : il suffit de prendre y très grand", "Vrai : car ℝ est infini", "Faux : car y doit être un entier"],diff:4,hint:"Si on te donne un y, peux-tu trouver un x plus grand ?",expl:"Pour tout y, le réel x = y + 1 vérifie x > y : aucun réel n'est plus grand que tous les autres. L'ordre de ∃ et ∀ compte."},
{id:"FR-6E-501",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la nature de « rapidement » dans « Il court rapidement » ?",rep:"adverbe",choix:["nom commun", "adjectif qualificatif", "préposition", "adverbe"],diff:2,hint:"Ce mot modifie le sens d'un verbe et ne s'accorde pas.",expl:"« Rapidement » précise le verbe « court » et est invariable : c'est un adverbe. Beaucoup d'adverbes de manière finissent en -ment."},
{id:"FR-6E-502",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la fonction de « une pomme » dans « Léa mange une pomme. » ?",rep:"COD",choix:["attribut du sujet", "sujet", "COD", "COI"],diff:2,hint:"Pose la question « Léa mange quoi ? ».",expl:"« Une pomme » répond à « mange quoi ? » sans préposition : c'est un complément d'objet direct."},
{id:"FR-6E-503",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la fonction de « malade » dans « Le chien semble malade. » ?",rep:"attribut du sujet",choix:["COD", "complément circonstanciel", "épithète", "attribut du sujet"],diff:3,hint:"« Sembler » est un verbe d'état, comme « être ».",expl:"Après un verbe d'état (être, sembler, paraître…), le mot qui qualifie le sujet est attribut du sujet."},
{id:"FR-6E-504",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la fonction de « à sa sœur » dans « Tom parle à sa sœur. » ?",rep:"COI",choix:["COD", "complément circonstanciel de lieu", "COI", "complément du nom"],diff:3,hint:"Le complément est relié au verbe par une préposition.",expl:"« À sa sœur » complète le verbe « parle » grâce à la préposition « à » : c'est un complément d'objet indirect."},
{id:"FR-6E-505",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « chanter » au passé simple, 3e personne du pluriel ?",rep:"ils chantèrent",choix:["ils chantaient", "ils chantirent", "ils chanteront", "ils chantèrent"],diff:2,hint:"Au passé simple, les verbes en -er ont des terminaisons en -a ou -è.",expl:"Les verbes du 1er groupe font -èrent à la 3e personne du pluriel du passé simple : ils chantèrent."},
{id:"FR-6E-506",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « finir » au passé simple, 1re personne du singulier ?",rep:"je finis",choix:["je finit", "je finissais", "je finissai", "je finis"],diff:3,hint:"Les verbes du 2e groupe ont un passé simple en -i.",expl:"Au passé simple, le 2e groupe se conjugue en -is, -is, -it… : je finis (même forme qu'au présent)."},
{id:"FR-6E-507",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « prendre » au passé simple, 3e personne du singulier ?",rep:"il prit",choix:["il prenait", "il prendit", "il prit", "il prena"],diff:3,hint:"Le radical de ce verbe se réduit à « pr- » au passé simple.",expl:"« Prendre » fait au passé simple : je pris, tu pris, il prit. « Il prenait » est l'imparfait."},
{id:"FR-6E-508",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « venir » au passé simple, 3e personne du pluriel ?",rep:"ils vinrent",choix:["ils venirent", "ils venaient", "ils vinrent", "ils venèrent"],diff:4,hint:"Pense à « il vint ».",expl:"« Venir » a un passé simple en -in- : je vins, il vint, ils vinrent. « Ils venaient » est l'imparfait."},
{id:"FR-6E-509",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « voir » au futur simple, 1re personne du singulier ?",rep:"je verrai",choix:["je verrai", "je verai", "je voirai", "je verrais"],diff:3,hint:"Le radical du futur de « voir » change et prend deux r.",expl:"« Voir » a un radical irrégulier au futur : je verrai. « Je verrais » (avec s) est le conditionnel."},
{id:"FR-6E-510",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « courir » au futur simple, 1re personne du pluriel ?",rep:"nous courrons",choix:["nous courirons", "nous courerons", "nous courrons", "nous courons"],diff:3,hint:"Au futur, le radical de « courir » est « courr- » : compare avec le présent.",expl:"Au futur, « courir » prend deux r : nous courrons. « Nous courons » avec un seul r est le présent."},
{id:"FR-6E-511",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « aller » à l'impératif présent, 2e personne du singulier ?",rep:"va",choix:["allez", "vas", "ailles", "va"],diff:3,hint:"À l'impératif, les verbes comme « aller » perdent le -s final.",expl:"À l'impératif, « aller » fait « va » sans s (sauf devant « y » : vas-y)."},
{id:"FR-6E-512",classe:"6ème",cat:"📖",type:"Français",enonce:"À quel temps est le verbe dans « nous avions mangé » ?",rep:"plus-que-parfait",choix:["passé antérieur", "imparfait", "passé composé", "plus-que-parfait"],diff:3,hint:"Regarde le temps de l'auxiliaire « avoir ».",expl:"Auxiliaire à l'imparfait + participe passé = plus-que-parfait de l'indicatif."},
{id:"FR-6E-513",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la forme correcte de « naître » au passé composé avec « elle » ?",rep:"elle est née",choix:["elle était née", "elle a né", "elle est née", "elle naquit"],diff:2,hint:"« Naître » se conjugue avec l'auxiliaire « être ».",expl:"« Naître » se conjugue avec « être » au passé composé, et le participe s'accorde avec le sujet : elle est née."},
{id:"FR-6E-514",classe:"6ème",cat:"📖",type:"Français",enonce:"Complète : « Les filles sont ___ hier soir. » (arriver)",rep:"arrivées",choix:["arrivés", "arrivée", "arrivé", "arrivées"],diff:2,hint:"Avec « être », le participe passé s'accorde avec le sujet.",expl:"Avec l'auxiliaire « être », le participe passé s'accorde avec le sujet « les filles » : féminin pluriel, arrivées."},
{id:"FR-6E-515",classe:"6ème",cat:"📖",type:"Français",enonce:"Complète : « Il ___ promené dans le parc. »",rep:"s'est",choix:["s'est", "c'est", "ses", "ces"],diff:2,hint:"Remplace par « je me suis promené » pour vérifier.",expl:"« S'est » est le verbe pronominal « se promener » au passé composé : on peut dire « je me suis promené »."},
{id:"FR-6E-516",classe:"6ème",cat:"📖",type:"Français",enonce:"Complète : « Je ne sais pas ___ il viendra. »",rep:"quand",choix:["quant", "quand", "qu'en"],diff:3,hint:"Le mot manquant indique un moment : à quel moment ?",expl:"« Quand » indique le temps (à quel moment). « Quant » s'emploie dans « quant à » et « qu'en » = que + en."},
{id:"FR-6E-517",classe:"6ème",cat:"📖",type:"Français",enonce:"Complète : « Il a ___ ses clés sur la table. »",rep:"laissé",choix:["laisser", "laissait", "laissés", "laissé"],diff:2,hint:"Remplace par « vendu » ou « vendre » pour vérifier.",expl:"Après l'auxiliaire « avoir », on met le participe passé : il a laissé (on dirait « il a vendu »). Le COD est placé après : pas d'accord."},
{id:"FR-6E-518",classe:"6ème",cat:"📖",type:"Français",enonce:"Que signifie le préfixe « il- » dans le mot « illisible » ?",rep:"le contraire",choix:["la répétition", "l'avant", "le contraire", "l'excès"],diff:2,hint:"Compare « lisible » et « illisible ».",expl:"Le préfixe « il- » (comme in-, im-, ir-) exprime le contraire : illisible = qui n'est pas lisible."},
{id:"FR-6E-519",classe:"6ème",cat:"📖",type:"Français",enonce:"Que signifie le suffixe « -able » dans le mot « lavable » ?",rep:"qui peut être lavé",choix:["qui doit être lavé", "qui a été lavé", "qui lave bien", "qui peut être lavé"],diff:2,hint:"Pense à « buvable », « mangeable ».",expl:"Le suffixe « -able » indique une possibilité : lavable = qui peut être lavé, buvable = qui peut être bu."},
{id:"FR-6E-520",classe:"6ème",cat:"📖",type:"Français",enonce:"Quel mot n'appartient PAS à la famille de « terre » ?",rep:"terrible",choix:["terrible", "terrain", "atterrir", "enterrer"],diff:3,hint:"Cherche le mot dont le sens n'a aucun rapport avec le sol.",expl:"« Terrible » vient du latin « terror » (la peur), pas de « terra ». Terrain, atterrir et enterrer contiennent le radical « terr- » (sol)."},
{id:"FR-6E-521",classe:"6ème",cat:"📖",type:"Français",enonce:"Quel est le synonyme de « courroucé » ?",rep:"en colère",choix:["en colère", "fatigué", "étonné", "effrayé"],diff:3,hint:"Le « courroux » est un sentiment violent.",expl:"« Courroucé » vient de « courroux », qui signifie une grande colère : courroucé = en colère."},
{id:"FR-6E-522",classe:"6ème",cat:"📖",type:"Français",enonce:"Quel est le contraire de « prodigue » ?",rep:"avare",choix:["avare", "dépensier", "riche", "généreux"],diff:4,hint:"Une personne prodigue dépense sans compter.",expl:"Prodigue = qui dépense sans compter. Son contraire est « avare », celui qui ne veut pas dépenser."},
{id:"FR-6E-523",classe:"6ème",cat:"📖",type:"Français",enonce:"Dans « la souris de l'ordinateur », le mot « souris » est employé au sens…",rep:"figuré",choix:["propre", "étymologique", "péjoratif", "figuré"],diff:3,hint:"Le sens premier de « souris » est un petit animal.",expl:"Le sens propre est le sens premier (l'animal). Ici, l'objet ressemble à l'animal : le mot est employé au sens figuré."},
{id:"FR-6E-524",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle figure de style trouve-t-on dans « Ses yeux brillent comme des étoiles » ?",rep:"comparaison",choix:["personnification", "énumération", "comparaison", "métaphore"],diff:2,hint:"Cherche un outil qui rapproche deux éléments.",expl:"Il y a un outil de comparaison (« comme ») qui rapproche les yeux et les étoiles : c'est une comparaison."},
{id:"FR-6E-525",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle figure de style trouve-t-on dans « Le vent hurle dans la nuit » ?",rep:"personnification",choix:["énumération", "personnification", "comparaison", "répétition"],diff:2,hint:"Qui hurle normalement ? Un être vivant.",expl:"On prête au vent une action d'être vivant (hurler) : c'est une personnification."},
{id:"FR-6E-526",classe:"6ème",cat:"📖",type:"Français",enonce:"Dans « Il est rusé tel un renard », quel est l'outil de comparaison ?",rep:"tel",choix:["rusé", "est", "tel", "renard"],diff:2,hint:"C'est le mot qui relie les deux éléments comparés.",expl:"Une comparaison a un comparé (il), un comparant (un renard) et un outil (« tel », comme « comme » ou « pareil à »)."},
{id:"FR-6E-527",classe:"6ème",cat:"📖",type:"Français",enonce:"Qui est l'auteur de « L'Odyssée » ?",rep:"Homère",choix:["Sophocle", "Ovide", "Virgile", "Homère"],diff:2,hint:"C'est aussi l'auteur supposé de « L'Iliade ».",expl:"« L'Iliade » et « L'Odyssée » sont attribuées au poète grec Homère (VIIIe siècle av. J.-C.)."},
{id:"FR-6E-528",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle île est le royaume d'Ulysse ?",rep:"Ithaque",choix:["Troie", "Sparte", "Ithaque", "la Crète"],diff:2,hint:"C'est l'île où l'attend Pénélope.",expl:"Ulysse est roi d'Ithaque : « L'Odyssée » raconte son long retour vers cette île après la guerre de Troie."},
{id:"FR-6E-529",classe:"6ème",cat:"📖",type:"Français",enonce:"Comment s'appelle le Cyclope aveuglé par Ulysse ?",rep:"Polyphème",choix:["Argos", "Cerbère", "Polyphème", "Éole"],diff:2,hint:"Ulysse se présente à lui sous le nom de « Personne ».",expl:"Ulysse crève l'œil unique du Cyclope Polyphème, fils de Poséidon, après lui avoir dit s'appeler « Personne »."},
{id:"FR-6E-530",classe:"6ème",cat:"📖",type:"Français",enonce:"Qui, dans « L'Odyssée », défait chaque nuit sa toile pour faire patienter ses prétendants ?",rep:"Pénélope",choix:["Pénélope", "Calypso", "Circé", "Hélène"],diff:2,hint:"Elle attend fidèlement le retour d'Ulysse à Ithaque pendant vingt ans.",expl:"Pénélope promet de choisir un prétendant quand sa toile sera finie, mais la défait chaque nuit : symbole de fidélité."},
{id:"FR-6E-531",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle magicienne transforme les compagnons d'Ulysse en porcs ?",rep:"Circé",choix:["Athéna", "Circé", "Nausicaa", "Calypso"],diff:3,hint:"Hermès donne à Ulysse une plante pour lui résister.",expl:"Dans « L'Odyssée », la magicienne Circé change les compagnons en porcs ; Ulysse, protégé par Hermès, les délivre."},
{id:"FR-6E-532",classe:"6ème",cat:"📖",type:"Français",enonce:"Qui est l'auteur latin des « Métamorphoses » ?",rep:"Ovide",choix:["Ovide", "Ésope", "Virgile", "Homère"],diff:3,hint:"Ce poète romain vécut au temps de l'empereur Auguste.",expl:"Les « Métamorphoses » sont un long poème latin d'Ovide qui raconte des transformations de dieux et d'humains."},
{id:"FR-6E-533",classe:"6ème",cat:"📖",type:"Français",enonce:"En quoi la nymphe Daphné est-elle transformée pour échapper à Apollon ?",rep:"en laurier",choix:["en laurier", "en olivier", "en source", "en biche"],diff:3,hint:"Cette plante devient le symbole d'Apollon et des vainqueurs.",expl:"Dans les « Métamorphoses » d'Ovide, Daphné devient un laurier ; Apollon en fait son arbre, symbole de gloire."},
{id:"FR-6E-534",classe:"6ème",cat:"📖",type:"Français",enonce:"De qui Narcisse tombe-t-il amoureux ?",rep:"de son reflet",choix:["de la nymphe Écho", "d'une statue", "de son reflet", "d'une déesse"],diff:2,hint:"Il se penche au-dessus de l'eau d'une source.",expl:"Narcisse s'éprend de son propre reflet dans l'eau et dépérit ; il est changé en fleur. Écho l'aimait en vain."},
{id:"FR-6E-535",classe:"6ème",cat:"📖",type:"Français",enonce:"Quel est le premier livre de la Bible, qui raconte la création du monde ?",rep:"la Genèse",choix:["l'Exode", "les Psaumes", "la Genèse", "l'Apocalypse"],diff:2,hint:"Son nom signifie « naissance, origine ».",expl:"La Genèse (du grec « genesis », origine) ouvre la Bible : création du monde, Adam et Ève, Noé, Abraham."},
{id:"FR-6E-536",classe:"6ème",cat:"📖",type:"Français",enonce:"Dans la Genèse, qui construit une arche pour survivre au Déluge ?",rep:"Noé",choix:["Moïse", "Abraham", "Adam", "Noé"],diff:2,hint:"Il y fait monter un couple de chaque espèce animale.",expl:"Dans la Genèse, Dieu ordonne à Noé de construire une arche pour sauver sa famille et les animaux du Déluge."},
{id:"FR-6E-537",classe:"6ème",cat:"📖",type:"Français",enonce:"Qui a écrit en vers la fable « Le Corbeau et le Renard » publiée en 1668 ?",rep:"Jean de La Fontaine",choix:["Ésope", "Jean de La Fontaine", "Charles Perrault", "Molière"],diff:2,hint:"C'est le fabuliste français le plus célèbre du XVIIe siècle.",expl:"La Fontaine publie ses « Fables » en vers à partir de 1668, en s'inspirant notamment d'Ésope."},
{id:"FR-6E-538",classe:"6ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on la leçon que l'on tire d'une fable ?",rep:"la morale",choix:["la morale", "le refrain", "la chute", "la strophe"],diff:2,hint:"Elle est souvent placée au début ou à la fin du texte.",expl:"La morale est la leçon de sagesse d'une fable, par exemple « La raison du plus fort est toujours la meilleure »."},
{id:"FR-6E-539",classe:"6ème",cat:"📖",type:"Français",enonce:"Quel fabuliste grec de l'Antiquité a inspiré La Fontaine ?",rep:"Ésope",choix:["Homère", "Ésope", "Sophocle", "Ovide"],diff:3,hint:"Il a écrit des fables en prose plusieurs siècles avant J.-C.",expl:"Ésope, fabuliste grec du VIe siècle av. J.-C., a écrit des fables en prose que La Fontaine a réécrites en vers."},
{id:"FR-6E-540",classe:"6ème",cat:"📖",type:"Français",enonce:"Dans « Le Roman de Renart », comment s'appelle le loup, ennemi de Renart ?",rep:"Ysengrin",choix:["Tiécelin", "Chantecler", "Noble", "Ysengrin"],diff:3,hint:"Ce personnage est l'oncle de Renart et souvent victime de ses tours.",expl:"Ysengrin est le loup, oncle et ennemi de Renart. Chantecler est le coq, Tiécelin le corbeau, Noble le lion."},
{id:"FR-6E-541",classe:"6ème",cat:"📖",type:"Français",enonce:"Dans « Le Roman de Renart », quel animal est le roi Noble ?",rep:"le lion",choix:["l'aigle", "l'ours", "le lion", "le loup"],diff:3,hint:"C'est l'animal traditionnellement appelé « roi des animaux ».",expl:"Noble est le lion, roi des animaux : il préside la cour où Renart est souvent jugé pour ses ruses."},
{id:"FR-6E-542",classe:"6ème",cat:"📖",type:"Français",enonce:"Qui a publié les contes « Cendrillon » et « Le Petit Chaperon rouge » au XVIIe siècle ?",rep:"Charles Perrault",choix:["Hans Christian Andersen", "les frères Grimm", "Charles Perrault", "Jean de La Fontaine"],diff:3,hint:"Les frères Grimm ont écrit leurs versions au XIXe siècle.",expl:"Charles Perrault publie « Histoires ou contes du temps passé » en 1697. Les Grimm et Andersen écrivent au XIXe siècle."},
{id:"FR-6E-543",classe:"6ème",cat:"📖",type:"Français",enonce:"Dans le schéma narratif, quelle étape déclenche les aventures du héros ?",rep:"l'élément perturbateur",choix:["la situation finale", "la situation initiale", "le dénouement", "l'élément perturbateur"],diff:2,hint:"C'est l'événement qui rompt l'équilibre du début.",expl:"L'élément perturbateur vient briser l'équilibre de la situation initiale et lance les péripéties."},
{id:"FR-6E-544",classe:"6ème",cat:"📖",type:"Français",enonce:"Dans le schéma actanciel, comment appelle-t-on celui qui aide le héros ?",rep:"l'adjuvant",choix:["l'objet", "l'adjuvant", "le destinataire", "l'opposant"],diff:3,hint:"Ce mot vient du latin « adjuvare », aider.",expl:"L'adjuvant aide le héros dans sa quête, l'opposant lui fait obstacle."},
{id:"FR-6E-545",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle ruse permet aux Grecs d'entrer dans Troie ?",rep:"un cheval de bois",choix:["un tunnel secret", "un cheval de bois", "un déguisement de marchands", "un faux traité de paix"],diff:2,hint:"C'est une idée d'Ulysse, offerte comme un cadeau.",expl:"Les Grecs cachent des soldats dans un grand cheval de bois que les Troyens font entrer dans leur ville."},
{id:"FR-6E-546",classe:"6ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on un groupe de vers séparé des autres par une ligne blanche ?",rep:"une strophe",choix:["un paragraphe", "une strophe", "un vers", "une rime"],diff:2,hint:"Dans un poème, c'est l'équivalent du paragraphe.",expl:"Une strophe est un ensemble de vers ; on la nomme selon le nombre de vers (quatrain = 4, tercet = 3)."},
{id:"FR-6E-547",classe:"6ème",cat:"📖",type:"Français",enonce:"Comment s'appellent des rimes disposées AABB ?",rep:"des rimes plates",choix:["des rimes alternées", "des rimes croisées", "des rimes embrassées", "des rimes plates"],diff:3,hint:"Les rimes se suivent deux par deux.",expl:"Rimes plates (ou suivies) : AABB. Rimes croisées : ABAB. Rimes embrassées : ABBA."},
{id:"FR-6E-548",classe:"6ème",cat:"📖",type:"Français",enonce:"Combien de syllabes compte un octosyllabe ?",rep:"8",choix:["6", "10", "8", "12"],diff:2,hint:"Le préfixe « octo- » se retrouve dans « octogone ».",expl:"« Octo- » signifie huit : un octosyllabe est un vers de 8 syllabes. L'alexandrin en compte 12."},
{id:"FR-6E-549",classe:"6ème",cat:"📖",type:"Français",enonce:"Quel est le type de la phrase « Ferme la porte, s'il te plaît. » ?",rep:"injonctif",choix:["exclamatif", "injonctif", "déclaratif", "interrogatif"],diff:2,hint:"La phrase donne un ordre ou fait une demande.",expl:"Une phrase qui donne un ordre ou un conseil est de type injonctif ; ici, le verbe est à l'impératif."},
{id:"FR-6E-550",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la forme négative correcte de « Il mange encore. » ?",rep:"Il ne mange plus.",choix:["Il ne mange jamais.", "Il ne mange rien.", "Il mange plus.", "Il ne mange plus."],diff:3,hint:"Quel adverbe s'oppose à « encore » ?",expl:"La négation de « encore » est « ne… plus ». À l'écrit, il ne faut pas oublier le « ne »."},
{id:"FR-6E-551",classe:"6ème",cat:"📖",type:"Français",enonce:"Combien de propositions y a-t-il dans « Il pleut, je reste chez moi et je lis. » ?",rep:"3",choix:["4", "1", "2", "3"],diff:3,hint:"Compte les verbes conjugués.",expl:"Il y a autant de propositions que de verbes conjugués : pleut, reste, lis = 3 propositions."},
{id:"FR-6E-552",classe:"6ème",cat:"📖",type:"Français",enonce:"Quel est le sujet du verbe dans « Dans la forêt vivait un vieil ogre. » ?",rep:"un vieil ogre",choix:["la forêt", "vivait", "dans la forêt", "un vieil ogre"],diff:3,hint:"Pose la question « Qui est-ce qui vivait ? ».",expl:"Le sujet est inversé, placé après le verbe : « Qui est-ce qui vivait ? » Un vieil ogre."},
{id:"FR-6E-553",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la fonction de « ce matin » dans « Ce matin, nous partons en vacances. » ?",rep:"complément circonstanciel de temps",choix:["complément circonstanciel de temps", "sujet", "COD", "complément circonstanciel de lieu"],diff:2,hint:"Ce groupe peut être déplacé ou supprimé.",expl:"« Ce matin » indique quand se passe l'action et peut être déplacé ou supprimé : c'est un CC de temps."},
{id:"FR-6E-554",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la nature de « leur » dans « Ils promènent leur chien. » ?",rep:"déterminant possessif",choix:["déterminant possessif", "déterminant démonstratif", "adjectif qualificatif", "pronom personnel"],diff:3,hint:"Ce mot est placé devant un nom.",expl:"« Leur » est placé devant le nom « chien » et indique à qui il appartient : déterminant possessif."},
{id:"FR-6E-555",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la nature de « le » dans « Je le vois. » ?",rep:"pronom personnel",choix:["adverbe", "pronom personnel", "nom commun", "article défini"],diff:3,hint:"Ce mot remplace-t-il un nom ou l'accompagne-t-il ?",expl:"Ici, « le » remplace un nom et se place devant le verbe : c'est un pronom personnel COD."},
{id:"FR-6E-556",classe:"6ème",cat:"📖",type:"Français",enonce:"À quel groupe appartient le verbe « partir » ?",rep:"3e groupe",choix:["3e groupe", "1er groupe", "2e groupe"],diff:3,hint:"Dit-on « nous partissons » ?",expl:"Les verbes du 2e groupe font -issons (nous finissons). « Nous partons » : partir est du 3e groupe."},
{id:"FR-6E-557",classe:"6ème",cat:"📖",type:"Français",enonce:"Quel est le pluriel de « un vitrail » ?",rep:"des vitraux",choix:["des vitraux", "des vitrails", "des vitraus", "des vitrals"],diff:3,hint:"Pense au pluriel de « travail » ou « corail ».",expl:"Quelques noms en -ail font -aux au pluriel : vitrail, travail, corail, émail, bail, soupirail, vantail."},
{id:"FR-6E-558",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « commencer » à l'imparfait, 1re personne du singulier ?",rep:"je commençais",choix:["je commençais", "je commencais", "je commençai", "je commencerais"],diff:3,hint:"Devant a, o, u, le c doit garder le son [s].",expl:"Devant -ais, on ajoute une cédille pour garder le son [s] : je commençais. « Je commençai » est le passé simple."},
{id:"FR-6E-559",classe:"6ème",cat:"📖",type:"Français",enonce:"Quelle est la valeur du présent dans « La Terre tourne autour du Soleil. » ?",rep:"vérité générale",choix:["présent d'énonciation", "présent de narration", "présent d'habitude", "vérité générale"],diff:3,hint:"Cette phrase est vraie à toutes les époques.",expl:"Le présent de vérité générale exprime un fait toujours vrai, quel que soit le moment où l'on parle."},
{id:"FR-6E-560",classe:"6ème",cat:"📖",type:"Français",enonce:"Dans un récit au passé, quel temps exprime les actions principales et brèves ?",rep:"le passé simple",choix:["le plus-que-parfait", "le futur", "l'imparfait", "le passé simple"],diff:3,hint:"L'imparfait sert plutôt aux descriptions.",expl:"Le passé simple exprime les actions de premier plan, brèves et successives ; l'imparfait sert à l'arrière-plan."},
{id:"FR-5E-501",classe:"5ème",cat:"📖",type:"Français",enonce:"Qui est l'auteur de « Perceval ou le Conte du Graal » ?",rep:"Chrétien de Troyes",choix:["Rabelais", "Chrétien de Troyes", "Marie de France", "François Villon"],diff:3,hint:"Cet auteur du XIIe siècle a aussi écrit « Yvain ».",expl:"Chrétien de Troyes (XIIe siècle) a écrit plusieurs romans de chevalerie : « Perceval », « Yvain », « Lancelot »."},
{id:"FR-5E-502",classe:"5ème",cat:"📖",type:"Français",enonce:"Quel chevalier de la Table ronde aime la reine Guenièvre ?",rep:"Lancelot",choix:["Perceval", "Gauvain", "Yvain", "Lancelot"],diff:3,hint:"On le surnomme le « chevalier de la charrette ».",expl:"Lancelot du Lac aime en secret Guenièvre, l'épouse du roi Arthur : un amour courtois et interdit."},
{id:"FR-5E-503",classe:"5ème",cat:"📖",type:"Français",enonce:"Quel enchanteur conseille le roi Arthur ?",rep:"Merlin",choix:["Gauvain", "Galaad", "Merlin", "Tristan"],diff:2,hint:"Il est né d'une mortelle et d'un démon selon la légende.",expl:"Merlin l'enchanteur est le conseiller d'Arthur dans les légendes de la Table ronde."},
{id:"FR-5E-504",classe:"5ème",cat:"📖",type:"Français",enonce:"Dans « Tristan et Iseut », que boivent par erreur les deux héros ?",rep:"un philtre d'amour",choix:["un poison mortel", "un vin de sommeil", "un philtre d'amour", "une potion d'oubli"],diff:3,hint:"Ce breuvage les lie l'un à l'autre pour toujours.",expl:"Tristan et Iseut boivent par erreur un philtre d'amour destiné à Iseut et au roi Marc : leur amour devient irrésistible."},
{id:"FR-5E-505",classe:"5ème",cat:"📖",type:"Français",enonce:"Qui a écrit « Les Fourberies de Scapin » ?",rep:"Molière",choix:["Molière", "Racine", "Marivaux", "Corneille"],diff:2,hint:"Cet auteur de comédies a aussi écrit « L'Avare ».",expl:"Molière (XVIIe siècle) écrit « Les Fourberies de Scapin » en 1671, une comédie pleine de ruses et de coups de bâton."},
{id:"FR-5E-506",classe:"5ème",cat:"📖",type:"Français",enonce:"Dans « Les Fourberies de Scapin », où Scapin cache-t-il Géronte avant de le battre ?",rep:"dans un sac",choix:["dans un tonneau", "dans un sac", "dans une armoire", "dans un coffre"],diff:3,hint:"C'est une scène célèbre de comique de geste.",expl:"Scapin fait croire à Géronte qu'on veut le tuer, le cache dans un sac et le roue de coups de bâton."},
{id:"FR-5E-507",classe:"5ème",cat:"📖",type:"Français",enonce:"Dans quelle comédie de Molière un bûcheron devient-il faux médecin ?",rep:"Le Médecin malgré lui",choix:["L'Avare", "Le Malade imaginaire", "Le Médecin malgré lui", "Le Bourgeois gentilhomme"],diff:3,hint:"Le titre dit qu'il le devient sans le vouloir.",expl:"Dans « Le Médecin malgré lui », Sganarelle, bûcheron, est forcé de jouer le médecin après une vengeance de sa femme."},
{id:"FR-5E-508",classe:"5ème",cat:"📖",type:"Français",enonce:"Au théâtre, comment appelle-t-on une indication scénique écrite pour la mise en scène ?",rep:"une didascalie",choix:["une réplique", "une tirade", "une didascalie", "un aparté"],diff:2,hint:"Elle est souvent en italique et n'est pas prononcée.",expl:"Les didascalies indiquent les gestes, le ton, le décor ; elles ne sont pas dites par les comédiens."},
{id:"FR-5E-509",classe:"5ème",cat:"📖",type:"Français",enonce:"Au théâtre, comment appelle-t-on des paroles que les autres personnages ne sont pas censés entendre ?",rep:"un aparté",choix:["une réplique", "un monologue", "une tirade", "un aparté"],diff:3,hint:"Le personnage parle « à part », pour le public.",expl:"Dans un aparté, le personnage parle pour lui ou pour le public, en présence d'autres personnages qui n'entendent pas."},
{id:"FR-5E-510",classe:"5ème",cat:"📖",type:"Français",enonce:"Au théâtre, comment appelle-t-on une longue réplique prononcée devant d'autres personnages ?",rep:"une tirade",choix:["une tirade", "une didascalie", "un aparté", "un monologue"],diff:3,hint:"Le monologue, lui, se dit seul en scène.",expl:"Une tirade est une longue réplique adressée à d'autres personnages ; un monologue se dit seul en scène."},
{id:"FR-5E-511",classe:"5ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on un malentendu où un personnage est pris pour un autre ?",rep:"un quiproquo",choix:["un aparté", "un quiproquo", "un dénouement", "un monologue"],diff:3,hint:"Ce mot latin signifie « une chose pour une autre ».",expl:"Le quiproquo (« quid pro quo ») est une erreur sur une personne ou une chose : ressort fréquent du comique de situation."},
{id:"FR-5E-512",classe:"5ème",cat:"📖",type:"Français",enonce:"Coups de bâton et chutes relèvent de quel type de comique ?",rep:"le comique de geste",choix:["le comique de caractère", "le comique de mots", "le comique de situation", "le comique de geste"],diff:2,hint:"Ce comique passe par le corps des comédiens.",expl:"Le comique de geste fait rire par les mouvements : coups, chutes, grimaces, poursuites."},
{id:"FR-5E-513",classe:"5ème",cat:"📖",type:"Français",enonce:"Qui est l'auteur de « Robinson Crusoé » ?",rep:"Daniel Defoe",choix:["Jules Verne", "Robert Louis Stevenson", "Daniel Defoe", "Jonathan Swift"],diff:3,hint:"C'est un auteur anglais du XVIIIe siècle.",expl:"Daniel Defoe publie « Robinson Crusoé » en 1719 : un naufragé survit des années sur une île déserte."},
{id:"FR-5E-514",classe:"5ème",cat:"📖",type:"Français",enonce:"Quel livre raconte le voyage de Marco Polo en Asie ?",rep:"Le Devisement du monde",choix:["Voyage au centre de la Terre", "Les Voyages de Gulliver", "Le Devisement du monde", "Le Tour du monde en 80 jours"],diff:4,hint:"On l'appelle aussi « Le Livre des merveilles ».",expl:"Marco Polo dicte « Le Devisement du monde » (ou « Livre des merveilles ») vers 1298, après son voyage en Chine."},
{id:"FR-5E-515",classe:"5ème",cat:"📖",type:"Français",enonce:"Qui a écrit « Le Tour du monde en quatre-vingts jours » ?",rep:"Jules Verne",choix:["Victor Hugo", "Jules Verne", "Daniel Defoe", "Alexandre Dumas"],diff:2,hint:"Il a aussi écrit « Vingt mille lieues sous les mers ».",expl:"Jules Verne publie ce roman d'aventures en 1872 : Phileas Fogg parie qu'il fera le tour du monde en 80 jours."},
{id:"FR-5E-516",classe:"5ème",cat:"📖",type:"Français",enonce:"Quel roman de Stevenson raconte la recherche du trésor du capitaine Flint ?",rep:"L'Île au trésor",choix:["Moby Dick", "L'Île au trésor", "Robinson Crusoé", "Les Trois Mousquetaires"],diff:3,hint:"Le jeune héros s'appelle Jim Hawkins.",expl:"Dans « L'Île au trésor » (1883), Robert Louis Stevenson raconte l'aventure de Jim Hawkins face au pirate Long John Silver."},
{id:"FR-5E-517",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « faire » au subjonctif présent, 1re personne du pluriel ?",rep:"que nous fassions",choix:["que nous fassons", "que nous ferions", "que nous faisions", "que nous fassions"],diff:3,hint:"Le radical du subjonctif de « faire » est « fass- ».",expl:"Subjonctif présent de « faire » : que je fasse, que nous fassions. « Faisions » est l'imparfait."},
{id:"FR-5E-518",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « pouvoir » au conditionnel présent, 1re personne du singulier ?",rep:"je pourrais",choix:["je pourrai", "je pourrait", "je pouvais", "je pourrais"],diff:3,hint:"Le conditionnel se termine comme l'imparfait.",expl:"Conditionnel = radical du futur + terminaisons de l'imparfait : je pourr-ais. « Je pourrai » est le futur."},
{id:"FR-5E-519",classe:"5ème",cat:"📖",type:"Français",enonce:"À quel mode est « achèterais » dans « Si j'étais riche, j'achèterais un bateau » ?",rep:"conditionnel",choix:["indicatif futur", "subjonctif", "indicatif imparfait", "conditionnel"],diff:2,hint:"L'action dépend d'une condition introduite par « si ».",expl:"« J'achèterais » se termine par -rais : c'est le conditionnel présent, qui exprime ici une hypothèse."},
{id:"FR-5E-520",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « faire » au passé simple, 3e personne du pluriel ?",rep:"ils firent",choix:["ils firent", "ils fairent", "ils faisirent", "ils faisaient"],diff:3,hint:"Pense à « il fit ».",expl:"« Faire » au passé simple : je fis, il fit, ils firent. « Ils faisaient » est l'imparfait."},
{id:"FR-5E-521",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « être » au passé simple, 1re personne du pluriel ?",rep:"nous fûmes",choix:["nous fumes", "nous fûmes", "nous serions", "nous étâmes"],diff:4,hint:"Pense à « il fut » ; n'oublie pas l'accent.",expl:"« Être » au passé simple : je fus, il fut, nous fûmes (accent circonflexe aux 1re et 2e personnes du pluriel)."},
{id:"FR-5E-522",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle est la voix passive de « Le chat attrape la souris » ?",rep:"La souris est attrapée par le chat.",choix:["Le chat est attrapé par la souris.", "La souris est attrapée par le chat.", "La souris a attrapé le chat.", "La souris était attrapée par le chat."],diff:3,hint:"Le COD devient sujet, et le temps ne change pas.",expl:"Le COD devient sujet, le sujet devient complément d'agent ; « être » est au même temps que le verbe actif (présent)."},
{id:"FR-5E-523",classe:"5ème",cat:"📖",type:"Français",enonce:"Quel est le complément d'agent dans « Le gâteau a été mangé par les enfants » ?",rep:"par les enfants",choix:["par les enfants", "a été mangé", "le gâteau", "mangé"],diff:3,hint:"Il indique qui fait vraiment l'action.",expl:"À la voix passive, le complément d'agent, introduit par « par » ou « de », désigne celui qui fait l'action."},
{id:"FR-5E-524",classe:"5ème",cat:"📖",type:"Français",enonce:"Comment sont reliées les propositions dans « Il pleut, mais je sors. » ?",rep:"par coordination",choix:["par coordination", "par subordination", "par juxtaposition"],diff:3,hint:"« Mais » fait partie de « mais, ou, et, donc, or, ni, car ».",expl:"« Mais » est une conjonction de coordination : les deux propositions sont coordonnées."},
{id:"FR-5E-525",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle conjonction de coordination exprime la conséquence ?",rep:"donc",choix:["mais", "or", "donc", "car"],diff:3,hint:"« Car » exprime au contraire la cause.",expl:"« Donc » introduit une conséquence ; « car » une cause, « mais » une opposition."},
{id:"FR-5E-526",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle est la nature de « où » dans « La ville où je suis né est petite. » ?",rep:"pronom relatif",choix:["adverbe interrogatif", "conjonction de subordination", "pronom relatif", "conjonction de coordination"],diff:3,hint:"Ce mot reprend le nom « ville » placé juste avant.",expl:"« Où » reprend son antécédent « la ville » et introduit une proposition relative : c'est un pronom relatif."},
{id:"FR-5E-527",classe:"5ème",cat:"📖",type:"Français",enonce:"Quel est l'antécédent de « qui » dans « J'ai vu le garçon qui chantait. » ?",rep:"le garçon",choix:["vu", "j'", "chantait", "le garçon"],diff:2,hint:"L'antécédent est le nom que reprend le pronom relatif.",expl:"Le pronom relatif « qui » reprend le nom placé avant lui, « le garçon » : c'est son antécédent."},
{id:"FR-5E-528",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle est la fonction de « qu'il viendra » dans « Je crois qu'il viendra. » ?",rep:"COD",choix:["complément circonstanciel de cause", "sujet", "complément du nom", "COD"],diff:3,hint:"Pose la question « Je crois quoi ? ».",expl:"La subordonnée complétive « qu'il viendra » répond à « je crois quoi ? » : elle est COD du verbe « crois »."},
{id:"FR-5E-529",classe:"5ème",cat:"📖",type:"Français",enonce:"Qu'exprime « parce qu'il était malade » dans « Il est resté chez lui parce qu'il était malade. » ?",rep:"la cause",choix:["le temps", "la conséquence", "la cause", "le but"],diff:2,hint:"Cette proposition répond à la question « pourquoi ? ».",expl:"« Parce que » introduit une subordonnée circonstancielle de cause : elle explique pourquoi il est resté."},
{id:"FR-5E-530",classe:"5ème",cat:"📖",type:"Français",enonce:"Quel est le discours indirect de : Il dit : « Je suis fatigué. » ?",rep:"Il dit qu'il est fatigué.",choix:["Il dit : il est fatigué.", "Il dit que je suis fatigué.", "Il dit qu'il est fatigué.", "Il dit qu'il était fatigué."],diff:3,hint:"Le « je » change de personne ; le verbe introducteur est au présent.",expl:"Au discours indirect, « je » devient « il » ; le verbe introducteur étant au présent, le temps ne change pas."},
{id:"FR-5E-531",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle figure de style trouve-t-on dans « Cet homme est un lion » ?",rep:"métaphore",choix:["personnification", "métaphore", "hyperbole", "comparaison"],diff:2,hint:"Y a-t-il un outil de comparaison ?",expl:"On rapproche l'homme et le lion sans outil de comparaison : c'est une métaphore."},
{id:"FR-5E-532",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle figure de style trouve-t-on dans « Je meurs de faim ! » ?",rep:"hyperbole",choix:["personnification", "hyperbole", "comparaison", "métaphore"],diff:2,hint:"On exagère pour frapper l'esprit.",expl:"L'hyperbole est une exagération : on ne meurt pas vraiment, on a simplement très faim."},
{id:"FR-5E-533",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle figure de style trouve-t-on dans « Je vis, je meurs » (Louise Labé) ?",rep:"antithèse",choix:["comparaison", "anaphore", "gradation", "antithèse"],diff:4,hint:"Les deux verbes ont des sens opposés.",expl:"L'antithèse rapproche deux idées opposées (vivre / mourir) pour souligner un contraste."},
{id:"FR-5E-534",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle figure de style trouve-t-on dans « Va, cours, vole, et nous venge » (Corneille) ?",rep:"gradation",choix:["hyperbole", "antithèse", "gradation", "comparaison"],diff:3,hint:"Observe la vitesse croissante des verbes.",expl:"La gradation enchaîne des termes d'intensité croissante : va, puis cours, puis vole."},
{id:"FR-5E-535",classe:"5ème",cat:"📖",type:"Français",enonce:"Que signifie l'adjectif « preux » dans les récits de chevalerie ?",rep:"vaillant",choix:["vaillant", "rusé", "fortuné", "pieux"],diff:3,hint:"Pense aux qualités guerrières d'un chevalier.",expl:"« Preux » signifie courageux, vaillant au combat ; la « prouesse » en vient."},
{id:"FR-5E-536",classe:"5ème",cat:"📖",type:"Français",enonce:"Que signifie « adouber » au Moyen Âge ?",rep:"faire de quelqu'un un chevalier",choix:["faire de quelqu'un un chevalier", "bénir un mariage noble", "déclarer la guerre à un seigneur", "couronner un nouveau roi"],diff:3,hint:"La cérémonie se fait avec la remise des armes.",expl:"L'adoubement est la cérémonie où un jeune noble reçoit ses armes et devient chevalier."},
{id:"FR-5E-537",classe:"5ème",cat:"📖",type:"Français",enonce:"De quel nom vient l'adjectif « courtois » ?",rep:"cour",choix:["court", "cour", "courir", "courage"],diff:3,hint:"Pense à l'entourage d'un roi ou d'un seigneur.",expl:"« Courtois » vient de « cour » : les manières raffinées de la cour du seigneur, d'où l'« amour courtois »."},
{id:"FR-5E-538",classe:"5ème",cat:"📖",type:"Français",enonce:"Que signifie le mot latin « caballus », à l'origine de « chevalier » ?",rep:"cheval",choix:["armure", "seigneur", "guerrier", "cheval"],diff:2,hint:"Retrouve-le dans « cavalier » ou « chevaucher ».",expl:"« Chevalier » vient de « caballus », le cheval : le chevalier est d'abord un combattant à cheval."},
{id:"FR-5E-539",classe:"5ème",cat:"📖",type:"Français",enonce:"Complète : « Le magicien crée une ___ d'optique. »",rep:"illusion",choix:["allusion", "élusion", "illusion"],diff:3,hint:"Le mot désigne une perception trompeuse.",expl:"« Illusion » = apparence trompeuse ; « allusion » = évocation discrète. Ce sont des paronymes."},
{id:"FR-5E-540",classe:"5ème",cat:"📖",type:"Français",enonce:"Complète : « Je ne sais pas ___ heure il est. »",rep:"quelle",choix:["quelles", "qu'elle", "quelle", "quel"],diff:2,hint:"Remplace par « qu'il » : la phrase a-t-elle un sens ?",expl:"« Quelle » est un déterminant qui s'accorde avec « heure » (féminin singulier). On ne peut pas dire « qu'il heure »."},
{id:"FR-5E-541",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle est la valeur de l'imparfait dans « Chaque matin, il se levait tôt » ?",rep:"action habituelle",choix:["action de premier plan", "action brève et soudaine", "action future", "action habituelle"],diff:2,hint:"Observe l'indication « chaque matin ».",expl:"L'imparfait exprime ici une habitude dans le passé, renforcée par « chaque matin »."},
{id:"FR-5E-542",classe:"5ème",cat:"📖",type:"Français",enonce:"Qu'est-ce qu'un fabliau ?",rep:"un court récit comique en vers",choix:["une fable en prose de l'Antiquité", "un long poème épique en latin", "un court récit comique en vers", "une chanson d'amour courtois"],diff:3,hint:"Ce genre du Moyen Âge fait rire des bourgeois et des paysans.",expl:"Le fabliau est un court conte en vers du Moyen Âge (XIIe-XIVe siècles), comique et souvent satirique."},
{id:"FR-5E-543",classe:"5ème",cat:"📖",type:"Français",enonce:"Quelle chanson de geste raconte la mort du neveu de Charlemagne à Roncevaux ?",rep:"La Chanson de Roland",choix:["Le Roman de Renart", "La Chanson de Roland", "Le Conte du Graal", "Tristan et Iseut"],diff:3,hint:"Le héros sonne de l'olifant trop tard.",expl:"« La Chanson de Roland » (XIe siècle) raconte la mort héroïque de Roland à Roncevaux."},
{id:"FR-5E-544",classe:"5ème",cat:"📖",type:"Français",enonce:"Comment s'appelle l'épée de Roland ?",rep:"Durendal",choix:["Excalibur", "Durendal", "Hauteclaire", "Joyeuse"],diff:4,hint:"Excalibur appartient à un autre héros, Arthur.",expl:"Roland porte Durendal ; Excalibur est l'épée d'Arthur, Joyeuse celle de Charlemagne, Hauteclaire celle d'Olivier."},
{id:"FR-5E-545",classe:"5ème",cat:"📖",type:"Français",enonce:"Que signifie le préfixe grec « poly- » dans « polygone » ?",rep:"plusieurs",choix:["autour", "plusieurs", "égal", "un seul"],diff:2,hint:"Pense à « polyglotte », qui parle de nombreuses langues.",expl:"« Poly- » vient du grec « polus », nombreux : un polygone a plusieurs angles."},
{id:"FR-5E-546",classe:"5ème",cat:"📖",type:"Français",enonce:"Que signifie l'élément « -phobe » dans « claustrophobe » ?",rep:"qui a peur de",choix:["qui aime", "qui étudie", "qui soigne", "qui a peur de"],diff:3,hint:"Son contraire est « -phile ».",expl:"« -phobe » vient du grec « phobos », la peur : un claustrophobe a peur des lieux clos."},
{id:"FR-5E-547",classe:"5ème",cat:"📖",type:"Français",enonce:"Quel registre veut provoquer le rire ?",rep:"le registre comique",choix:["le registre épique", "le registre comique", "le registre lyrique", "le registre tragique"],diff:2,hint:"Pense aux pièces de Molière.",expl:"Le registre comique cherche à faire rire ; le lyrique exprime des sentiments, l'épique célèbre des exploits."},
{id:"FR-4E-501",classe:"4ème",cat:"📖",type:"Français",enonce:"Qui est l'auteur de la nouvelle fantastique « Le Horla » ?",rep:"Guy de Maupassant",choix:["Théophile Gautier", "Prosper Mérimée", "Guy de Maupassant", "Edgar Allan Poe"],diff:2,hint:"Cet auteur normand a aussi écrit « Boule de suif ».",expl:"« Le Horla » (1887) de Maupassant raconte l'angoisse d'un homme hanté par un être invisible."},
{id:"FR-4E-502",classe:"4ème",cat:"📖",type:"Français",enonce:"Qu'est-ce qui caractérise le récit fantastique ?",rep:"l'hésitation entre rationnel et surnaturel",choix:["un futur imaginé grâce aux sciences", "l'hésitation entre rationnel et surnaturel", "le surnaturel accepté sans surprise", "la peinture fidèle de la société"],diff:3,hint:"Le personnage et le lecteur doutent de ce qu'ils voient.",expl:"Le fantastique fait hésiter entre une explication rationnelle et une explication surnaturelle ; le merveilleux, lui, accepte la magie."},
{id:"FR-4E-503",classe:"4ème",cat:"📖",type:"Français",enonce:"Qui a écrit « La Vénus d'Ille » ?",rep:"Prosper Mérimée",choix:["Charles Nodier", "Guy de Maupassant", "Honoré de Balzac", "Prosper Mérimée"],diff:3,hint:"Il est aussi l'auteur de « Carmen » et « Colomba ».",expl:"Prosper Mérimée publie « La Vénus d'Ille » en 1837 : une statue de bronze semble prendre vie."},
{id:"FR-4E-504",classe:"4ème",cat:"📖",type:"Français",enonce:"Sous quelle forme est écrit « Le Horla » de 1887 ?",rep:"un journal intime",choix:["un échange de lettres", "un long poème", "un journal intime", "une pièce de théâtre"],diff:3,hint:"Le narrateur note ses impressions jour après jour.",expl:"Le texte est un journal daté : le narrateur y consigne sa peur grandissante, ce qui renforce le doute fantastique."},
{id:"FR-4E-505",classe:"4ème",cat:"📖",type:"Français",enonce:"Qui est l'auteur de la pièce « Le Cid » (1637) ?",rep:"Pierre Corneille",choix:["Victor Hugo", "Jean Racine", "Pierre Corneille", "Molière"],diff:2,hint:"Cet auteur du XVIIe siècle est né à Rouen.",expl:"« Le Cid » de Corneille met en scène Rodrigue, déchiré entre son amour pour Chimène et l'honneur de son père."},
{id:"FR-4E-506",classe:"4ème",cat:"📖",type:"Français",enonce:"Dans « Le Cid », comment appelle-t-on le choix impossible de Rodrigue entre amour et honneur ?",rep:"un dilemme",choix:["un dilemme", "un dénouement", "un aparté", "un quiproquo"],diff:3,hint:"Les deux possibilités entraînent une perte.",expl:"Un dilemme est un choix entre deux solutions également douloureuses : venger son père ou garder Chimène."},
{id:"FR-4E-507",classe:"4ème",cat:"📖",type:"Français",enonce:"Quel mouvement littéraire du début du XIXe siècle exprime les sentiments du moi ?",rep:"le romantisme",choix:["le réalisme", "le romantisme", "le classicisme", "le surréalisme"],diff:3,hint:"Lamartine et Victor Hugo en sont des figures majeures.",expl:"Le romantisme (début XIXe siècle) met en avant les émotions, la nature et le moi ; Lamartine, Hugo, Musset en font partie."},
{id:"FR-4E-508",classe:"4ème",cat:"📖",type:"Français",enonce:"Qui est l'auteur de la nouvelle « La Parure » ?",rep:"Guy de Maupassant",choix:["Émile Zola", "Gustave Flaubert", "Honoré de Balzac", "Guy de Maupassant"],diff:3,hint:"Mathilde Loisel y perd un collier emprunté.",expl:"Dans « La Parure » (1884) de Maupassant, Mathilde travaille dix ans pour rembourser un collier… qui était faux."},
{id:"FR-4E-509",classe:"4ème",cat:"📖",type:"Français",enonce:"Comment Balzac a-t-il nommé l'ensemble de ses romans ?",rep:"La Comédie humaine",choix:["Les Misérables", "Les Fleurs du mal", "Les Rougon-Macquart", "La Comédie humaine"],diff:3,hint:"Le titre fait écho à « La Divine Comédie » de Dante.",expl:"Balzac rassemble plus de 90 œuvres sous le titre « La Comédie humaine » pour peindre toute la société de son temps."},
{id:"FR-4E-510",classe:"4ème",cat:"📖",type:"Français",enonce:"Qui est l'auteur du cycle « Les Rougon-Macquart » ?",rep:"Émile Zola",choix:["Honoré de Balzac", "Guy de Maupassant", "Émile Zola", "Alexandre Dumas"],diff:2,hint:"Ce cycle contient « Germinal » et « L'Assommoir ».",expl:"Zola écrit les 20 romans des « Rougon-Macquart » pour étudier une famille sous le Second Empire."},
{id:"FR-4E-511",classe:"4ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on la fin surprenante d'une nouvelle ?",rep:"la chute",choix:["la péripétie", "la chute", "la morale", "le prologue"],diff:2,hint:"Elle renverse souvent ce que le lecteur attendait.",expl:"La chute est la fin inattendue d'une nouvelle, comme le collier faux à la fin de « La Parure »."},
{id:"FR-4E-512",classe:"4ème",cat:"📖",type:"Français",enonce:"Qu'exprime la subordonnée dans « Bien qu'il soit fatigué, il continue. » ?",rep:"la concession",choix:["la cause", "la condition", "la concession", "le but"],diff:3,hint:"Le fait attendu (s'arrêter) ne se produit pas.",expl:"« Bien que » + subjonctif introduit une concession : un fait qui aurait dû empêcher l'action principale."},
{id:"FR-4E-513",classe:"4ème",cat:"📖",type:"Français",enonce:"Qu'exprime la subordonnée dans « Il parle fort pour qu'on l'entende. » ?",rep:"le but",choix:["la concession", "la conséquence", "la cause", "le but"],diff:3,hint:"Quel objectif poursuit-il ?",expl:"« Pour que » + subjonctif introduit une subordonnée de but : elle indique l'objectif visé."},
{id:"FR-4E-514",classe:"4ème",cat:"📖",type:"Français",enonce:"Qu'exprime la subordonnée dans « Il a tant couru qu'il est épuisé. » ?",rep:"la conséquence",choix:["le but", "la concession", "la conséquence", "la cause"],diff:3,hint:"Repère la structure « tant… que ».",expl:"« Tant… que », « si… que », « si bien que » introduisent une conséquence : le résultat de l'action."},
{id:"FR-4E-515",classe:"4ème",cat:"📖",type:"Français",enonce:"Qu'exprime la subordonnée dans « Si tu viens, nous irons au cinéma. » ?",rep:"la condition",choix:["le temps", "la condition", "la cause", "la concession"],diff:2,hint:"La sortie au cinéma dépend de quelque chose.",expl:"« Si » introduit ici une subordonnée de condition (ou d'hypothèse) : l'action principale en dépend."},
{id:"FR-4E-516",classe:"4ème",cat:"📖",type:"Français",enonce:"Quelle est la nature de « Le soleil s'étant levé » dans « Le soleil s'étant levé, nous partîmes. » ?",rep:"subordonnée participiale",choix:["subordonnée participiale", "subordonnée complétive", "subordonnée infinitive", "subordonnée relative"],diff:4,hint:"Elle a son propre sujet et un participe, sans mot subordonnant.",expl:"Une participiale a un sujet propre (le soleil) et un verbe au participe ; elle joue le rôle de CC (ici de temps)."},
{id:"FR-4E-517",classe:"4ème",cat:"📖",type:"Français",enonce:"Quelle est la fonction de « déléguée » dans « Ils ont élu Marie déléguée. » ?",rep:"attribut du COD",choix:["épithète", "attribut du COD", "apposition", "COI"],diff:4,hint:"Ce mot dit ce que devient Marie, qui est COD.",expl:"« Déléguée » donne une qualité au COD « Marie » par l'intermédiaire du verbe « élire » : attribut du COD."},
{id:"FR-4E-518",classe:"4ème",cat:"📖",type:"Français",enonce:"Quelle est la fonction de « poète engagé » dans « Victor Hugo, poète engagé, s'exila. » ?",rep:"apposition",choix:["épithète", "COD", "apposition", "attribut du sujet"],diff:3,hint:"Le groupe est séparé du nom par des virgules.",expl:"Un groupe détaché par des virgules qui apporte une précision sur le nom est en apposition."},
{id:"FR-4E-519",classe:"4ème",cat:"📖",type:"Français",enonce:"Complète : « Elle s'est ___ les mains. » (laver)",rep:"lavé",choix:["lavés", "lavée", "lavé", "lavées"],diff:4,hint:"Elle a lavé quoi ? Où est placé ce COD ?",expl:"Le COD « les mains » est placé après le verbe : le participe passé ne s'accorde pas. « Se » est ici COI."},
{id:"FR-4E-520",classe:"4ème",cat:"📖",type:"Français",enonce:"Complète : « Ils se sont ___ longtemps. » (parler)",rep:"parlé",choix:["parler", "parlées", "parlé", "parlés"],diff:4,hint:"On parle « à » quelqu'un : « se » est-il COD ?",expl:"On parle à quelqu'un : « se » est COI. Sans COD placé avant, le participe passé reste invariable : parlé."},
{id:"FR-4E-521",classe:"4ème",cat:"📖",type:"Français",enonce:"À quel temps est le verbe dans « Quand il eut fini, il sortit » : « eut fini » ?",rep:"passé antérieur",choix:["futur antérieur", "passé antérieur", "plus-que-parfait", "passé composé"],diff:3,hint:"Regarde le temps de l'auxiliaire « avoir ».",expl:"Auxiliaire au passé simple + participe passé = passé antérieur : action antérieure à une action au passé simple."},
{id:"FR-4E-522",classe:"4ème",cat:"📖",type:"Français",enonce:"Quelle est la valeur du conditionnel dans « Le ministre serait malade, selon la presse. » ?",rep:"une information non vérifiée",choix:["un souhait", "une demande polie", "une information non vérifiée", "un futur dans le passé"],diff:3,hint:"« Selon la presse » : est-ce certain ?",expl:"Le conditionnel peut présenter une information incertaine, non confirmée : c'est souvent le cas dans les journaux."},
{id:"FR-4E-523",classe:"4ème",cat:"📖",type:"Français",enonce:"Quelle est la valeur du conditionnel dans « Je voudrais un renseignement. » ?",rep:"la politesse",choix:["la politesse", "l'information incertaine", "l'hypothèse", "le futur dans le passé"],diff:2,hint:"Compare avec « Je veux un renseignement ».",expl:"Le conditionnel atténue une demande : « je voudrais » est plus poli que « je veux »."},
{id:"FR-4E-524",classe:"4ème",cat:"📖",type:"Français",enonce:"Quelle est la valeur du conditionnel dans « Il a dit qu'il viendrait. » ?",rep:"un futur dans le passé",choix:["un souhait", "une condition", "une demande polie", "un futur dans le passé"],diff:3,hint:"L'action est postérieure à un moment passé.",expl:"Après un verbe au passé, le conditionnel exprime une action future par rapport à ce passé : futur dans le passé."},
{id:"FR-4E-525",classe:"4ème",cat:"📖",type:"Français",enonce:"À quel temps est le verbe passif dans « La lettre avait été écrite » ?",rep:"plus-que-parfait",choix:["plus-que-parfait", "passé composé", "imparfait", "passé antérieur"],diff:4,hint:"Au passif, regarde le temps de l'auxiliaire « être ».",expl:"Le temps d'un verbe passif est celui de « être » : « avait été » est le plus-que-parfait de « être »."},
{id:"FR-4E-526",classe:"4ème",cat:"📖",type:"Français",enonce:"Quel connecteur exprime l'opposition ?",rep:"pourtant",choix:["en effet", "ainsi", "de plus", "pourtant"],diff:2,hint:"Lequel introduit une idée contraire à la précédente ?",expl:"« Pourtant » marque l'opposition, comme « cependant » ou « néanmoins ». « Ainsi » conclut, « de plus » ajoute."},
{id:"FR-4E-527",classe:"4ème",cat:"📖",type:"Français",enonce:"Quel connecteur introduit une explication ?",rep:"en effet",choix:["en effet", "enfin", "donc", "cependant"],diff:3,hint:"Il justifie ce qui vient d'être dit.",expl:"« En effet » introduit une explication ou une justification ; « donc » une conséquence, « cependant » une opposition."},
{id:"FR-4E-528",classe:"4ème",cat:"📖",type:"Français",enonce:"Quelle figure de style trouve-t-on dans « Il nous a quittés » pour dire « il est mort » ?",rep:"euphémisme",choix:["antithèse", "hyperbole", "métaphore", "euphémisme"],diff:3,hint:"On adoucit une réalité pénible.",expl:"L'euphémisme atténue une idée choquante ou douloureuse en l'exprimant de façon adoucie."},
{id:"FR-4E-529",classe:"4ème",cat:"📖",type:"Français",enonce:"Quelle figure de style désigne Paris par « la Ville Lumière » ?",rep:"périphrase",choix:["périphrase", "euphémisme", "antithèse", "hyperbole"],diff:3,hint:"On remplace un nom par une expression de plusieurs mots.",expl:"La périphrase remplace un mot par une expression qui le désigne par une de ses caractéristiques."},
{id:"FR-4E-530",classe:"4ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on la représentation d'une idée abstraite par un personnage (la Mort avec sa faux) ?",rep:"une allégorie",choix:["une comparaison", "une allégorie", "une métonymie", "une hyperbole"],diff:4,hint:"L'idée prend un corps et des attributs concrets.",expl:"L'allégorie incarne une idée abstraite (la Mort, la Justice, la Liberté) sous une forme concrète et reconnaissable."},
{id:"FR-4E-531",classe:"4ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on une métaphore développée sur plusieurs mots ou phrases ?",rep:"une métaphore filée",choix:["une anaphore", "une métaphore filée", "une gradation", "une accumulation"],diff:3,hint:"Elle se « déroule » comme un fil.",expl:"La métaphore filée prolonge une même image avec plusieurs termes du même champ lexical."},
{id:"FR-4E-532",classe:"4ème",cat:"📖",type:"Français",enonce:"Dans une lettre, comment appelle-t-on la phrase qui précède la signature ?",rep:"la formule de politesse",choix:["le post-scriptum", "la formule d'appel", "la formule de politesse", "l'en-tête"],diff:2,hint:"« Je vous prie d'agréer… » en est un exemple.",expl:"La formule de politesse clôt la lettre avant la signature ; la formule d'appel (« Madame, ») l'ouvre."},
{id:"FR-4E-533",classe:"4ème",cat:"📖",type:"Français",enonce:"Dans « Demain, dès l'aube », Victor Hugo se rend sur la tombe de…",rep:"sa fille Léopoldine",choix:["sa mère Sophie", "sa femme Adèle", "son ami Lamartine", "sa fille Léopoldine"],diff:3,hint:"Elle s'est noyée dans la Seine en 1843.",expl:"Ce poème des « Contemplations » évoque la marche de Hugo vers la tombe de sa fille Léopoldine, noyée en 1843."},
{id:"FR-4E-534",classe:"4ème",cat:"📖",type:"Français",enonce:"Quel est le genre des « Contemplations » de Victor Hugo ?",rep:"un recueil de poèmes",choix:["un essai", "un recueil de poèmes", "un roman", "une pièce de théâtre"],diff:3,hint:"« Demain, dès l'aube » en fait partie.",expl:"« Les Contemplations » (1856) sont un recueil de poèmes lyriques, en partie consacré au deuil de Léopoldine."},
{id:"FR-4E-535",classe:"4ème",cat:"📖",type:"Français",enonce:"Que signifie l'adjectif « prolixe » ?",rep:"qui parle trop longuement",choix:["qui parle trop longuement", "qui reste silencieux", "qui parle à voix basse", "qui parle avec colère"],diff:4,hint:"Son contraire est « concis ».",expl:"Une personne prolixe s'exprime avec trop de mots, trop longuement ; le contraire est « concis »."},
{id:"FR-4E-536",classe:"4ème",cat:"📖",type:"Français",enonce:"Que signifie la racine grecque « biblio- » dans « bibliothèque » ?",rep:"livre",choix:["lecture", "écriture", "savoir", "livre"],diff:2,hint:"Pense aussi à « bibliographie ».",expl:"« Biblion » signifie livre en grec : bibliothèque = lieu où l'on range les livres."},
{id:"FR-4E-537",classe:"4ème",cat:"📖",type:"Français",enonce:"Quel mot contient la racine grecque « chronos », le temps ?",rep:"chronologie",choix:["chronologie", "chromatique", "chirurgie", "chlorophylle"],diff:3,hint:"Cherche le mot qui parle d'un ordre dans le temps.",expl:"« Chronologie » = étude de l'ordre du temps. « Chroma » (couleur), « chlôros » (vert), « kheir » (main) sont d'autres racines."},
{id:"FR-4E-538",classe:"4ème",cat:"📖",type:"Français",enonce:"Que signifie le mot « philanthrope » ?",rep:"qui aime les hommes",choix:["qui aime les hommes", "qui soigne les hommes", "qui déteste les hommes", "qui étudie les hommes"],diff:3,hint:"« Philo- » signifie aimer, « anthropos » l'être humain.",expl:"« Philos » (qui aime) + « anthropos » (homme) : le philanthrope aide ses semblables. Le contraire est « misanthrope »."},
{id:"FR-4E-539",classe:"4ème",cat:"📖",type:"Français",enonce:"Quel mode suit normalement « après que » ?",rep:"l'indicatif",choix:["le conditionnel", "l'impératif", "l'indicatif", "le subjonctif"],diff:4,hint:"Après que, l'action a vraiment eu lieu.",expl:"« Après que » exprime un fait réel et accompli : il se construit avec l'indicatif, contrairement à « avant que »."},
{id:"FR-4E-540",classe:"4ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « savoir » au subjonctif présent, 1re personne du singulier ?",rep:"que je sache",choix:["que je sais", "que je sache", "que je saurais", "que je savais"],diff:3,hint:"Pense à « Pas que je sache ».",expl:"Le subjonctif présent de « savoir » a un radical irrégulier : que je sache, que nous sachions."},
{id:"FR-4E-541",classe:"4ème",cat:"📖",type:"Français",enonce:"Quelle est la forme de « croire » au passé simple, 3e personne du singulier ?",rep:"il crut",choix:["il croît", "il crut", "il croya", "il croyait"],diff:3,hint:"Ce passé simple est en -u.",expl:"« Croire » fait « il crut » au passé simple. « Il croît » (avec accent) vient de « croître »."},
{id:"FR-4E-542",classe:"4ème",cat:"📖",type:"Français",enonce:"Quel est l'infinitif de « nous acquérons » ?",rep:"acquérir",choix:["acquéroir", "acquérir", "acquérer", "acquerrer"],diff:3,hint:"Pense à « conquérir », qui se conjugue de la même façon.",expl:"« Nous acquérons » vient d'« acquérir », verbe du 3e groupe comme « conquérir » (radical acquér-/acquièr-)."},
{id:"FR-4E-543",classe:"4ème",cat:"📖",type:"Français",enonce:"Combien d'expansions du nom « roman » y a-t-il dans « un roman d'aventures passionnant » ?",rep:"2",choix:["2", "1", "3", "0"],diff:3,hint:"Cherche un complément du nom et un adjectif épithète.",expl:"« D'aventures » est complément du nom et « passionnant » adjectif épithète : 2 expansions."},
{id:"FR-4E-544",classe:"4ème",cat:"📖",type:"Français",enonce:"Dans un texte argumentatif, comment appelle-t-on l'idée que défend l'auteur ?",rep:"la thèse",choix:["la thèse", "l'exemple", "l'argument", "la concession"],diff:2,hint:"Les arguments servent à la soutenir.",expl:"La thèse est l'opinion défendue ; les arguments la justifient et les exemples illustrent les arguments."},
{id:"FR-4E-545",classe:"4ème",cat:"📖",type:"Français",enonce:"Quel est le discours indirect de : Il a dit : « Je viendrai demain. » ?",rep:"Il a dit qu'il viendrait le lendemain.",choix:["Il a dit qu'il viendrait le lendemain.", "Il a dit qu'il venait le lendemain.", "Il a dit que je viendrais le lendemain.", "Il a dit qu'il viendra demain."],diff:4,hint:"Le verbe introducteur est au passé : temps et repères changent.",expl:"Après un verbe au passé, le futur devient conditionnel (futur dans le passé) et « demain » devient « le lendemain »."},
{id:"GE-6E-501",classe:"6ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on une très grande ville qui concentre habitants, activités et pouvoirs de décision ?",rep:"Une métropole",choix:["Un bourg rural", "Une périphérie", "Une banlieue", "Une métropole"],diff:2,hint:"Pense aux villes comme Paris, Lyon ou Londres qui commandent un vaste territoire.",expl:"Une métropole est une grande ville qui rassemble population, emplois, sièges d'entreprises et pouvoirs, et qui rayonne sur un large territoire."},
{id:"GE-6E-502",classe:"6ème",cat:"🌍",type:"Géographie",enonce:"Un espace de 20 km² compte 400 habitants. Quelle est sa densité de population ?",rep:"20 hab./km²",choix:["0,05 hab./km²", "380 hab./km²", "20 hab./km²", "8 000 hab./km²"],diff:3,hint:"La densité = nombre d'habitants ÷ superficie.",expl:"Densité = habitants ÷ superficie : 400 ÷ 20 = 20 habitants par km². C'est un espace de faible densité."},
{id:"GE-6E-503",classe:"6ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on la concentration croissante des habitants et des activités sur les côtes ?",rep:"La littoralisation",choix:["La périurbanisation", "La désertification", "L'exode rural", "La littoralisation"],diff:3,hint:"Les ports, les plages et le tourisme attirent de plus en plus de monde au bord de la mer.",expl:"La littoralisation désigne le mouvement des hommes et des activités vers les littoraux, attractifs pour le tourisme, les ports et le cadre de vie."},
{id:"GE-6E-504",classe:"6ème",cat:"🌍",type:"Géographie",enonce:"Quels sont les trois grands foyers de peuplement du monde ?",rep:"Asie de l'Est, Asie du Sud, Europe",choix:["Amérique du Nord, Afrique, Océanie", "Europe, Amazonie, Sibérie", "Asie de l'Est, Asie du Sud, Europe", "Asie du Sud, Sahara, Canada"],diff:2,hint:"Pense aux pays les plus peuplés : la Chine et l'Inde, puis un vieux continent.",expl:"Plus de la moitié de l'humanité vit en Asie de l'Est (Chine, Japon), en Asie du Sud (Inde) et en Europe, des régions aux plaines fertiles."},
{id:"GE-6E-505",classe:"6ème",cat:"🌍",type:"Géographie",enonce:"Quelle est la principale contrainte qui limite le peuplement du Sahara ?",rep:"Le manque d'eau",choix:["Le froid intense", "Les pentes très fortes", "L'excès de pluie", "Le manque d'eau"],diff:2,hint:"Le Sahara est un désert chaud : qu'est-ce qui y manque le plus ?",expl:"Le Sahara reçoit très peu de pluie : l'aridité est sa contrainte majeure. Les habitants se regroupent autour des oasis où l'eau est disponible."},
{id:"GE-6E-506",classe:"6ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on l'extension des villes sur les campagnes qui les entourent ?",rep:"L'étalement urbain",choix:["L'exode rural", "La désertification", "La littoralisation", "L'étalement urbain"],diff:3,hint:"Lotissements et zones commerciales grignotent les champs en bordure de la ville.",expl:"L'étalement urbain, c'est l'avancée de la ville (lotissements, zones commerciales) sur les espaces agricoles et naturels qui l'entourent."},
{id:"GE-6E-507",classe:"6ème",cat:"🌍",type:"Géographie",enonce:"Dans un espace montagnard, à quoi sert un parc national ?",rep:"À protéger la nature et les paysages",choix:["À construire de nouvelles routes", "À développer les stations de ski", "À protéger la nature et les paysages", "À installer des usines d'énergie"],diff:2,hint:"Le mot « parc » évoque un espace préservé pour sa faune et sa flore.",expl:"Un parc national protège un espace naturel remarquable (faune, flore, paysages) : les constructions et certaines activités y sont strictement réglementées."},
{id:"GE-5E-501",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Comment calcule-t-on l'accroissement naturel d'une population ?",rep:"Naissances − décès",choix:["Naissances + décès", "Décès − arrivées", "Naissances − décès", "Arrivées − départs"],diff:2,hint:"« Naturel » : on ne compte que ce qui se passe à l'intérieur du pays.",expl:"L'accroissement naturel est la différence entre les naissances et les décès. Les arrivées et départs relèvent, eux, du solde migratoire."},
{id:"GE-5E-502",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on la différence entre les arrivées et les départs de migrants ?",rep:"Le solde migratoire",choix:["Le solde migratoire", "Le taux de natalité", "L'accroissement naturel", "L'indice de fécondité"],diff:2,hint:"Le mot « migration » désigne les déplacements de population.",expl:"Le solde migratoire = immigrants − émigrants. Ajouté à l'accroissement naturel, il donne la variation totale de la population."},
{id:"GE-5E-503",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Pendant la transition démographique, quel taux baisse en premier ?",rep:"Le taux de mortalité",choix:["L'espérance de vie", "Le solde migratoire", "Le taux de mortalité", "Le taux de natalité"],diff:3,hint:"Les progrès de la médecine et de l'hygiène agissent d'abord.",expl:"La mortalité baisse d'abord grâce à la médecine et à l'hygiène ; la natalité ne baisse qu'ensuite. Entre les deux, la population augmente fortement."},
{id:"GE-5E-504",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quelle est la conséquence d'une faible fécondité qui dure longtemps, comme au Japon ?",rep:"Le vieillissement de la population",choix:["Un rajeunissement de la population", "Une explosion démographique", "Une hausse de la natalité", "Le vieillissement de la population"],diff:2,hint:"S'il naît peu d'enfants, quelle part de la population devient plus importante ?",expl:"Avec peu de naissances et une longue espérance de vie, la part des personnes âgées augmente : c'est le vieillissement démographique."},
{id:"GE-5E-505",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Entre quelles valeurs l'indice de développement humain (IDH) varie-t-il ?",rep:"Entre 0 et 1",choix:["Entre 1 et 5", "Entre 0 et 100", "Entre 0 et 10", "Entre 0 et 1"],diff:3,hint:"Ce n'est ni une note sur 10, ni un pourcentage.",expl:"L'IDH est un indice compris entre 0 et 1 : plus il est proche de 1, plus le pays est développé (santé, éducation, niveau de vie)."},
{id:"GE-5E-506",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quel indicateur donne le nombre moyen d'enfants par femme ?",rep:"L'indice de fécondité",choix:["Le taux de mortalité", "Le taux de natalité", "L'indice de fécondité", "L'espérance de vie"],diff:3,hint:"Cet indicateur se calcule par femme, pas pour 1 000 habitants.",expl:"L'indice (synthétique) de fécondité mesure le nombre moyen d'enfants par femme. Le taux de natalité, lui, compte les naissances pour 1 000 habitants."},
{id:"GE-5E-507",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Combien d'enfants par femme faut-il environ pour renouveler les générations ?",rep:"2,1",choix:["3,5", "4,0", "1,1", "2,1"],diff:3,hint:"Il faut remplacer les deux parents, plus un petit peu pour compenser les décès précoces.",expl:"Le seuil de renouvellement est d'environ 2,1 enfants par femme : 2 pour remplacer les parents, un peu plus pour compenser la mortalité des enfants."},
{id:"GE-5E-508",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Une pyramide des âges à base très large indique une population…",rep:"jeune, avec une forte natalité",choix:["jeune, avec une forte natalité", "âgée, avec une faible natalité", "âgée, avec une forte mortalité", "stable, sans aucune naissance"],diff:2,hint:"La base de la pyramide représente les enfants.",expl:"La base d'une pyramide correspond aux plus jeunes : si elle est large, il y a beaucoup d'enfants, donc une forte natalité et une population jeune."},
{id:"GE-5E-509",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quels sont les trois piliers du développement durable ?",rep:"Économique, social, environnemental",choix:["Local, national, mondial", "Économique, social, environnemental", "Agricole, industriel, commercial", "Politique, militaire, culturel"],diff:2,hint:"Il faut concilier l'argent, les hommes et la planète.",expl:"Le développement durable cherche à concilier efficacité économique, équité sociale et protection de l'environnement, pour aujourd'hui et pour les générations futures."},
{id:"GE-5E-510",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on un quartier d'habitat précaire construit sans autorisation ?",rep:"Un bidonville",choix:["Un grand ensemble", "Une ville nouvelle", "Un quartier d'affaires", "Un bidonville"],diff:2,hint:"Les maisons y sont faites de tôle, de bois ou de matériaux de récupération.",expl:"Un bidonville est un quartier d'habitat illégal et précaire, souvent sans eau courante ni assainissement, fréquent dans les grandes villes des pays pauvres."},
{id:"GE-5E-511",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Laquelle de ces énergies est renouvelable ?",rep:"L'énergie éolienne",choix:["Le charbon", "L'uranium", "L'énergie éolienne", "Le gaz naturel"],diff:2,hint:"Une énergie renouvelable ne s'épuise pas à l'échelle humaine.",expl:"Le vent se renouvelle sans cesse : l'éolien est renouvelable. Le charbon, le gaz et l'uranium sont des stocks limités qui s'épuisent."},
{id:"GE-5E-512",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Pourquoi le pétrole est-il une ressource non renouvelable ?",rep:"Il met des millions d'années à se former",choix:["Il se trouve sous la mer", "Il pollue l'atmosphère", "Il est trop cher à extraire", "Il met des millions d'années à se former"],diff:3,hint:"Compare le temps de formation au temps de consommation.",expl:"Une ressource est non renouvelable quand elle se forme bien plus lentement qu'on ne la consomme : le pétrole demande des millions d'années."},
{id:"GE-5E-513",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on la situation où les besoins en eau dépassent l'eau disponible ?",rep:"Le stress hydrique",choix:["Le stress hydrique", "L'irrigation", "Le dessalement", "La crue"],diff:3,hint:"On l'observe dans des régions arides très peuplées, comme le Moyen-Orient.",expl:"On parle de stress hydrique lorsque la demande en eau est supérieure aux ressources disponibles, comme au Moyen-Orient ou en Afrique du Nord."},
{id:"GE-5E-514",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quelle activité consomme le plus d'eau douce dans le monde ?",rep:"L'agriculture",choix:["L'agriculture", "Les usages domestiques", "Le tourisme", "L'industrie"],diff:3,hint:"Pense à l'irrigation des champs.",expl:"L'agriculture, surtout l'irrigation, utilise environ 70 % de l'eau douce prélevée dans le monde, loin devant l'industrie et les ménages."},
{id:"GE-5E-515",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quelle technique permet d'obtenir de l'eau douce à partir d'eau de mer ?",rep:"Le dessalement",choix:["Le dessalement", "Le drainage", "L'assainissement", "L'irrigation"],diff:2,hint:"Que faut-il retirer de l'eau de mer pour la boire ?",expl:"Le dessalement retire le sel de l'eau de mer. Très utilisé dans les pays du Golfe, il coûte cher et consomme beaucoup d'énergie."},
{id:"GE-5E-516",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Le grand barrage de la Renaissance, source de tensions avec l'Égypte, est construit dans quel pays ?",rep:"L'Éthiopie",choix:["Le Soudan", "Le Kenya", "L'Ouganda", "L'Éthiopie"],diff:4,hint:"Le Nil Bleu prend sa source sur les hauts plateaux de ce pays.",expl:"Le barrage de la Renaissance est construit par l'Éthiopie sur le Nil Bleu. L'Égypte, en aval, craint de manquer d'eau : l'eau est un enjeu géopolitique."},
{id:"GE-5E-517",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"On parle d'insécurité alimentaire quand une population…",rep:"n'a pas accès à assez de nourriture",choix:["mange surtout des plats industriels", "cultive ses propres légumes", "n'a pas accès à assez de nourriture", "importe une partie de ses aliments"],diff:2,hint:"Il s'agit d'un manque de nourriture, en quantité ou en qualité.",expl:"L'insécurité alimentaire désigne le fait de ne pas avoir un accès régulier à une nourriture suffisante et saine. Elle touche surtout des pays pauvres."},
{id:"GE-5E-518",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Qu'a permis la « révolution verte » en Inde à partir des années 1960 ?",rep:"Augmenter les rendements agricoles",choix:["Développer l'énergie solaire", "Augmenter les rendements agricoles", "Reboiser les montagnes", "Supprimer l'irrigation"],diff:3,hint:"Semences sélectionnées, engrais et irrigation : dans quel but ?",expl:"La révolution verte a combiné semences améliorées, engrais et irrigation pour produire beaucoup plus par hectare, mais avec des effets sur les sols et l'eau."},
{id:"GE-5E-519",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quel est un inconvénient majeur de l'agriculture intensive ?",rep:"La pollution des sols et des eaux",choix:["Des rendements très faibles", "L'absence de production", "La pollution des sols et des eaux", "Le manque de machines"],diff:2,hint:"Pense aux engrais et aux pesticides utilisés en grande quantité.",expl:"L'agriculture intensive produit beaucoup, mais l'usage massif d'engrais et de pesticides pollue les sols, les rivières et les nappes souterraines."},
{id:"GE-5E-520",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Que produit d'abord une agriculture vivrière ?",rep:"De quoi nourrir la famille de l'agriculteur",choix:["Des plantes pour les biocarburants", "Des matières premières pour l'industrie", "Des produits destinés à l'exportation", "De quoi nourrir la famille de l'agriculteur"],diff:3,hint:"« Vivrière » vient du verbe « vivre ».",expl:"L'agriculture vivrière sert d'abord à nourrir l'agriculteur et sa famille ; l'agriculture commerciale vend sa production, parfois à l'étranger."},
{id:"GE-5E-521",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quel organisme de l'ONU publie des rapports scientifiques sur le changement climatique ?",rep:"Le GIEC",choix:["L'OMC", "L'OMS", "Le GIEC", "L'UNESCO"],diff:3,hint:"Ce groupe d'experts a reçu le prix Nobel de la paix en 2007.",expl:"Le GIEC (Groupe d'experts intergouvernemental sur l'évolution du climat) rassemble les travaux des scientifiques et alerte sur le réchauffement et ses effets."},
{id:"GE-5E-522",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quelles sont les deux causes principales de la hausse du niveau des océans ?",rep:"Fonte des glaciers et dilatation de l'eau",choix:["Érosion des côtes et volcanisme", "Fonte de la banquise et pluies plus fortes", "Fonte des glaciers et dilatation de l'eau", "Séismes sous-marins et marées"],diff:4,hint:"Un glaçon qui fond dans un verre plein ne le fait pas déborder : pense à la banquise.",expl:"La mer monte car la glace des continents (glaciers, inlandsis) fond et l'eau se dilate en se réchauffant. La banquise, déjà dans l'eau, joue très peu."},
{id:"GE-5E-523",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"En géographie, un risque naît de la rencontre entre…",rep:"un aléa et des enjeux vulnérables",choix:["un aléa et des enjeux vulnérables", "un aléa et un espace désert", "deux phénomènes naturels", "une catastrophe et sa réparation"],diff:3,hint:"Un séisme dans un désert vide n'est pas un risque pour les hommes.",expl:"Il y a risque quand un aléa (séisme, crue…) peut toucher des populations, des biens ou des activités vulnérables. Sans enjeux humains, pas de risque."},
{id:"GE-5E-524",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on un phénomène naturel potentiellement dangereux, comme un séisme ou une crue ?",rep:"Un aléa",choix:["Une vulnérabilité", "Un aléa", "Une catastrophe", "Un enjeu"],diff:3,hint:"C'est le phénomène lui-même, avant de savoir s'il touchera des habitants.",expl:"L'aléa est le phénomène naturel ou technologique possible. Il devient catastrophe seulement s'il se produit et cause de lourds dégâts humains."},
{id:"GE-5E-525",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Pourquoi un séisme fait-il souvent plus de victimes dans un pays pauvre ?",rep:"Bâtiments et secours y sont moins adaptés",choix:["Bâtiments et secours y sont moins adaptés", "Les plaques tectoniques y sont plus fines", "La population y est moins nombreuse", "Les séismes y sont toujours plus forts"],diff:2,hint:"Pense à la vulnérabilité : constructions, prévention, hôpitaux.",expl:"À aléa égal, les dégâts dépendent de la vulnérabilité : normes parasismiques, secours et prévention manquent souvent dans les pays pauvres."},
{id:"GE-5E-526",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quelle catastrophe industrielle a frappé Bhopal, en Inde, en 1984 ?",rep:"Une fuite de gaz toxique",choix:["Une fuite de gaz toxique", "Un accident nucléaire", "Une marée noire", "La rupture d'un barrage"],diff:4,hint:"L'accident a eu lieu dans une usine de pesticides.",expl:"À Bhopal, une usine de pesticides a laissé échapper un gaz toxique, tuant des milliers d'habitants : c'est un exemple de risque industriel en ville."},
{id:"GE-5E-527",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quelle ville française a connu l'explosion de l'usine chimique AZF en 2001 ?",rep:"Toulouse",choix:["Lyon", "Rouen", "Toulouse", "Marseille"],diff:3,hint:"C'est la grande ville de la Garonne, capitale de l'aéronautique.",expl:"En 2001, l'usine AZF a explosé à Toulouse, faisant 31 morts. Elle montre le danger des sites industriels proches des quartiers habités."},
{id:"GE-5E-528",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quel événement a provoqué l'accident nucléaire de Fukushima en 2011 ?",rep:"Un séisme suivi d'un tsunami",choix:["Une erreur lors d'un test", "Une éruption volcanique", "Un séisme suivi d'un tsunami", "Un incendie de forêt"],diff:2,hint:"Le Japon est situé sur des failles actives, au bord de l'océan.",expl:"Un très fort séisme a déclenché un tsunami qui a noyé la centrale de Fukushima : un aléa naturel a provoqué un accident technologique."},
{id:"GE-5E-529",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quel document limite les constructions dans les zones à risque en France ?",rep:"Le plan de prévention des risques",choix:["Le plan de déplacements urbains", "Le recensement de la population", "Le schéma régional des transports", "Le plan de prévention des risques"],diff:3,hint:"Il est établi par l'État et s'impose aux plans d'urbanisme des communes.",expl:"Le plan de prévention des risques (PPR) cartographie les zones dangereuses (inondation, avalanche…) et y interdit ou encadre les constructions."},
{id:"GE-5E-530",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on un cyclone tropical qui se forme dans l'Atlantique Nord ?",rep:"Un ouragan",choix:["Un typhon", "Un ouragan", "Une tornade", "Une mousson"],diff:3,hint:"C'est le nom utilisé aux Antilles et aux États-Unis.",expl:"Un cyclone tropical s'appelle ouragan dans l'Atlantique Nord, typhon dans le Pacifique Nord-Ouest. Une tornade est un phénomène bien plus petit."},
{id:"GE-5E-531",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Qu'apporte la mousson d'été en Asie du Sud ?",rep:"De fortes pluies",choix:["De fortes pluies", "Des vents glacés", "Une grande sécheresse", "Des chutes de neige"],diff:2,hint:"Les rizières en dépendent chaque année.",expl:"La mousson d'été est un vent humide venu de l'océan Indien qui apporte de fortes pluies, indispensables aux cultures mais source d'inondations."},
{id:"GE-5E-532",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quelle source d'énergie produit la majorité de l'électricité en France ?",rep:"Le nucléaire",choix:["Le charbon", "Le nucléaire", "Le gaz", "L'éolien"],diff:2,hint:"La France compte de nombreux réacteurs le long de ses fleuves.",expl:"Grâce à son parc de centrales, la France produit la majorité de son électricité avec le nucléaire, une énergie peu émettrice de CO2 mais non renouvelable."},
{id:"GE-5E-533",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quelle organisation regroupe de grands pays exportateurs de pétrole ?",rep:"L'OPEP",choix:["L'ASEAN", "L'OTAN", "L'OMC", "L'OPEP"],diff:3,hint:"L'Arabie saoudite et le Venezuela en font partie.",expl:"L'OPEP (Organisation des pays exportateurs de pétrole), dont l'Arabie saoudite, coordonne la production de ses membres pour peser sur les prix."},
{id:"GE-5E-534",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Construire des digues face à la montée des eaux est une mesure…",rep:"d'adaptation",choix:["de reboisement", "d'atténuation", "d'adaptation", "de délocalisation"],diff:4,hint:"On ne réduit pas le réchauffement, on s'organise pour vivre avec.",expl:"S'adapter, c'est se protéger des effets du changement climatique (digues). Atténuer, c'est réduire ses causes, comme les émissions de gaz à effet de serre."},
{id:"GE-5E-535",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on les ressources tirées de la pêche ?",rep:"Les ressources halieutiques",choix:["Les ressources forestières", "Les ressources minières", "Les ressources halieutiques", "Les ressources énergétiques"],diff:3,hint:"Il s'agit des poissons, crustacés et coquillages.",expl:"Les ressources halieutiques sont les poissons et fruits de mer exploités par la pêche. Elles se renouvellent, mais peuvent s'épuiser si on pêche trop."},
{id:"GE-5E-536",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Quelle est la principale conséquence de la surpêche ?",rep:"L'épuisement des stocks de poissons",choix:["La disparition des marées", "La hausse du niveau des mers", "L'acidification des fleuves", "L'épuisement des stocks de poissons"],diff:2,hint:"On pêche plus vite que les poissons ne se reproduisent.",expl:"Quand on prélève plus de poissons qu'il n'en naît, les stocks diminuent jusqu'à s'effondrer : une ressource renouvelable peut donc s'épuiser."},
{id:"GE-5E-537",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Que mesure l'espérance de vie à la naissance ?",rep:"Le nombre moyen d'années à vivre",choix:["Le nombre de décès par an", "Le nombre moyen d'années à vivre", "L'âge du plus vieil habitant", "L'âge moyen de la population"],diff:2,hint:"On imagine un bébé qui vient de naître : combien d'années peut-il espérer ?",expl:"L'espérance de vie à la naissance est la durée de vie moyenne d'un nouveau-né selon les conditions actuelles. C'est un bon indicateur de développement."},
{id:"GE-5E-538",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Le taux de mortalité infantile compte les décès d'enfants de moins de…",rep:"1 an",choix:["5 ans", "1 an", "18 ans", "10 ans"],diff:3,hint:"« Infantile » concerne ici les nourrissons.",expl:"La mortalité infantile mesure les décès avant 1 an pour 1 000 naissances. Elle est élevée là où l'accès aux soins et à l'eau potable est faible."},
{id:"GE-5E-539",classe:"5ème",cat:"🌍",type:"Géographie",enonce:"Pourquoi l'accès à l'eau potable est-il inégal dans le monde ?",rep:"Ressources et équipements sont inégalement répartis",choix:["Les pays pauvres refusent l'eau potable", "Ressources et équipements sont inégalement répartis", "Toute l'eau de pluie s'évapore sous les tropiques", "L'eau douce n'existe que dans les pays riches"],diff:3,hint:"Il faut de l'eau, mais aussi des moyens pour la traiter et la distribuer.",expl:"L'eau potable dépend des pluies et des réserves, mais aussi des réseaux, stations d'épuration et moyens financiers : deux inégalités qui se cumulent."},
{id:"GE-4E-501",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on une ville de plus de 10 millions d'habitants ?",rep:"Une mégapole",choix:["Une conurbation", "Une mégalopole", "Une technopole", "Une mégapole"],diff:3,hint:"Attention à ne pas confondre avec un mot plus long qui désigne un ensemble de villes.",expl:"Une mégapole est une ville de plus de 10 millions d'habitants (Tokyo, Lagos). À ne pas confondre avec la mégalopole, chaîne de grandes villes."},
{id:"GE-4E-502",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Qu'est-ce qu'une mégalopole ?",rep:"Une chaîne de grandes villes reliées entre elles",choix:["Une ville de plus de 10 millions d'habitants", "Un quartier d'affaires très dense", "Une chaîne de grandes villes reliées entre elles", "Une ville nouvelle construite près d'une capitale"],diff:4,hint:"Exemple : de Boston à Washington, les villes se suivent presque sans interruption.",expl:"Une mégalopole est un vaste ensemble urbain formé de plusieurs métropoles reliées par des flux intenses, comme la mégalopole japonaise de Tokyo à Osaka."},
{id:"GE-4E-503",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Quelles villes sont considérées comme les grandes villes mondiales au sommet de la hiérarchie ?",rep:"New York, Londres, Tokyo",choix:["Sydney, Rio, Dubaï", "New York, Londres, Tokyo", "Lagos, Mumbai, Le Caire", "Rome, Madrid, Berlin"],diff:2,hint:"Pense aux villes qui abritent les plus grandes Bourses du monde.",expl:"New York, Londres et Tokyo concentrent sièges de firmes, Bourses et pouvoirs de décision : ce sont des villes mondiales qui commandent l'économie."},
{id:"GE-4E-504",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Le taux d'urbanisation mesure la part de la population…",rep:"qui vit en ville",choix:["qui travaille dans l'industrie", "qui possède un logement", "qui migre vers l'étranger", "qui vit en ville"],diff:2,hint:"« Urbain » signifie « de la ville ».",expl:"Le taux d'urbanisation est le pourcentage de la population totale qui habite en ville. Il augmente dans le monde entier, surtout dans les pays du Sud."},
{id:"GE-4E-505",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on le quartier d'affaires central des villes nord-américaines ?",rep:"Le CBD",choix:["Le ghetto", "Le suburb", "Le township", "Le CBD"],diff:3,hint:"On y trouve les gratte-ciel et les sièges des banques, au cœur de la ville.",expl:"Le CBD (Central Business District) regroupe gratte-ciel, sièges sociaux et banques au cœur des villes américaines. Les suburbs sont les banlieues résidentielles."},
{id:"GE-4E-506",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on un quartier résidentiel fermé et surveillé, réservé à des habitants aisés ?",rep:"Une gated community",choix:["Un bidonville", "Un grand ensemble", "Une favela", "Une gated community"],diff:3,hint:"On en trouve beaucoup aux États-Unis et en Amérique latine ; son nom est anglais.",expl:"Une gated community est un quartier clos, gardé, où les plus riches s'isolent du reste de la ville : c'est une forme de ségrégation spatiale."},
{id:"GE-4E-507",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Comment nomme-t-on les bidonvilles au Brésil ?",rep:"Les favelas",choix:["Les favelas", "Les suburbs", "Les médinas", "Les townships"],diff:2,hint:"On en trouve beaucoup sur les collines de Rio de Janeiro.",expl:"Au Brésil, les bidonvilles s'appellent favelas. Les townships sont des quartiers ségrégués d'Afrique du Sud, les médinas des vieilles villes arabes."},
{id:"GE-4E-508",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Qu'est-ce qu'un hub aéroportuaire ?",rep:"Un aéroport-pivot où convergent de nombreuses lignes",choix:["Un aéroport-pivot où convergent de nombreuses lignes", "Une gare reliée à un port de commerce", "Un aéroport fermé au trafic international", "Un petit aéroport réservé aux avions privés"],diff:3,hint:"« Hub » signifie « moyeu » en anglais : le centre d'une roue.",expl:"Un hub est une plateforme de correspondance où convergent de nombreuses lignes (Dubaï, Paris-CDG). Il montre qu'une ville est bien connectée au monde."},
{id:"GE-4E-509",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on une personne qui fuit son pays à cause de persécutions et obtient une protection ?",rep:"Un réfugié",choix:["Un travailleur saisonnier", "Un réfugié", "Un touriste", "Un expatrié"],diff:2,hint:"Son statut est défini par la convention de Genève de 1951.",expl:"Un réfugié a fui son pays par crainte de persécutions ou de guerre et obtient une protection internationale. Un expatrié part travailler volontairement."},
{id:"GE-4E-510",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on l'argent envoyé par les migrants à leur famille restée au pays ?",rep:"Les remises",choix:["Les remises", "Les droits de douane", "Les subventions", "Les dividendes"],diff:3,hint:"Ce ne sont ni des taxes ni des aides publiques : c'est de l'argent privé envoyé aux proches.",expl:"Les remises (transferts de fonds) des migrants sont une ressource essentielle pour de nombreux pays du Sud, parfois plus importante que l'aide internationale."},
{id:"GE-4E-511",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Quelle est la principale cause des migrations internationales ?",rep:"La recherche d'un emploi",choix:["La recherche d'un emploi", "Le tourisme", "Les études à l'étranger", "Le départ à la retraite"],diff:2,hint:"La plupart des migrants veulent améliorer leurs conditions de vie.",expl:"La majorité des migrants partent pour des raisons économiques : trouver un travail et de meilleurs revenus. Guerres et persécutions poussent aussi au départ."},
{id:"GE-4E-512",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Quelle petite île italienne, proche de la Tunisie, est une porte d'entrée de migrants en Europe ?",rep:"Lampedusa",choix:["Capri", "Elbe", "Ischia", "Lampedusa"],diff:3,hint:"Elle est plus proche de l'Afrique que de l'Italie continentale.",expl:"Lampedusa, à environ 110 km des côtes tunisiennes, est l'un des principaux points d'arrivée des migrants qui traversent la Méditerranée centrale."},
{id:"GE-4E-513",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on la saturation d'un lieu par un trop grand nombre de visiteurs ?",rep:"Le surtourisme",choix:["Le tourisme vert", "Le tourisme d'affaires", "L'écotourisme", "Le surtourisme"],diff:2,hint:"Venise ou Barcelone limitent désormais l'accès des croisiéristes pour cette raison.",expl:"Le surtourisme (Venise, Barcelone) désigne l'excès de touristes qui dégrade les sites et gêne les habitants. L'écotourisme cherche au contraire à respecter les lieux."},
{id:"GE-4E-514",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"De quel continent provient la plus grande partie des touristes internationaux ?",rep:"D'Europe",choix:["D'Océanie", "D'Europe", "D'Amérique du Sud", "D'Afrique"],diff:3,hint:"Pense aux pays riches, proches les uns des autres, où les congés payés sont longs.",expl:"L'Europe est à la fois la première région émettrice et réceptrice de touristes : niveau de vie élevé, congés et nombreux pays voisins favorisent les voyages."},
{id:"GE-4E-515",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on le fait que l'économie mondiale passe de plus en plus par la mer ?",rep:"La maritimisation",choix:["La littoralisation", "La métropolisation", "La régionalisation", "La maritimisation"],diff:3,hint:"Pense aux porte-conteneurs, aux ports géants et aux ressources des océans.",expl:"La maritimisation est le rôle croissant des mers dans l'économie : transport des marchandises, ressources, ports. La littoralisation concerne les hommes sur les côtes."},
{id:"GE-4E-516",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Quelle invention a révolutionné le transport maritime de marchandises au XXe siècle ?",rep:"Le conteneur",choix:["Le sous-marin", "La machine à vapeur", "Le conteneur", "Le paquebot"],diff:2,hint:"C'est une grande boîte métallique standardisée.",expl:"Le conteneur, boîte de taille standard, se transfère facilement du navire au train ou au camion. Il a fait baisser les coûts et accéléré la mondialisation."},
{id:"GE-4E-517",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Quelle part environ du commerce mondial, en volume, passe par la mer ?",rep:"Environ 80 %",choix:["Environ 20 %", "Environ 5 %", "Environ 80 %", "Environ 50 %"],diff:3,hint:"Le bateau est de loin le moyen le moins cher pour transporter en masse.",expl:"Environ 80 % des marchandises échangées dans le monde voyagent par bateau, car c'est le transport le moins coûteux pour de grandes quantités."},
{id:"GE-4E-518",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on un littoral qui regroupe plusieurs grands ports proches ?",rep:"Une façade maritime",choix:["Une façade maritime", "Un hinterland", "Une ZEE", "Un détroit"],diff:3,hint:"Exemple : la Northern Range, du Havre à Hambourg.",expl:"Une façade maritime est un ensemble de ports voisins, ouverts sur le monde et reliés à leur arrière-pays, comme la Northern Range en Europe."},
{id:"GE-4E-519",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Que désigne l'hinterland d'un port ?",rep:"L'arrière-pays qu'il dessert",choix:["La ville qui lui fait concurrence", "L'arrière-pays qu'il dessert", "La zone de pêche qui l'entoure", "Le bassin où arrivent les navires"],diff:3,hint:"C'est un espace à l'intérieur des terres, relié au port par routes, rails et fleuves.",expl:"L'hinterland est l'espace intérieur desservi par un port : d'où viennent et où vont les marchandises. Plus il est vaste, plus le port est puissant."},
{id:"GE-4E-520",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Quel est le premier port d'Europe ?",rep:"Rotterdam",choix:["Hambourg", "Anvers", "Rotterdam", "Le Havre"],diff:3,hint:"Il se trouve aux Pays-Bas, à l'embouchure du Rhin.",expl:"Rotterdam est le premier port d'Europe grâce à sa position à l'embouchure du Rhin, qui lui ouvre un immense arrière-pays industriel."},
{id:"GE-4E-521",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Pourquoi beaucoup de navires sont-ils immatriculés au Panama ou au Liberia ?",rep:"Taxes et règles y sont plus faibles",choix:["Ces pays construisent tous les navires", "Ce sont les plus grands ports du monde", "Taxes et règles y sont plus faibles", "La loi oblige à s'y immatriculer"],diff:4,hint:"On parle de « pavillons de complaisance ».",expl:"Ces pays offrent des pavillons de complaisance : faibles taxes et règles sociales peu exigeantes. Les armateurs y immatriculent leurs navires pour réduire leurs coûts."},
{id:"GE-4E-522",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Quel golfe, entre le Yémen et la Somalie, a été touché par la piraterie maritime ?",rep:"Le golfe d'Aden",choix:["Le golfe du Mexique", "Le golfe Persique", "Le golfe de Guinée", "Le golfe d'Aden"],diff:4,hint:"Il relie la mer Rouge à l'océan Indien.",expl:"Le golfe d'Aden, passage vers le canal de Suez, a connu une forte piraterie somalienne : des marines de guerre y escortent les navires de commerce."},
{id:"GE-4E-523",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Qu'est-ce qu'une délocalisation ?",rep:"Le transfert d'une production vers un pays moins coûteux",choix:["Le transfert d'une production vers un pays moins coûteux", "Le rachat d'une entreprise par l'État", "La création d'une usine dans sa ville d'origine", "La fermeture définitive d'une entreprise"],diff:2,hint:"L'entreprise change de « lieu » de production.",expl:"Délocaliser, c'est déplacer une activité vers un pays où la main-d'œuvre ou les taxes coûtent moins cher, pour réduire les coûts de production."},
{id:"GE-4E-524",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on une entreprise implantée dans de nombreux pays ?",rep:"Une firme transnationale",choix:["Une petite entreprise", "Une firme transnationale", "Une coopérative agricole", "Une entreprise publique"],diff:2,hint:"Exemples : Apple, TotalEnergies ou Toyota ont des filiales sur tous les continents.",expl:"Une firme transnationale (FTN) a son siège dans un pays et des filiales dans le monde entier. Les FTN sont des actrices majeures de la mondialisation."},
{id:"GE-4E-525",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Quelle ville chinoise, voisine de Hong Kong, est devenue une zone économique spéciale en 1980 ?",rep:"Shenzhen",choix:["Xi'an", "Pékin", "Chongqing", "Shenzhen"],diff:3,hint:"Elle se trouve sur le littoral sud, face à Hong Kong.",expl:"Shenzhen, simple bourg en 1980, est devenue une métropole grâce à sa zone économique spéciale ouverte aux capitaux étrangers sur le littoral chinois."},
{id:"GE-4E-526",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on les usines d'assemblage installées côté mexicain de la frontière avec les États-Unis ?",rep:"Les maquiladoras",choix:["Les haciendas", "Les ranchos", "Les maquiladoras", "Les favelas"],diff:4,hint:"Ce mot espagnol vient de « maquilar », transformer.",expl:"Les maquiladoras assemblent, avec une main-d'œuvre mexicaine moins chère, des produits vendus aux États-Unis : la frontière est une interface Nord-Sud."},
{id:"GE-4E-527",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Quel accord de libre-échange relie les États-Unis, le Canada et le Mexique ?",rep:"L'ACEUM (ex-ALENA)",choix:["L'ASEAN", "L'Union européenne", "L'ACEUM (ex-ALENA)", "Le Mercosur"],diff:3,hint:"Il a remplacé en 2020 un accord signé en 1994.",expl:"L'ACEUM, qui a remplacé l'ALENA en 2020, organise le libre-échange entre les trois pays d'Amérique du Nord. Le Mercosur réunit des pays d'Amérique du Sud."},
{id:"GE-4E-528",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Quelle céréale domine dans la Corn Belt américaine ?",rep:"Le maïs",choix:["Le riz", "Le maïs", "L'orge", "Le blé"],diff:2,hint:"Cette céréale, originaire d'Amérique, sert beaucoup à nourrir le bétail.",expl:"La Corn Belt (« ceinture du maïs ») du Midwest est l'une des plus grandes régions productrices de maïs au monde, notamment pour l'élevage et l'exportation."},
{id:"GE-4E-529",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Quel golfe borde l'Afrique de l'Ouest et recèle d'importants gisements de pétrole ?",rep:"Le golfe de Guinée",choix:["Le golfe Persique", "Le golfe de Guinée", "Le golfe de Gascogne", "La mer Rouge"],diff:3,hint:"Il porte le nom de plusieurs pays de la région.",expl:"Le golfe de Guinée, au large du Nigeria, du Gabon ou de la Guinée équatoriale, est riche en pétrole offshore : c'est une interface majeure de l'Afrique avec la mondialisation."},
{id:"GE-4E-530",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"Quelle est la plus grande ville d'Afrique de l'Ouest ?",rep:"Lagos",choix:["Abidjan", "Accra", "Dakar", "Lagos"],diff:2,hint:"Elle se trouve au Nigeria, le pays le plus peuplé d'Afrique.",expl:"Lagos, au Nigeria, est une mégapole de plus de 10 millions d'habitants, la plus grande ville d'Afrique de l'Ouest, avec une croissance très rapide."},
{id:"GE-4E-531",classe:"4ème",cat:"🌍",type:"Géographie",enonce:"De quelle production la Côte d'Ivoire est-elle le premier producteur mondial ?",rep:"Le cacao",choix:["Le café", "L'arachide", "Le coton", "Le cacao"],diff:2,hint:"C'est la matière première du chocolat.",expl:"La Côte d'Ivoire produit environ 40 % du cacao mondial, en grande partie exporté vers l'Europe : une dépendance typique aux produits agricoles d'exportation."},
{id:"GE-3E-501",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on l'installation de citadins dans les communes rurales autour des villes ?",rep:"La périurbanisation",choix:["L'exode rural", "La littoralisation", "La gentrification", "La périurbanisation"],diff:2,hint:"Ces nouveaux habitants travaillent souvent en ville et font la navette chaque jour.",expl:"La périurbanisation est l'extension des villes vers les communes rurales voisines, où des citadins s'installent tout en travaillant dans le pôle urbain."},
{id:"GE-3E-502",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on les déplacements quotidiens entre le domicile et le lieu de travail ?",rep:"Les mobilités pendulaires",choix:["Les mobilités pendulaires", "Les flux touristiques", "Les migrations définitives", "Les mobilités saisonnières"],diff:2,hint:"Matin et soir, les routes d'accès aux villes sont saturées par ces trajets.",expl:"Les mobilités pendulaires sont les allers-retours quotidiens domicile-travail. Elles s'allongent avec la périurbanisation et provoquent des embouteillages."},
{id:"GE-3E-503",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Après Paris, quelle est la deuxième aire urbaine de France ?",rep:"Lyon",choix:["Lille", "Lyon", "Toulouse", "Marseille"],diff:3,hint:"Elle est située au confluent du Rhône et de la Saône.",expl:"Lyon forme la deuxième aire urbaine française, devant Marseille-Aix. Paris reste loin devant : le réseau urbain français est dominé par la capitale."},
{id:"GE-3E-504",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quel statut ont obtenu de grandes intercommunalités comme Lyon, Lille ou Bordeaux depuis 2014 ?",rep:"Celui de métropole",choix:["Celui de département", "Celui de métropole", "Celui de canton", "Celui de région"],diff:3,hint:"C'est aussi le nom donné aux très grandes villes.",expl:"Depuis la loi de 2014, les grandes intercommunalités peuvent devenir des métropoles, avec plus de compétences (transports, logement, économie)."},
{id:"GE-3E-505",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Dans quelle région se trouve Toulouse, capitale de l'aéronautique française ?",rep:"L'Occitanie",choix:["L'Occitanie", "Auvergne-Rhône-Alpes", "La Nouvelle-Aquitaine", "Le Grand Est"],diff:2,hint:"Cette région longe les Pyrénées et la Méditerranée.",expl:"Toulouse est la capitale de l'Occitanie. Avec Airbus et ses sous-traitants, elle forme un grand pôle aéronautique et spatial."},
{id:"GE-3E-506",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on un espace qui associe recherche, université et entreprises innovantes ?",rep:"Un technopôle",choix:["Un technopôle", "Une zone commerciale", "Un bassin minier", "Une zone industrialo-portuaire"],diff:3,hint:"Exemples : Sophia Antipolis ou la région de Grenoble.",expl:"Un technopôle rassemble universités, laboratoires et entreprises de haute technologie pour favoriser l'innovation, comme Sophia Antipolis ou Grenoble."},
{id:"GE-3E-507",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Près de quelle ville se trouve le technopôle de Sophia Antipolis ?",rep:"Antibes",choix:["Rennes", "Montpellier", "Antibes", "Grenoble"],diff:3,hint:"Il se situe sur la Côte d'Azur.",expl:"Sophia Antipolis, créé dans les années 1970 près d'Antibes, sur la Côte d'Azur, est l'un des premiers et plus grands technopôles d'Europe."},
{id:"GE-3E-508",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"À quel grand port français est rattachée la zone industrialo-portuaire de Fos-sur-Mer ?",rep:"Marseille",choix:["Nantes-Saint-Nazaire", "Dunkerque", "Marseille", "Le Havre"],diff:3,hint:"Fos-sur-Mer est située sur la Méditerranée.",expl:"Fos-sur-Mer fait partie du grand port maritime de Marseille : sidérurgie, pétrochimie et conteneurs s'y installent au bord de l'eau, c'est une ZIP."},
{id:"GE-3E-509",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quel secteur d'activité emploie la grande majorité des actifs en France ?",rep:"Le secteur tertiaire",choix:["Le secteur tertiaire", "Le secteur primaire", "Le secteur secondaire", "Les trois à parts égales"],diff:2,hint:"Ce secteur regroupe les services : commerce, santé, éducation, transports.",expl:"Environ trois actifs sur quatre travaillent dans les services (secteur tertiaire). L'agriculture (primaire) et l'industrie (secondaire) emploient beaucoup moins."},
{id:"GE-3E-510",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quel pays est le premier producteur agricole de l'Union européenne ?",rep:"La France",choix:["L'Espagne", "L'Allemagne", "La Pologne", "La France"],diff:2,hint:"Ce pays a la plus grande surface agricole de l'UE.",expl:"Grâce à sa vaste surface agricole et à ses climats variés, la France est le premier producteur agricole de l'UE, grand exportateur de céréales et de vins."},
{id:"GE-3E-511",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quel type d'agriculture domine dans la Beauce, au sud-ouest de Paris ?",rep:"Les céréales",choix:["Le maraîchage", "La vigne", "Les céréales", "L'élevage laitier"],diff:2,hint:"On la surnomme le « grenier à blé » de la France.",expl:"La Beauce, plaine aux sols fertiles, pratique une agriculture intensive et mécanisée de céréales (blé, maïs) sur de très grandes exploitations."},
{id:"GE-3E-512",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on le déclin des industries traditionnelles comme les mines ou la sidérurgie ?",rep:"La désindustrialisation",choix:["La tertiarisation", "La décentralisation", "La désindustrialisation", "La délocalisation"],diff:3,hint:"Le préfixe « dés- » indique la disparition de quelque chose.",expl:"La désindustrialisation est la baisse des emplois et des activités industrielles d'un territoire, comme dans le Nord ou la Lorraine avec la fin des mines."},
{id:"GE-3E-513",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quel territoire français a souffert de la fermeture de ses mines de charbon ?",rep:"Le Nord-Pas-de-Calais",choix:["La Beauce", "Le Nord-Pas-de-Calais", "La Côte d'Azur", "La Bretagne"],diff:2,hint:"Les terrils, collines de déchets miniers, marquent encore son paysage.",expl:"Le bassin minier du Nord-Pas-de-Calais (aujourd'hui dans les Hauts-de-France) a vu fermer toutes ses mines de charbon : chômage et reconversion ont marqué ce territoire."},
{id:"GE-3E-514",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quels espaces ruraux attirent aujourd'hui de nouveaux habitants ?",rep:"Ceux proches des villes et des littoraux",choix:["Aucun, tous se dépeuplent", "Ceux proches des villes et des littoraux", "Ceux de haute montagne uniquement", "Les plus isolés et les plus enclavés"],diff:3,hint:"Pense à l'accessibilité et au cadre de vie.",expl:"Les campagnes proches des villes, des littoraux ou bien desservies gagnent des habitants. Les espaces isolés et enclavés, eux, continuent souvent de se vider."},
{id:"GE-3E-515",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on les citadins qui s'installent durablement à la campagne ?",rep:"Les néoruraux",choix:["Les estivants", "Les saisonniers", "Les frontaliers", "Les néoruraux"],diff:2,hint:"Ils recherchent le calme, l'espace et parfois le télétravail.",expl:"Les néoruraux sont d'anciens citadins venus vivre à la campagne pour le cadre de vie, le télétravail ou un projet : ils redynamisent certains villages."},
{id:"GE-3E-516",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quel est l'objectif d'un parc naturel régional ?",rep:"Protéger le patrimoine tout en développant le territoire",choix:["Remplacer les communes par une réserve", "Interdire toute présence humaine", "Protéger le patrimoine tout en développant le territoire", "Accueillir de grandes usines"],diff:3,hint:"Contrairement au parc national, des habitants y vivent et y travaillent.",expl:"Un parc naturel régional concilie protection des paysages et développement économique (tourisme, agriculture) dans des espaces ruraux habités."},
{id:"GE-3E-517",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quelle infrastructure a fortement réduit les temps de trajet entre Paris et les grandes villes ?",rep:"Les lignes à grande vitesse",choix:["Les lignes à grande vitesse", "Les routes départementales", "Les pistes cyclables", "Les canaux de navigation"],diff:2,hint:"Le TGV y circule à plus de 300 km/h.",expl:"Les lignes à grande vitesse mettent Lyon, Marseille ou Bordeaux à quelques heures de Paris : elles rapprochent les métropoles mais pas les espaces qu'elles traversent."},
{id:"GE-3E-518",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Pourquoi dit-on que le réseau de transport français est « en étoile » ?",rep:"Il est centré sur Paris",choix:["Il est centré sur Paris", "Il suit les frontières", "Il évite les grandes villes", "Il relie surtout les ports"],diff:2,hint:"Regarde une carte des autoroutes ou des TGV : d'où partent les lignes ?",expl:"Autoroutes et voies ferrées partent de Paris vers les régions : c'est un réseau en étoile, héritage de la centralisation, qui favorise la capitale."},
{id:"GE-3E-519",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Combien de régions compte la France métropolitaine depuis 2016 ?",rep:"13",choix:["22", "13", "18", "27"],diff:3,hint:"La réforme de 2016 a fusionné plusieurs des 22 anciennes régions.",expl:"Depuis la réforme de 2016, la France métropolitaine compte 13 régions (dont la Corse) ; avec les 5 régions d'outre-mer, on arrive à 18."},
{id:"GE-3E-520",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Lequel de ces territoires est un département et région d'outre-mer (DROM) ?",rep:"La Réunion",choix:["La Nouvelle-Calédonie", "Wallis-et-Futuna", "La Polynésie française", "La Réunion"],diff:3,hint:"Les DROM sont au nombre de cinq, dont un dans l'océan Indien près de Madagascar.",expl:"Les cinq DROM sont la Guadeloupe, la Martinique, la Guyane, La Réunion et Mayotte. Les autres territoires ont des statuts particuliers (collectivités)."},
{id:"GE-3E-521",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quel territoire est devenu le 101e département français en 2011 ?",rep:"Mayotte",choix:["La Guyane", "Saint-Pierre-et-Miquelon", "La Martinique", "Mayotte"],diff:3,hint:"C'est une île de l'archipel des Comores, dans l'océan Indien.",expl:"Mayotte est devenue département en 2011, le 101e. C'est le DROM le plus jeune et le plus pauvre, avec une population très jeune."},
{id:"GE-3E-522",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Dans quelle ville de Guyane se trouve le Centre spatial guyanais ?",rep:"Kourou",choix:["Saint-Georges", "Cayenne", "Kourou", "Saint-Laurent-du-Maroni"],diff:3,hint:"Ce n'est pas la préfecture de la Guyane.",expl:"Le Centre spatial de Kourou profite de la proximité de l'équateur pour lancer les fusées européennes : un atout de la France ultramarine."},
{id:"GE-3E-523",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quelle contrainte majeure pèse sur la plupart des territoires ultramarins ?",rep:"L'éloignement de la métropole",choix:["L'absence de littoral", "Le climat polaire", "Le manque de jeunes", "L'éloignement de la métropole"],diff:2,hint:"Pense aux milliers de kilomètres qui séparent ces territoires de Paris.",expl:"L'éloignement et souvent l'insularité augmentent les coûts de transport et les prix. Les territoires ultramarins dépendent beaucoup de la métropole."},
{id:"GE-3E-524",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Comment l'Union européenne qualifie-t-elle les DROM comme la Guadeloupe ?",rep:"De régions ultrapériphériques",choix:["De zones franches européennes", "De pays et territoires associés", "De régions ultrapériphériques", "D'États membres associés"],diff:4,hint:"Elles font partie de l'UE mais sont situées très loin du continent.",expl:"Les DROM sont des régions ultrapériphériques (RUP) : elles appartiennent pleinement à l'UE et reçoivent des aides adaptées à leur éloignement."},
{id:"GE-3E-525",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quel fonds européen finance des projets pour réduire les inégalités entre régions ?",rep:"Le FEDER",choix:["Le FMI", "Le FEDER", "L'OTAN", "La BCE"],diff:3,hint:"Il fait partie de la politique de cohésion de l'Union européenne.",expl:"Le FEDER (Fonds européen de développement régional) finance routes, entreprises ou rénovations dans les régions les moins riches : c'est la politique de cohésion."},
{id:"GE-3E-526",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Que permet l'espace Schengen ?",rep:"La libre circulation des personnes",choix:["L'usage d'une monnaie unique", "La libre circulation des personnes", "Un impôt européen unique", "Une armée européenne commune"],diff:2,hint:"Il concerne les contrôles aux frontières entre pays membres.",expl:"Dans l'espace Schengen, les contrôles aux frontières intérieures sont supprimés : on circule librement, mais les frontières extérieures sont renforcées."},
{id:"GE-3E-527",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Lequel de ces pays de l'Union européenne n'utilise pas l'euro ?",rep:"La Suède",choix:["L'Irlande", "La Suède", "La Finlande", "L'Espagne"],diff:3,hint:"Ce pays scandinave a gardé sa couronne.",expl:"Tous les pays de l'UE n'ont pas adopté l'euro : la Suède conserve la couronne suédoise. Espagne, Irlande et Finlande font partie de la zone euro."},
{id:"GE-3E-528",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Lequel de ces pays fait partie de l'espace Schengen sans être membre de l'UE ?",rep:"La Suisse",choix:["Le Royaume-Uni", "La Turquie", "L'Irlande", "La Suisse"],diff:4,hint:"Attention : l'un de ces pays est dans l'UE mais pas dans Schengen.",expl:"La Suisse n'est pas dans l'UE mais applique Schengen. L'Irlande est dans l'UE sans être dans Schengen ; le Royaume-Uni et la Turquie ne sont dans aucun des deux."},
{id:"GE-3E-529",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Dans quelle ville le Parlement européen a-t-il son siège officiel ?",rep:"Strasbourg",choix:["Francfort", "Strasbourg", "Bruxelles", "Luxembourg"],diff:3,hint:"C'est une ville française, frontalière de l'Allemagne.",expl:"Le siège officiel du Parlement européen est à Strasbourg, symbole de la réconciliation franco-allemande, même si certaines sessions ont lieu à Bruxelles."},
{id:"GE-3E-530",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on une personne qui vit en France et travaille chaque jour en Suisse ?",rep:"Un frontalier",choix:["Un saisonnier", "Un expatrié", "Un frontalier", "Un réfugié"],diff:2,hint:"Elle garde son logement en France mais change de pays pour travailler.",expl:"Un travailleur frontalier vit dans un pays et travaille dans un pays voisin. Ils sont très nombreux autour de Genève et du Luxembourg, attirés par les salaires."},
{id:"GE-3E-531",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quel programme européen finance la coopération entre régions situées de part et d'autre d'une frontière ?",rep:"Interreg",choix:["Galileo", "Interreg", "Erasmus", "Copernicus"],diff:4,hint:"Il finance par exemple des lignes de bus entre la France et l'Allemagne.",expl:"Interreg finance des projets transfrontaliers (transports, santé, emploi). Erasmus concerne les études, Galileo la géolocalisation, Copernicus l'observation de la Terre."},
{id:"GE-3E-532",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quelle organisation regroupe les États et gouvernements ayant le français en partage ?",rep:"La Francophonie",choix:["Le G7", "Le Commonwealth", "L'OCDE", "La Francophonie"],diff:2,hint:"Elle compte plus de 80 États et gouvernements, dont beaucoup en Afrique.",expl:"L'Organisation internationale de la Francophonie réunit des pays ayant le français en partage : c'est un outil d'influence culturelle de la France."},
{id:"GE-3E-533",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"De quel organe de l'ONU la France est-elle membre permanent ?",rep:"Le Conseil de sécurité",choix:["La Cour internationale de justice", "L'Assemblée générale", "Le Conseil de sécurité", "L'UNESCO"],diff:2,hint:"Cet organe compte cinq membres permanents disposant d'un droit de veto.",expl:"La France est l'un des cinq membres permanents du Conseil de sécurité, avec un droit de veto : un atout majeur de sa puissance diplomatique."},
{id:"GE-3E-534",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on la capacité d'un pays à influencer par sa culture et son image ?",rep:"Le soft power",choix:["Le protectionnisme", "Le hard power", "Le soft power", "Le libre-échange"],diff:3,hint:"C'est le contraire d'une puissance fondée sur la force militaire.",expl:"Le soft power est la puissance d'influence (langue, culture, tourisme, gastronomie). Le hard power repose sur la force militaire et économique."},
{id:"GE-3E-535",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on la domination écrasante de Paris dans le réseau urbain français ?",rep:"La macrocéphalie",choix:["La macrocéphalie", "La gentrification", "La rurbanisation", "La conurbation"],diff:4,hint:"Paris pèse environ six fois plus que Lyon ; on décrit ce déséquilibre par une image du corps humain.",expl:"On parle de macrocéphalie quand une ville, ici Paris, est bien plus peuplée et puissante que toutes les autres du pays."},
{id:"GE-3E-536",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Pourquoi la périurbanisation augmente-t-elle l'usage de la voiture ?",rep:"Les transports en commun y sont rares",choix:["Les routes y sont interdites aux vélos", "Les transports en commun y sont rares", "Les habitants y travaillent à domicile", "L'essence y est moins chère"],diff:3,hint:"Habitat dispersé, emplois en ville : comment se déplacer ?",expl:"Dans les espaces périurbains, l'habitat est dispersé et loin des emplois : bus et trains y sont peu rentables, la voiture devient indispensable."},
{id:"GE-3E-537",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quelle loi de 1986 protège les côtes françaises contre l'urbanisation excessive ?",rep:"La loi Littoral",choix:["La loi Montagne", "La loi SRU", "La loi Climat", "La loi Littoral"],diff:3,hint:"Elle interdit en principe de construire dans la bande des 100 mètres du rivage.",expl:"La loi Littoral (1986) limite les constructions près du rivage pour protéger les paysages et l'accès à la mer face à la forte pression touristique."},
{id:"GE-3E-538",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quelle loi impose aux grandes communes un minimum de logements sociaux ?",rep:"La loi SRU",choix:["La loi Montagne", "La loi Évin", "La loi Littoral", "La loi SRU"],diff:4,hint:"Elle date de 2000 et vise la mixité sociale.",expl:"La loi SRU (2000) oblige les communes concernées à avoir une part minimale de logements sociaux, pour favoriser la mixité sociale."},
{id:"GE-3E-539",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Comment appelle-t-on un territoire où il est très difficile d'accéder à un médecin ?",rep:"Un désert médical",choix:["Une zone franche", "Un pôle de santé", "Un désert médical", "Une diagonale du vide"],diff:2,hint:"On utilise l'image d'un espace où il n'y a presque rien.",expl:"Un désert médical manque de médecins par rapport à sa population. Il touche surtout des espaces ruraux isolés et certaines banlieues : c'est une inégalité territoriale."},
{id:"GE-3E-540",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quelle politique publique cherche à réduire les inégalités dans les quartiers en difficulté ?",rep:"La politique de la ville",choix:["La politique monétaire", "La politique de la ville", "La politique agricole commune", "La politique étrangère"],diff:3,hint:"Elle vise des quartiers urbains, souvent des grands ensembles.",expl:"La politique de la ville aide les quartiers prioritaires : rénovation urbaine, emploi, éducation, pour réduire les écarts avec le reste de l'agglomération."},
{id:"GE-3E-541",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Les lois de décentralisation de 1982 ont transféré des pouvoirs…",rep:"de l'État aux collectivités territoriales",choix:["des communes vers l'État", "des régions vers l'Union européenne", "de l'État aux collectivités territoriales", "de l'Union européenne à l'État"],diff:3,hint:"« Décentraliser », c'est éloigner du centre (Paris).",expl:"La décentralisation donne des compétences aux régions, départements et communes, qui deviennent des acteurs majeurs de l'aménagement du territoire."},
{id:"GE-3E-542",classe:"3ème",cat:"🌍",type:"Géographie",enonce:"Quelle politique européenne soutient les agriculteurs ?",rep:"La PAC",choix:["Le programme Galileo", "L'espace Schengen", "Le programme Erasmus+", "La PAC"],diff:2,hint:"Créée dès 1962, elle représente une grande part du budget européen.",expl:"La PAC, créée en 1962, aide les agriculteurs européens par des subventions. La France en est l'un des premiers bénéficiaires."},
{id:"FR-3E-501",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans « Il est parti parce qu'il était fatigué », la subordonnée exprime…",rep:"la cause",choix:["le but", "la conséquence", "la concession", "la cause"],diff:2,hint:"Pose la question « pourquoi ? » au verbe principal.",expl:"« Parce que » introduit une subordonnée circonstancielle de cause : elle explique la raison de l'action principale."},
{id:"FR-3E-502",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans « Bien qu'il pleuve, nous sortons », la subordonnée exprime…",rep:"la concession",choix:["le temps", "la condition", "la concession", "la cause"],diff:3,hint:"L'action principale se fait malgré un obstacle.",expl:"« Bien que » introduit une concession : un fait qui aurait dû empêcher l'action principale, mais ne l'empêche pas. Elle se construit avec le subjonctif."},
{id:"FR-3E-503",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans « Il parle si fort que tout le monde l'entend », la subordonnée exprime…",rep:"la conséquence",choix:["la cause", "la comparaison", "le but", "la conséquence"],diff:3,hint:"Repère le couple « si… que » : qu'arrive-t-il à cause de sa voix ?",expl:"« Si… que » introduit une conséquence : le résultat de l'action principale (tout le monde entend parce qu'il parle fort)."},
{id:"FR-3E-504",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans « Je travaille pour que tu réussisses », la subordonnée exprime…",rep:"le but",choix:["la cause", "la conséquence", "le but", "l'opposition"],diff:2,hint:"Demande-toi : dans quelle intention le sujet agit-il ?",expl:"« Pour que » + subjonctif exprime le but : l'objectif visé, qui n'est pas encore réalisé."},
{id:"FR-3E-505",classe:"3ème",cat:"📖",type:"Français",enonce:"Quelle est la nature de « qu'il viendra » dans « Je pense qu'il viendra » ?",rep:"subordonnée complétive",choix:["subordonnée relative", "subordonnée circonstancielle", "proposition indépendante", "subordonnée complétive"],diff:3,hint:"Regarde si « que » reprend un nom (antécédent) ou complète le verbe.",expl:"« Que » n'a pas d'antécédent : c'est une conjonction. La proposition complète le verbe « penser » (COD) : c'est une subordonnée complétive."},
{id:"FR-3E-506",classe:"3ème",cat:"📖",type:"Français",enonce:"Quelle est la nature de « s'il viendra » dans « Je me demande s'il viendra » ?",rep:"subordonnée interrogative indirecte",choix:["subordonnée relative", "subordonnée complétive par que", "subordonnée de condition", "subordonnée interrogative indirecte"],diff:4,hint:"Transforme la phrase en question directe : « Viendra-t-il ? »",expl:"Après un verbe comme « se demander », « si » introduit une question rapportée : c'est une interrogative indirecte, et non une condition."},
{id:"FR-3E-507",classe:"3ème",cat:"📖",type:"Français",enonce:"Mets à la voix passive : « Le jury a récompensé Léa. »",rep:"Léa a été récompensée par le jury.",choix:["Léa était récompensée par le jury.", "Léa est récompensée par le jury.", "Léa a été récompensée par le jury.", "Léa fut récompensée par le jury."],diff:3,hint:"L'auxiliaire « être » prend le temps du verbe actif.",expl:"Au passif, l'auxiliaire « être » se met au temps du verbe actif : passé composé « a récompensé » donne « a été récompensée »."},
{id:"FR-3E-508",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans « Il m'a dit qu'il viendrait », quelle est la valeur du conditionnel ?",rep:"le futur dans le passé",choix:["l'hypothèse", "l'information incertaine", "le futur dans le passé", "la politesse"],diff:3,hint:"Quand la venue a-t-elle lieu par rapport au moment où il parle ?",expl:"Dans un récit au passé, le conditionnel exprime une action postérieure à un moment passé : c'est le futur dans le passé."},
{id:"FR-3E-509",classe:"3ème",cat:"📖",type:"Français",enonce:"Complète : « Si tu étais venu, tu ___ le spectacle. »",rep:"aurais vu",choix:["aurais vu", "avais vu", "verrais", "auras vu"],diff:3,hint:"Le « si » est suivi du plus-que-parfait : regret d'un fait passé.",expl:"Si + plus-que-parfait se construit avec le conditionnel passé (« aurais vu ») : c'est l'irréel du passé."},
{id:"FR-3E-510",classe:"3ème",cat:"📖",type:"Français",enonce:"Complète : « Il faut que nous ___ attention. » (faire)",rep:"fassions",choix:["faisons", "ferions", "fassions", "faisions"],diff:2,hint:"Après « il faut que », on emploie le subjonctif.",expl:"« Il faut que » impose le subjonctif présent : que nous fassions. « Faisions » est l'imparfait de l'indicatif."},
{id:"FR-3E-511",classe:"3ème",cat:"📖",type:"Français",enonce:"Complète : « Je doute qu'il ___ venir. » (pouvoir)",rep:"puisse",choix:["pourra", "peut", "pouvait", "puisse"],diff:3,hint:"Le doute ne présente pas l'action comme certaine.",expl:"Les verbes de doute (douter que) sont suivis du subjonctif : qu'il puisse."},
{id:"FR-3E-512",classe:"3ème",cat:"📖",type:"Français",enonce:"Quelle est la forme correcte de « venir » au passé simple, 3e personne du pluriel ?",rep:"ils vinrent",choix:["ils venèrent", "ils vinèrent", "ils venirent", "ils vinrent"],diff:3,hint:"Pense à « il vint » au singulier.",expl:"« Venir » a un passé simple en -in- : je vins, il vint, ils vinrent."},
{id:"FR-3E-513",classe:"3ème",cat:"📖",type:"Français",enonce:"À quel temps est conjugué « il eut fini » ?",rep:"passé antérieur",choix:["futur antérieur", "plus-que-parfait", "passé antérieur", "passé composé"],diff:3,hint:"L'auxiliaire « avoir » est au passé simple.",expl:"Auxiliaire au passé simple + participe passé = passé antérieur. Il marque une action achevée avant une autre au passé simple."},
{id:"FR-3E-514",classe:"3ème",cat:"📖",type:"Français",enonce:"Verbe pronominal « se laver » : quelle phrase est correctement accordée ?",rep:"Elles se sont lavé les mains.",choix:["Elles se sont lavés les mains.", "Elles se sont laver les mains.", "Elles se sont lavées les mains.", "Elles se sont lavé les mains."],diff:4,hint:"Cherche le COD : est-il placé avant ou après le verbe ?",expl:"Le COD « les mains » est placé après le verbe : le participe ne s'accorde pas. « Se » est ici COI (laver les mains à soi)."},
{id:"FR-3E-515",classe:"3ème",cat:"📖",type:"Français",enonce:"Verbe pronominal « se parler » : quelle phrase est correctement accordée ?",rep:"Ils se sont parlé toute la soirée.",choix:["Ils se sont parlé toute la soirée.", "Ils se sont parlés toute la soirée.", "Ils se sont parler toute la soirée.", "Ils se sont parlées toute la soirée."],diff:4,hint:"On parle À quelqu'un : quelle est la fonction de « se » ?",expl:"On parle à quelqu'un : « se » est COI, il n'y a pas de COD placé avant, donc « parlé » reste invariable."},
{id:"FR-3E-516",classe:"3ème",cat:"📖",type:"Français",enonce:"Complète : « ___ que soient tes efforts, continue. »",rep:"Quels",choix:["Quelles", "Quels", "Quel", "Quelques"],diff:3,hint:"Le mot s'accorde avec le sujet placé après « soient ».",expl:"Devant le verbe être, « quel que » s'écrit en deux mots et s'accorde avec le sujet : « efforts » est masculin pluriel, donc « quels »."},
{id:"FR-3E-517",classe:"3ème",cat:"📖",type:"Français",enonce:"Quelle phrase est correctement orthographiée ?",rep:"Je leur ai rendu leurs cahiers.",choix:["Je leurs ai rendu leurs cahiers.", "Je leurs ai rendu leur cahiers.", "Je leur ai rendu leur cahiers.", "Je leur ai rendu leurs cahiers."],diff:3,hint:"Devant un verbe, « leur » est un pronom ; devant un nom, un déterminant.",expl:"Le pronom « leur » (à eux) est toujours invariable ; le déterminant « leurs » s'accorde avec le nom pluriel « cahiers »."},
{id:"FR-3E-518",classe:"3ème",cat:"📖",type:"Français",enonce:"Que signifie la racine grecque « chrono » (chronologie, chronomètre) ?",rep:"le temps",choix:["la couleur", "la terre", "le temps", "la lumière"],diff:2,hint:"Un chronomètre sert à mesurer quoi ?",expl:"« Khronos » signifie « temps » en grec : chronologie = ordre dans le temps, chronomètre = instrument qui mesure le temps."},
{id:"FR-3E-519",classe:"3ème",cat:"📖",type:"Français",enonce:"Que signifie l'adjectif « omniscient » ?",rep:"qui sait tout",choix:["qui voit tout", "qui est partout", "qui peut tout", "qui sait tout"],diff:3,hint:"« Omni » = tout ; la seconde partie vient du latin « scire ».",expl:"« Omni- » veut dire « tout » et « scient » vient de « scire », savoir. Omnipotent = qui peut tout, omniprésent = qui est partout."},
{id:"FR-3E-520",classe:"3ème",cat:"📖",type:"Français",enonce:"Complète : « Un danger ___ menace la ville. »",rep:"imminent",choix:["imminent", "immanent", "éminent"],diff:3,hint:"Le danger est sur le point d'arriver.",expl:"« Imminent » = qui va arriver très bientôt. « Éminent » = remarquable (un éminent savant) ; « immanent » = qui est contenu dans la nature d'un être. Ce sont des paronymes."},
{id:"FR-3E-521",classe:"3ème",cat:"📖",type:"Français",enonce:"Complète : « La ___ économique est difficile cette année. »",rep:"conjoncture",choix:["conjoncture", "conjonction", "conjuration", "conjecture"],diff:4,hint:"On parle de la situation générale à un moment donné.",expl:"La conjoncture est la situation à un moment donné. Une conjecture est une supposition : ces mots sont des paronymes."},
{id:"FR-3E-522",classe:"3ème",cat:"📖",type:"Français",enonce:"« Va, cours, vole, et nous venge ! » (Corneille) : quelle figure de style ?",rep:"une gradation",choix:["une gradation", "une périphrase", "une antithèse", "une anaphore"],diff:3,hint:"Observe l'ordre et la force des verbes.",expl:"Les verbes vont du plus faible au plus fort (va, cours, vole) : c'est une gradation, qui fait monter l'intensité."},
{id:"FR-3E-523",classe:"3ème",cat:"📖",type:"Français",enonce:"Dire « il nous a quittés » pour « il est mort » est…",rep:"un euphémisme",choix:["une hyperbole", "une métonymie", "une antiphrase", "un euphémisme"],diff:3,hint:"La formule rend la réalité moins brutale.",expl:"L'euphémisme adoucit une réalité pénible ou choquante en l'exprimant de façon atténuée."},
{id:"FR-3E-524",classe:"3ème",cat:"📖",type:"Français",enonce:"Désigner Paris par « la Ville Lumière » est…",rep:"une périphrase",choix:["une comparaison", "une anaphore", "une périphrase", "une métonymie"],diff:2,hint:"Plusieurs mots remplacent un seul nom.",expl:"La périphrase remplace un mot par une expression qui le décrit : « la Ville Lumière » pour Paris."},
{id:"FR-3E-525",classe:"3ème",cat:"📖",type:"Français",enonce:"« Boire un verre » : quelle figure de style ?",rep:"une métonymie",choix:["une hyperbole", "une métonymie", "une métaphore", "une périphrase"],diff:3,hint:"Boit-on le verre ou ce qu'il contient ?",expl:"La métonymie désigne une chose par une autre qui lui est liée : ici le contenant (verre) pour le contenu (la boisson)."},
{id:"FR-3E-526",classe:"3ème",cat:"📖",type:"Français",enonce:"« Je vis, je meurs ; je me brûle et me noie » (Louise Labé) : quelle figure ?",rep:"une antithèse",choix:["une gradation", "une périphrase", "une antithèse", "une anaphore"],diff:3,hint:"Regarde les couples de mots : vivre/mourir, brûler/noyer.",expl:"L'antithèse rapproche des termes de sens opposés dans une même phrase pour exprimer un déchirement intérieur."},
{id:"FR-3E-527",classe:"3ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on la représentation d'une idée abstraite par un personnage concret ?",rep:"une allégorie",choix:["une hyperbole", "une métonymie", "une personnification", "une allégorie"],diff:4,hint:"Pense à la Liberté peinte en femme par Delacroix.",expl:"L'allégorie incarne une idée abstraite (la Liberté, la Mort) sous une forme concrète, souvent un personnage avec majuscule."},
{id:"FR-3E-528",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans une autobiographie, l'auteur, le narrateur et le personnage principal sont…",rep:"une seule et même personne",choix:["trois personnes distinctes", "des êtres imaginaires", "une seule et même personne", "l'auteur et un témoin"],diff:2,hint:"Qui raconte la vie de qui dans une autobiographie ?",expl:"C'est le pacte autobiographique : l'auteur raconte sa propre vie, il est à la fois narrateur et personnage principal."},
{id:"FR-3E-529",classe:"3ème",cat:"📖",type:"Français",enonce:"Quel écrivain du XVIIIe siècle a écrit l'autobiographie « Les Confessions » ?",rep:"Rousseau",choix:["Montesquieu", "Voltaire", "Rousseau", "Diderot"],diff:3,hint:"Il est aussi l'auteur du « Contrat social ».",expl:"Rousseau écrit « Les Confessions », souvent considérées comme la première grande autobiographie moderne en français."},
{id:"FR-3E-530",classe:"3ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on un récit de vie centré sur les événements historiques vécus par l'auteur ?",rep:"des mémoires",choix:["des mémoires", "un journal intime", "une biographie", "un roman historique"],diff:4,hint:"L'auteur se présente surtout comme témoin de son époque.",expl:"Les mémoires racontent la vie de l'auteur en lien avec l'Histoire dont il a été témoin ou acteur."},
{id:"FR-3E-531",classe:"3ème",cat:"📖",type:"Français",enonce:"Quelle autrice a écrit « Enfance » (1983), récit de ses souvenirs d'enfance ?",rep:"Nathalie Sarraute",choix:["Colette", "Nathalie Sarraute", "Simone de Beauvoir", "Marguerite Duras"],diff:4,hint:"Elle dialogue avec son double dans ce livre.",expl:"Dans « Enfance », Nathalie Sarraute fait revivre ses souvenirs à travers un dialogue avec une voix intérieure qui la questionne."},
{id:"FR-3E-532",classe:"3ème",cat:"📖",type:"Français",enonce:"Pendant quelle période Anne Frank tient-elle son journal ?",rep:"la Seconde Guerre mondiale",choix:["la Seconde Guerre mondiale", "la guerre froide", "la guerre d'Algérie", "la Première Guerre mondiale"],diff:2,hint:"Sa famille juive se cache à Amsterdam.",expl:"Anne Frank écrit son journal de 1942 à 1944, cachée à Amsterdam pour échapper aux persécutions nazies."},
{id:"FR-3E-533",classe:"3ème",cat:"📖",type:"Français",enonce:"Que raconte Primo Levi dans « Si c'est un homme » ?",rep:"sa déportation à Auschwitz",choix:["sa déportation à Auschwitz", "sa vie de soldat en 1914", "son exil en Amérique", "la Résistance en Italie"],diff:3,hint:"C'est un témoignage sur un camp nazi.",expl:"Primo Levi, chimiste juif italien, témoigne de sa déportation à Auschwitz et de la déshumanisation dans les camps."},
{id:"FR-3E-534",classe:"3ème",cat:"📖",type:"Français",enonce:"À quel contexte est associé le poème « Liberté » de Paul Éluard (1942) ?",rep:"la Résistance",choix:["la Révolution française", "la Première Guerre mondiale", "la Résistance", "la guerre de 1870"],diff:2,hint:"Regarde la date : la France est occupée.",expl:"Écrit sous l'Occupation, « Liberté » fut diffusé par la Résistance et parachuté par des avions alliés : c'est un poème engagé."},
{id:"FR-3E-535",classe:"3ème",cat:"📖",type:"Français",enonce:"Contre qui Victor Hugo écrit-il « Les Châtiments » ?",rep:"Napoléon III",choix:["Napoléon Ier", "Louis XVI", "Napoléon III", "Charles X"],diff:3,hint:"Hugo s'exile après un coup d'État en 1851.",expl:"Exilé après le coup d'État de 1851, Hugo dénonce Napoléon III dans « Les Châtiments » (1853), recueil de poésie engagée."},
{id:"FR-3E-536",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans « Rhinocéros » d'Ionesco, la « rhinocérite » symbolise surtout…",rep:"la contagion du totalitarisme",choix:["une épidémie réelle", "le progrès scientifique", "la peur des animaux", "la contagion du totalitarisme"],diff:3,hint:"Les habitants abandonnent peu à peu leur esprit critique.",expl:"Les personnages se transforment un à un en rhinocéros : Ionesco dénonce le conformisme et la montée des idéologies totalitaires."},
{id:"FR-3E-537",classe:"3ème",cat:"📖",type:"Français",enonce:"L'« Antigone » d'Anouilh (1944) réécrit une tragédie de…",rep:"Sophocle",choix:["Racine", "Sophocle", "Corneille", "Molière"],diff:3,hint:"La pièce d'origine date de l'Antiquité grecque.",expl:"Anouilh reprend l'Antigone de Sophocle (Ve siècle av. J.-C.) et la transpose dans le contexte de l'Occupation."},
{id:"FR-3E-538",classe:"3ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on un vers qui ne suit ni mètre régulier ni rimes obligées ?",rep:"le vers libre",choix:["le vers libre", "l'octosyllabe", "l'alexandrin", "le décasyllabe"],diff:2,hint:"Les poètes modernes s'affranchissent des règles.",expl:"Le vers libre, apparu à la fin du XIXe siècle, n'obéit à aucune longueur fixe ni à la rime obligatoire."},
{id:"FR-3E-539",classe:"3ème",cat:"📖",type:"Français",enonce:"Combien de syllabes dans « Je suis le ténébreux, le veuf, l'inconsolé » (Nerval) ?",rep:"12",choix:["10", "12", "13", "11"],diff:3,hint:"Attention à l'élision dans « l'inconsolé ».",expl:"Je-suis-le-té-né-breux / le-veuf-l'in-con-so-lé : 12 syllabes, c'est un alexandrin."},
{id:"FR-3E-540",classe:"3ème",cat:"📖",type:"Français",enonce:"Un texte qui se moque des défauts d'une société pour les dénoncer relève du registre…",rep:"satirique",choix:["épique", "lyrique", "tragique", "satirique"],diff:2,hint:"Le rire sert ici une critique.",expl:"Le registre satirique utilise la moquerie et l'ironie pour critiquer les mœurs, les institutions ou les personnes."},
{id:"FR-3E-541",classe:"3ème",cat:"📖",type:"Français",enonce:"Rapporte au discours indirect : Il a dit : « Je viendrai demain. »",rep:"Il a dit qu'il viendrait le lendemain.",choix:["Il a dit que je viendrai le lendemain.", "Il a dit qu'il viendra demain.", "Il a dit qu'il viendrait le lendemain.", "Il a dit qu'il venait demain."],diff:4,hint:"Pense aux pronoms, au temps du verbe et à l'indicateur de temps.",expl:"Au discours indirect passé : « je » devient « il », le futur devient conditionnel (futur dans le passé), « demain » devient « le lendemain »."},
{id:"FR-3E-542",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans « On l'a élu président », quelle est la fonction de « président » ?",rep:"attribut du COD",choix:["attribut du sujet", "COD", "attribut du COD", "apposition"],diff:4,hint:"« Président » donne une qualité à « l' », qui est COD.",expl:"« Président » caractérise le COD « l' » par l'intermédiaire du verbe « élire » : c'est un attribut du COD."},
{id:"FR-3E-543",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans « Victor Hugo, poète engagé, s'exila en 1851 », quelle est la fonction de « poète engagé » ?",rep:"apposition",choix:["complément du nom", "sujet", "attribut du sujet", "apposition"],diff:3,hint:"Le groupe est détaché par des virgules et précise le nom.",expl:"Le groupe détaché par des virgules apporte une précision sur « Victor Hugo » sans verbe : c'est une apposition."},
{id:"FR-3E-544",classe:"3ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on la forme verbale « en marchant » ?",rep:"un gérondif",choix:["un adjectif verbal", "un gérondif", "un infinitif", "un participe présent"],diff:3,hint:"Elle est précédée de la préposition « en ».",expl:"Le gérondif = « en » + participe présent. Il exprime souvent la manière, le temps ou le moyen."},
{id:"FR-3E-545",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans « En 1789, le peuple prend la Bastille », quelle est la valeur du présent ?",rep:"le présent de narration",choix:["le présent d'énonciation", "le présent de narration", "le présent d'habitude", "le présent de vérité générale"],diff:3,hint:"L'action se passe-t-elle maintenant ?",expl:"Le présent de narration (ou historique) raconte un fait passé comme s'il se déroulait sous nos yeux, pour le rendre vivant."},
{id:"FR-3E-546",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans « Il lisait quand le téléphone sonna », l'imparfait exprime…",rep:"une action d'arrière-plan",choix:["un fait futur", "une action d'arrière-plan", "une vérité générale", "une action soudaine"],diff:3,hint:"Quelle action interrompt l'autre ?",expl:"L'imparfait décrit l'action en cours, en arrière-plan ; le passé simple (« sonna ») marque l'action de premier plan qui survient."},
{id:"FR-3E-547",classe:"3ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on l'imitation d'une œuvre sérieuse détournée pour faire rire ?",rep:"une parodie",choix:["une traduction", "un plagiat", "une adaptation", "une parodie"],diff:3,hint:"Elle reprend le modèle en le rendant comique.",expl:"La parodie imite une œuvre connue en la déformant de façon comique ; le plagiat, lui, copie en cachant sa source."},
{id:"FR-3E-548",classe:"3ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on le sens suggéré d'un mot, qui s'ajoute à son sens premier ?",rep:"la connotation",choix:["la dénotation", "l'étymologie", "la connotation", "la définition"],diff:3,hint:"« Rouge » évoque aussi la passion ou le danger.",expl:"La dénotation est le sens premier du mot ; la connotation correspond aux idées et impressions qu'il évoque en plus."},
{id:"FR-3E-549",classe:"3ème",cat:"📖",type:"Français",enonce:"À quelle affaire se rapporte l'article « J'accuse… ! » d'Émile Zola (1898) ?",rep:"l'affaire Dreyfus",choix:["la guerre de 1870", "l'affaire Dreyfus", "la Commune de Paris", "le scandale de Panama"],diff:3,hint:"Un officier juif est condamné à tort pour trahison.",expl:"Dans « J'accuse… ! », Zola défend le capitaine Dreyfus, injustement condamné : c'est un exemple célèbre d'engagement d'un écrivain."},
{id:"FR-3E-550",classe:"3ème",cat:"📖",type:"Français",enonce:"Comment appelle-t-on un poème dont les vers dessinent une forme liée à son sujet ?",rep:"un calligramme",choix:["un acrostiche", "un haïku", "un rondeau", "un calligramme"],diff:2,hint:"Apollinaire en a écrit un en forme de pluie.",expl:"Le calligramme dispose les mots pour former un dessin (pluie, cœur, tour Eiffel), comme chez Apollinaire."},
{id:"FR-3E-551",classe:"3ème",cat:"📖",type:"Français",enonce:"À la fin du « Dormeur du val » de Rimbaud, on découvre que le soldat est…",rep:"mort",choix:["prisonnier", "endormi", "blessé", "mort"],diff:2,hint:"Relis le dernier vers : « Il a deux trous rouges au côté droit. »",expl:"Le dernier vers révèle que le soldat est mort : la chute dénonce brutalement l'horreur de la guerre."},
{id:"FR-3E-552",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans « Il ne mange que des pommes », quelle tournure négative est employée ?",rep:"la négation restrictive",choix:["la négation totale", "la double négation", "la négation partielle", "la négation restrictive"],diff:4,hint:"Mange-t-il autre chose que des pommes ?",expl:"« Ne… que » signifie « seulement » : c'est une tournure restrictive (ou exceptive), qui n'est pas une vraie négation."},
{id:"FR-3E-553",classe:"3ème",cat:"📖",type:"Français",enonce:"Dans « Je sais que tu mens », quelle est la nature de « que » ?",rep:"conjonction de subordination",choix:["conjonction de subordination", "adverbe", "pronom interrogatif", "pronom relatif"],diff:3,hint:"« Que » reprend-il un nom placé avant lui ?",expl:"« Que » n'a pas d'antécédent et introduit une complétive : c'est une conjonction de subordination, pas un pronom relatif."},
{id:"FR-3E-554",classe:"3ème",cat:"📖",type:"Français",enonce:"Combien de propositions dans « Quand il arriva, il vit que la porte était ouverte » ?",rep:"3",choix:["3", "4", "1", "2"],diff:3,hint:"Compte les verbes conjugués.",expl:"Une proposition par verbe conjugué : arriva, vit, était. La phrase complexe contient donc 3 propositions."},
{id:"FR-3E-555",classe:"3ème",cat:"📖",type:"Français",enonce:"Quel est le pluriel correct de « chef-d'œuvre » ?",rep:"des chefs-d'œuvre",choix:["des chef-d'œuvre", "des chefs-d'œuvre", "des chefs-d'œuvres", "des chef-d'œuvres"],diff:3,hint:"Il s'agit de chefs (principaux) de l'œuvre.",expl:"Seul « chef » prend la marque du pluriel : « d'œuvre » est un complément du nom qui reste invariable."},
{id:"FR-3E-556",classe:"3ème",cat:"📖",type:"Français",enonce:"Quelle forme est correcte ?",rep:"des robes marron",choix:["des robes marron", "des robe marron", "des robes marrons", "des robes marronnes"],diff:3,hint:"« Marron » est d'abord le nom d'un fruit.",expl:"Les adjectifs de couleur issus d'un nom (marron, orange, cerise) restent invariables : des robes marron."},
{id:"FR-3E-557",classe:"3ème",cat:"📖",type:"Français",enonce:"Quelle écriture est correcte ?",rep:"quatre-vingts pages",choix:["quatre-vingts pages", "quatre-vingt pages", "quatre-vingts-trois pages", "trois cent pages"],diff:3,hint:"« Vingt » et « cent » multipliés prennent un s s'ils terminent le nombre.",expl:"« Vingt » prend un s quand il est multiplié et termine le nombre : quatre-vingts, mais quatre-vingt-trois, trois cents."},
{id:"FR-LY-501",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quel mouvement du XVIe siècle place l'homme et l'étude des textes antiques au centre ?",rep:"l'humanisme",choix:["le classicisme", "le romantisme", "le baroque", "l'humanisme"],diff:2,hint:"Pense à Rabelais, Érasme et Montaigne.",expl:"L'humanisme (XVIe siècle) redécouvre les textes antiques et fait confiance à l'homme, à l'éducation et au savoir."},
{id:"FR-LY-502",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quel auteur du XVIe siècle a écrit les « Essais », avec la devise « Que sais-je ? » ?",rep:"Montaigne",choix:["Pascal", "Descartes", "Rabelais", "Montaigne"],diff:2,hint:"Il se prend lui-même pour sujet de réflexion.",expl:"Montaigne écrit les « Essais » (1580-1592) : il s'y étudie lui-même et doute de tout savoir définitif, d'où « Que sais-je ? »."},
{id:"FR-LY-503",classe:"Lycée",cat:"📖",type:"Français",enonce:"« Défense et illustration de la langue française » (1549) est le manifeste de…",rep:"la Pléiade",choix:["le symbolisme", "la Pléiade", "le Parnasse", "les Lumières"],diff:3,hint:"Le texte est signé Du Bellay, ami de Ronsard.",expl:"Du Bellay y défend l'usage du français en poésie et l'imitation des Anciens : c'est le manifeste de la Pléiade."},
{id:"FR-LY-504",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quel thème domine « Mignonne, allons voir si la rose » de Ronsard ?",rep:"le carpe diem",choix:["l'amour de la patrie", "la critique du roi", "la foi religieuse", "le carpe diem"],diff:2,hint:"La rose fane en un jour : que faut-il faire de sa jeunesse ?",expl:"Ronsard compare la jeune fille à une rose qui fane vite : il l'invite à profiter du temps présent, c'est le carpe diem."},
{id:"FR-LY-505",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quel courant (fin XVIe–XVIIe s.) valorise le mouvement, l'illusion et l'inconstance ?",rep:"le baroque",choix:["le réalisme", "l'humanisme", "le baroque", "le classicisme"],diff:3,hint:"Ce courant précède le goût classique de l'ordre.",expl:"Le baroque célèbre le changement, les apparences trompeuses, le théâtre dans le théâtre, à l'opposé de l'ordre classique."},
{id:"FR-LY-506",classe:"Lycée",cat:"📖",type:"Français",enonce:"La règle classique des trois unités impose l'unité d'action, de temps et de…",rep:"lieu",choix:["ton", "personnage", "lieu", "style"],diff:2,hint:"Boileau : « Qu'en un ... qu'en un jour un seul fait accompli… »",expl:"Selon la règle des trois unités : une seule intrigue, en une journée, dans un seul lieu, pour garantir la vraisemblance."},
{id:"FR-LY-507",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quelle règle du théâtre classique interdit de montrer la mort ou la violence sur scène ?",rep:"la bienséance",choix:["la bienséance", "la vraisemblance", "la catharsis", "l'unité d'action"],diff:3,hint:"Il s'agit de ne pas choquer le public.",expl:"La bienséance exige de respecter le goût et la morale du public : les morts violentes sont racontées (récit), pas montrées."},
{id:"FR-LY-508",classe:"Lycée",cat:"📖",type:"Français",enonce:"Selon Aristote, comment s'appelle la purgation des passions produite par la tragédie ?",rep:"la catharsis",choix:["la péripétie", "la catharsis", "l'hybris", "la mimèsis"],diff:4,hint:"Le mot grec signifie « purification ».",expl:"La catharsis : en éprouvant terreur et pitié devant la tragédie, le spectateur se libère de ses propres passions."},
{id:"FR-LY-509",classe:"Lycée",cat:"📖",type:"Français",enonce:"Dans « Phèdre » de Racine, Phèdre éprouve une passion coupable pour…",rep:"Hippolyte",choix:["Oreste", "Thésée", "Hippolyte", "Pyrrhus"],diff:3,hint:"C'est le fils de son mari Thésée.",expl:"Phèdre, épouse de Thésée, aime Hippolyte, son beau-fils : cette passion interdite la conduit à la mort."},
{id:"FR-LY-510",classe:"Lycée",cat:"📖",type:"Français",enonce:"Dans « Le Cid » de Corneille, Rodrigue doit choisir entre son amour et…",rep:"l'honneur de sa famille",choix:["la fortune de son père", "sa foi religieuse", "l'honneur de sa famille", "sa carrière à la cour"],diff:2,hint:"Le père de Chimène a offensé celui de Rodrigue.",expl:"Rodrigue doit venger son père offensé par le père de Chimène, qu'il aime : c'est le célèbre dilemme cornélien."},
{id:"FR-LY-511",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quelle devise latine résume le but de la comédie classique ?",rep:"Castigat ridendo mores",choix:["Ut pictura poesis", "Carpe diem", "Memento mori", "Castigat ridendo mores"],diff:4,hint:"La comédie veut améliorer les gens en les faisant rire.",expl:"« Castigat ridendo mores » (formule de Santeul) : la comédie corrige les mœurs par le rire, ambition que Molière revendique dans la préface de « Tartuffe »."},
{id:"FR-LY-512",classe:"Lycée",cat:"📖",type:"Français",enonce:"Dans « Candide », quelle philosophie Voltaire tourne-t-il en dérision à travers Pangloss ?",rep:"l'optimisme",choix:["l'optimisme", "l'épicurisme", "le stoïcisme", "le scepticisme"],diff:3,hint:"Pangloss répète que « tout est au mieux ».",expl:"Pangloss affirme que tout va pour le mieux malgré les catastrophes : Voltaire ridiculise l'optimisme inspiré de Leibniz."},
{id:"FR-LY-513",classe:"Lycée",cat:"📖",type:"Français",enonce:"Qui a écrit les « Lettres persanes » (1721), où des Persans découvrent la France ?",rep:"Montesquieu",choix:["Voltaire", "Montesquieu", "Diderot", "Marivaux"],diff:3,hint:"Il est aussi l'auteur de « De l'esprit des lois ».",expl:"Montesquieu utilise le regard étranger d'Usbek et Rica pour critiquer la société française : c'est un roman épistolaire."},
{id:"FR-LY-514",classe:"Lycée",cat:"📖",type:"Français",enonce:"Qui a écrit la « Déclaration des droits de la femme et de la citoyenne » (1791) ?",rep:"Olympe de Gouges",choix:["George Sand", "Madame de Staël", "Madame Roland", "Olympe de Gouges"],diff:2,hint:"Elle répond à la Déclaration de 1789.",expl:"Olympe de Gouges réclame en 1791 l'égalité entre femmes et hommes, en réécrivant la Déclaration des droits de l'homme."},
{id:"FR-LY-515",classe:"Lycée",cat:"📖",type:"Français",enonce:"Que défend Victor Hugo dans la Préface de « Cromwell » (1827) ?",rep:"le mélange du sublime et du grotesque",choix:["le respect des trois unités", "l'art pour l'art", "le mélange du sublime et du grotesque", "la séparation des genres"],diff:4,hint:"Le drame romantique veut montrer la vie entière.",expl:"Hugo rejette les règles classiques et réclame un drame qui mêle sublime et grotesque, tragique et comique, comme dans la vie."},
{id:"FR-LY-516",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quelle pièce provoque une « bataille » entre classiques et romantiques en 1830 ?",rep:"Hernani",choix:["Lorenzaccio", "Chatterton", "Hernani", "Ruy Blas"],diff:3,hint:"La pièce est de Victor Hugo.",expl:"La première d'« Hernani » de Hugo, en 1830, oppose violemment partisans des règles classiques et jeunes romantiques."},
{id:"FR-LY-517",classe:"Lycée",cat:"📖",type:"Français",enonce:"La formule « l'art pour l'art » est associée à quel mouvement poétique ?",rep:"le Parnasse",choix:["le romantisme", "le Parnasse", "la Pléiade", "le surréalisme"],diff:3,hint:"Théophile Gautier en est une grande figure.",expl:"Le Parnasse refuse l'engagement et l'épanchement : la poésie doit viser la beauté formelle, sans utilité morale ou politique."},
{id:"FR-LY-518",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quel recueil de Baudelaire est condamné pour « outrage à la morale publique » en 1857 ?",rep:"Les Fleurs du mal",choix:["Poèmes saturniens", "Les Fleurs du mal", "Les Contemplations", "Les Châtiments"],diff:2,hint:"Le titre associe beauté et mal.",expl:"« Les Fleurs du mal » (1857) valent à Baudelaire un procès : six poèmes sont censurés pour immoralité."},
{id:"FR-LY-519",classe:"Lycée",cat:"📖",type:"Français",enonce:"« Les parfums, les couleurs et les sons se répondent » (Baudelaire) : quelle notion ?",rep:"les correspondances",choix:["le carpe diem", "l'art pour l'art", "le spleen", "les correspondances"],diff:3,hint:"Les sens se font écho les uns aux autres.",expl:"Baudelaire évoque les correspondances entre les sens (synesthésies) et entre le monde visible et un monde spirituel."},
{id:"FR-LY-520",classe:"Lycée",cat:"📖",type:"Français",enonce:"Chez Baudelaire, le « spleen » désigne…",rep:"une profonde mélancolie",choix:["un idéal de beauté", "un amour heureux", "une colère politique", "une profonde mélancolie"],diff:2,hint:"Il s'oppose à l'« Idéal » dans « Les Fleurs du mal ».",expl:"Le spleen est un ennui profond, une angoisse mélancolique qui écrase le poète ; il s'oppose à l'aspiration vers l'Idéal."},
{id:"FR-LY-521",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quel romancier a réuni ses romans sous le titre « La Comédie humaine » ?",rep:"Balzac",choix:["Zola", "Hugo", "Stendhal", "Balzac"],diff:2,hint:"Il est l'auteur du « Père Goriot ».",expl:"Balzac regroupe près de 90 œuvres sous « La Comédie humaine », vaste peinture de la société française du XIXe siècle."},
{id:"FR-LY-522",classe:"Lycée",cat:"📖",type:"Français",enonce:"Le cycle des « Rougon-Macquart » de Zola suit une famille sous…",rep:"le Second Empire",choix:["le Second Empire", "la Restauration", "la Révolution française", "la Belle Époque"],diff:3,hint:"Napoléon III est alors au pouvoir.",expl:"Zola étudie l'« histoire naturelle et sociale d'une famille sous le Second Empire » (1852-1870), avec une démarche naturaliste."},
{id:"FR-LY-523",classe:"Lycée",cat:"📖",type:"Français",enonce:"Qui écrit : « Un roman est un miroir qu'on promène le long d'un chemin » ?",rep:"Stendhal",choix:["Flaubert", "Stendhal", "Maupassant", "Balzac"],diff:4,hint:"La phrase figure dans « Le Rouge et le Noir ».",expl:"Stendhal, dans « Le Rouge et le Noir », définit ainsi le roman réaliste : il doit refléter fidèlement la réalité."},
{id:"FR-LY-524",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quelle technique surréaliste consiste à écrire sans contrôle de la raison ?",rep:"l'écriture automatique",choix:["le monologue intérieur", "l'écriture automatique", "le vers libre", "le cadavre exquis"],diff:3,hint:"André Breton la définit dans le Manifeste de 1924.",expl:"L'écriture automatique note la pensée sans contrôle de la raison pour libérer l'inconscient, selon Breton."},
{id:"FR-LY-525",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quelle particularité typographique marque le recueil « Alcools » d'Apollinaire (1913) ?",rep:"l'absence de ponctuation",choix:["l'absence de ponctuation", "l'emploi des majuscules", "l'absence de titres", "des vers numérotés"],diff:3,hint:"Apollinaire supprime un élément sur les épreuves.",expl:"Apollinaire supprime toute ponctuation dans « Alcools » : le rythme du vers suffit à guider la lecture."},
{id:"FR-LY-526",classe:"Lycée",cat:"📖",type:"Français",enonce:"Dans « En attendant Godot » de Beckett, Godot…",rep:"n'arrive jamais",choix:["n'arrive jamais", "meurt au début", "arrive au dernier acte", "est un des deux héros"],diff:2,hint:"Le titre de la pièce est un indice.",expl:"Vladimir et Estragon attendent en vain Godot : cette attente absurde illustre le théâtre de l'absurde."},
{id:"FR-LY-527",classe:"Lycée",cat:"📖",type:"Français",enonce:"« Aujourd'hui, maman est morte. » est l'incipit de quel roman ?",rep:"L'Étranger",choix:["La Nausée", "Bonjour tristesse", "L'Étranger", "La Peste"],diff:2,hint:"Le héros s'appelle Meursault.",expl:"C'est la première phrase de « L'Étranger » (1942) d'Albert Camus, roman lié à la notion d'absurde."},
{id:"FR-LY-528",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quel mouvement des années 1950 remet en cause le personnage et l'intrigue du roman ?",rep:"le Nouveau Roman",choix:["l'existentialisme", "le surréalisme", "le Nouveau Roman", "le naturalisme"],diff:3,hint:"Robbe-Grillet et Sarraute en font partie.",expl:"Le Nouveau Roman (Robbe-Grillet, Sarraute, Butor) rejette le roman traditionnel : personnage flou, intrigue éclatée, descriptions minutieuses."},
{id:"FR-LY-529",classe:"Lycée",cat:"📖",type:"Français",enonce:"Dans « Juste la fin du monde » de Lagarce, Louis revient dans sa famille pour annoncer…",rep:"sa mort prochaine",choix:["son mariage", "sa ruine", "sa mort prochaine", "son départ à l'étranger"],diff:3,hint:"Le titre fait penser à une fin.",expl:"Louis revient annoncer sa mort prochaine, mais il n'y parvient pas : la pièce explore l'incommunicabilité familiale."},
{id:"FR-LY-530",classe:"Lycée",cat:"📖",type:"Français",enonce:"Un récit bref à visée argumentative dont on tire une leçon s'appelle…",rep:"un apologue",choix:["un essai", "un apologue", "un pamphlet", "un réquisitoire"],diff:3,hint:"Les fables et les contes philosophiques en sont des exemples.",expl:"L'apologue (fable, conte philosophique, utopie) argumente de façon indirecte : le récit plaisant transmet une morale."},
{id:"FR-LY-531",classe:"Lycée",cat:"📖",type:"Français",enonce:"Dans « Candide », l'Eldorado est…",rep:"une utopie",choix:["une dystopie", "une épopée", "une uchronie", "une utopie"],diff:3,hint:"C'est un pays idéal, sans misère ni fanatisme.",expl:"L'Eldorado est une société idéale imaginée : une utopie qui permet, par contraste, de critiquer l'Europe."},
{id:"FR-LY-532",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quelle est la devise de l'abbaye de Thélème dans « Gargantua » de Rabelais ?",rep:"Fais ce que voudras",choix:["Rien de trop", "Que sais-je ?", "Fais ce que voudras", "Connais-toi toi-même"],diff:3,hint:"Elle exprime une grande confiance en la liberté humaine.",expl:"« Fais ce que voudras » : Rabelais imagine une abbaye où des êtres bien éduqués, naturellement bons, vivent librement."},
{id:"FR-LY-533",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quel moraliste du XVIIe siècle a écrit « Les Caractères », recueil de portraits ?",rep:"La Bruyère",choix:["Pascal", "La Bruyère", "Boileau", "La Rochefoucauld"],diff:3,hint:"Il peint Giton le riche et Phédon le pauvre.",expl:"La Bruyère publie « Les Caractères » (1688) : des portraits satiriques qui dénoncent les travers de son temps."},
{id:"FR-LY-534",classe:"Lycée",cat:"📖",type:"Français",enonce:"Qui écrit : « L'homme n'est qu'un roseau, le plus faible de la nature ; mais c'est un roseau pensant » ?",rep:"Pascal",choix:["La Fontaine", "Pascal", "Descartes", "Montaigne"],diff:3,hint:"La phrase vient des « Pensées ».",expl:"Dans les « Pensées », Pascal souligne la fragilité de l'homme mais aussi sa grandeur : la pensée."},
{id:"FR-LY-535",classe:"Lycée",cat:"📖",type:"Français",enonce:"Sous quelle forme Laclos écrit-il « Les Liaisons dangereuses » (1782) ?",rep:"un roman épistolaire",choix:["un récit en vers", "un conte philosophique", "un roman autobiographique", "un roman épistolaire"],diff:2,hint:"Merteuil et Valmont s'écrivent beaucoup.",expl:"« Les Liaisons dangereuses » est un roman par lettres : chaque personnage livre son point de vue, souvent manipulateur."},
{id:"FR-LY-536",classe:"Lycée",cat:"📖",type:"Français",enonce:"Dans « L'Île des esclaves » de Marivaux, maîtres et valets…",rep:"échangent leurs rôles",choix:["sont réduits en esclavage", "s'enfuient ensemble", "échangent leurs rôles", "fondent une république"],diff:3,hint:"Sur l'île, l'ordre social est renversé.",expl:"Les maîtres deviennent valets et inversement : Marivaux invite les maîtres à reconnaître leurs défauts et à plus d'humanité."},
{id:"FR-LY-537",classe:"Lycée",cat:"📖",type:"Français",enonce:"Au théâtre, la double énonciation signifie que les répliques s'adressent…",rep:"aux personnages et au public",choix:["aux personnages et au public", "à l'auteur et au metteur en scène", "au personnage seul", "à deux personnages à la fois"],diff:3,hint:"Qui d'autre que les personnages entend les répliques ?",expl:"Chaque réplique vise un personnage sur scène mais aussi le spectateur, qui reçoit des informations parfois ignorées des personnages."},
{id:"FR-LY-538",classe:"Lycée",cat:"📖",type:"Français",enonce:"Comment appelle-t-on un échange rapide de répliques courtes, souvent d'un vers ?",rep:"une stichomythie",choix:["une stichomythie", "un quiproquo", "un aparté", "une tirade"],diff:3,hint:"Le dialogue devient un véritable duel verbal.",expl:"La stichomythie enchaîne des répliques brèves, vers à vers, pour montrer l'affrontement ou la vivacité du conflit."},
{id:"FR-LY-539",classe:"Lycée",cat:"📖",type:"Français",enonce:"Comment appelle-t-on un dénouement provoqué par une intervention soudaine et inattendue ?",rep:"un deus ex machina",choix:["une exposition", "un deus ex machina", "une catharsis", "un quiproquo"],diff:4,hint:"L'expression latine évoque un dieu descendu d'une machine.",expl:"Le deus ex machina résout l'intrigue par un élément extérieur imprévu, comme l'intervention du roi à la fin de « Tartuffe »."},
{id:"FR-LY-540",classe:"Lycée",cat:"📖",type:"Français",enonce:"Un long discours d'un personnage qui s'adresse à d'autres sans être interrompu est…",rep:"une tirade",choix:["un aparté", "une stichomythie", "un monologue", "une tirade"],diff:3,hint:"Les autres personnages sont présents et écoutent.",expl:"La tirade est une longue réplique adressée à d'autres personnages ; le monologue, lui, est prononcé seul en scène."},
{id:"FR-LY-541",classe:"Lycée",cat:"📖",type:"Français",enonce:"Comment appelle-t-on le débordement d'une phrase sur le vers suivant sans pause ?",rep:"un enjambement",choix:["une césure", "une diérèse", "un hémistiche", "un enjambement"],diff:3,hint:"La syntaxe ne s'arrête pas à la fin du vers.",expl:"Il y a enjambement quand la phrase continue sur le vers suivant ; le rejet est le court élément ainsi mis en valeur."},
{id:"FR-LY-542",classe:"Lycée",cat:"📖",type:"Français",enonce:"Comment appelle-t-on le mot bref placé au début du vers suivant, qui termine la phrase du vers précédent ?",rep:"un rejet",choix:["une rime", "un contre-rejet", "un rejet", "une césure"],diff:4,hint:"Il est « rejeté » au vers suivant.",expl:"Le rejet met en relief un mot court renvoyé au vers suivant ; le contre-rejet est un mot bref en fin de vers qui commence la phrase suivante."},
{id:"FR-LY-543",classe:"Lycée",cat:"📖",type:"Français",enonce:"« Pour qui sont ces serpents qui sifflent sur vos têtes ? » (Racine) : quelle figure ?",rep:"une allitération",choix:["une anaphore", "une assonance", "une gradation", "une allitération"],diff:3,hint:"Écoute le son consonne qui revient.",expl:"La répétition du son consonne [s] imite le sifflement des serpents : c'est une allitération."},
{id:"FR-LY-544",classe:"Lycée",cat:"📖",type:"Français",enonce:"Prononcer « lion » en une seule syllabe au lieu de deux s'appelle…",rep:"une synérèse",choix:["une apocope", "une diérèse", "une synérèse", "une élision"],diff:4,hint:"C'est le contraire de la diérèse.",expl:"La synérèse réunit deux voyelles voisines en une syllabe ; la diérèse les sépare (li-on) pour allonger le mot."},
{id:"FR-LY-545",classe:"Lycée",cat:"📖",type:"Français",enonce:"Au XVIe siècle, un poème qui fait l'éloge d'une partie du corps féminin s'appelle…",rep:"un blason",choix:["un rondeau", "un blason", "une ode", "une ballade"],diff:4,hint:"Clément Marot en a lancé la mode.",expl:"Le blason célèbre en détail une partie du corps (l'œil, le sourcil) ; le contreblason, lui, la dénigre."},
{id:"FR-LY-546",classe:"Lycée",cat:"📖",type:"Français",enonce:"« Le Spleen de Paris » de Baudelaire est un recueil de…",rep:"poèmes en prose",choix:["sonnets en alexandrins", "poèmes en prose", "chansons populaires", "fables morales"],diff:3,hint:"Son autre titre est « Petits poèmes en prose ».",expl:"Dans « Le Spleen de Paris », Baudelaire invente une poésie sans vers ni rimes : le poème en prose."},
{id:"FR-LY-547",classe:"Lycée",cat:"📖",type:"Français",enonce:"« Ils allaient obscurs sous la nuit solitaire » (Virgile) : quelle figure ?",rep:"une hypallage",choix:["une hyperbole", "une hypallage", "une anaphore", "une litote"],diff:4,hint:"Qui est vraiment obscur, et qui est vraiment seul ?",expl:"L'hypallage attribue un adjectif à un autre mot que celui qu'il qualifie logiquement : la nuit est obscure, les hommes sont seuls."},
{id:"FR-LY-548",classe:"Lycée",cat:"📖",type:"Français",enonce:"« Je ne te dirai pas combien il est menteur » : quelle figure de style ?",rep:"une prétérition",choix:["une litote", "une antithèse", "un euphémisme", "une prétérition"],diff:4,hint:"On dit qu'on ne dira pas… tout en le disant.",expl:"La prétérition consiste à prétendre taire une chose tout en l'exprimant, ce qui la met en valeur."},
{id:"FR-LY-549",classe:"Lycée",cat:"📖",type:"Français",enonce:"« Et le pain, et le vin, et le bois manquaient » : quelle figure de style ?",rep:"une polysyndète",choix:["une anaphore", "une polysyndète", "une asyndète", "une gradation"],diff:4,hint:"Observe la conjonction répétée.",expl:"La polysyndète répète une conjonction de coordination (et, ni) ; l'asyndète, au contraire, supprime les liens."},
{id:"FR-LY-550",classe:"Lycée",cat:"📖",type:"Français",enonce:"Comment appelle-t-on une description si vivante qu'elle donne l'impression de voir la scène ?",rep:"une hypotypose",choix:["une litote", "une prosopopée", "une hypotypose", "une périphrase"],diff:4,hint:"Le lecteur a la scène « sous les yeux ».",expl:"L'hypotypose peint une scène de façon si frappante et animée que le lecteur croit y assister."},
{id:"FR-LY-551",classe:"Lycée",cat:"📖",type:"Français",enonce:"« Bravo, quelle réussite ! » dit après un échec : quelle figure de style ?",rep:"une antiphrase",choix:["une litote", "une antiphrase", "une hyperbole", "une périphrase"],diff:3,hint:"On dit le contraire de ce que l'on pense.",expl:"L'antiphrase exprime le contraire de ce qu'on veut dire : c'est le procédé principal de l'ironie."},
{id:"FR-LY-552",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quand le lecteur découvre l'histoire à travers les perceptions d'un seul personnage, la focalisation est…",rep:"interne",choix:["omnisciente", "externe", "zéro", "interne"],diff:3,hint:"On est « dans la tête » d'un personnage.",expl:"En focalisation interne, on ne sait que ce que voit, pense et ressent un personnage."},
{id:"FR-LY-553",classe:"Lycée",cat:"📖",type:"Français",enonce:"Comment appelle-t-on les dernières lignes d'un roman ?",rep:"l'excipit",choix:["l'incipit", "le prologue", "l'excipit", "l'épilogue"],diff:3,hint:"C'est l'inverse de l'incipit.",expl:"L'incipit désigne les premières lignes d'un récit ; l'excipit, les dernières. Les deux sont souvent étudiés en commentaire."},
{id:"FR-LY-554",classe:"Lycée",cat:"📖",type:"Français",enonce:"Résumer plusieurs années en une phrase, c'est utiliser…",rep:"un sommaire",choix:["une analepse", "une scène", "un sommaire", "une pause"],diff:4,hint:"Le temps du récit est bien plus court que celui de l'histoire.",expl:"Le sommaire accélère le récit en résumant une longue durée ; la scène suit le rythme réel et la pause arrête l'histoire."},
{id:"FR-LY-555",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quand le récit s'interrompt pour une longue description, on parle de…",rep:"une pause",choix:["une pause", "une prolepse", "un sommaire", "une ellipse"],diff:3,hint:"L'histoire n'avance plus pendant ce temps.",expl:"Dans une pause (souvent descriptive), le temps de l'histoire s'arrête alors que le texte continue."},
{id:"FR-LY-556",classe:"Lycée",cat:"📖",type:"Français",enonce:"Comment appelle-t-on un récit qui contient en lui une réduction de lui-même ?",rep:"une mise en abyme",choix:["un récit encadré", "une mise en abyme", "une analepse", "un pastiche"],diff:4,hint:"Pense à un tableau représentant le même tableau.",expl:"La mise en abyme insère dans l'œuvre un élément qui la reflète, comme une pièce jouée dans la pièce."},
{id:"FR-LY-557",classe:"Lycée",cat:"📖",type:"Français",enonce:"En rhétorique, comment appelle-t-on l'image que l'orateur donne de lui pour être cru ?",rep:"l'ethos",choix:["le logos", "le pathos", "le kairos", "l'ethos"],diff:4,hint:"Logos = raison, pathos = émotion ; et la crédibilité ?",expl:"L'ethos est l'image de l'orateur (sérieux, honnêteté) ; le logos repose sur la raison, le pathos sur les émotions."},
{id:"FR-LY-558",classe:"Lycée",cat:"📖",type:"Français",enonce:"Un raisonnement qui part d'une idée générale pour en tirer un cas particulier est…",rep:"déductif",choix:["analogique", "concessif", "inductif", "déductif"],diff:3,hint:"Pense au syllogisme : « Tous les hommes sont mortels, or Socrate est un homme… »",expl:"La déduction va du général au particulier ; l'induction généralise à partir de cas particuliers."},
{id:"FR-LY-559",classe:"Lycée",cat:"📖",type:"Français",enonce:"Reconnaître une part de vérité à l'adversaire avant de le contredire, c'est faire…",rep:"une concession",choix:["une réfutation", "une digression", "une concession", "une induction"],diff:3,hint:"Pense à « certes… mais… ».",expl:"La concession admet un point de vue adverse (« certes ») avant de le dépasser (« mais ») : cela rend l'argumentation plus solide."},
{id:"FR-LY-560",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quel genre rhétorique correspond à l'éloge et au blâme ?",rep:"le genre épidictique",choix:["le genre narratif", "le genre épidictique", "le genre judiciaire", "le genre délibératif"],diff:4,hint:"Aristote distingue trois genres rhétoriques.",expl:"Aristote distingue le judiciaire (accuser/défendre), le délibératif (conseiller) et l'épidictique (louer ou blâmer)."},
{id:"FR-LY-561",classe:"Lycée",cat:"📖",type:"Français",enonce:"En dissertation, le plan dialectique suit généralement l'ordre…",rep:"thèse, antithèse, synthèse",choix:["introduction, exemple, morale", "passé, présent, avenir", "thèse, antithèse, synthèse", "cause, conséquence, solution"],diff:2,hint:"Il confronte deux points de vue avant de les dépasser.",expl:"Le plan dialectique examine une thèse, puis la thèse opposée, avant de proposer un dépassement qui nuance le débat."},
{id:"FR-LY-562",classe:"Lycée",cat:"📖",type:"Français",enonce:"Dans « Je ne l'ai jamais vu », la négation est…",rep:"partielle",choix:["lexicale", "restrictive", "totale", "partielle"],diff:4,hint:"La négation porte sur un aspect précis (ici le temps).",expl:"« Ne… pas » est une négation totale ; « ne… jamais, plus, rien, personne » sont des négations partielles, qui portent sur un élément."},
{id:"FR-LY-563",classe:"Lycée",cat:"📖",type:"Français",enonce:"« Viendras-tu demain ? » est une interrogation…",rep:"totale",choix:["rhétorique", "indirecte", "totale", "partielle"],diff:3,hint:"Quel type de réponse attend-elle ?",expl:"L'interrogation totale porte sur toute la phrase et appelle « oui » ou « non » ; la partielle porte sur un élément (qui, où…)."},
{id:"FR-LY-564",classe:"Lycée",cat:"📖",type:"Français",enonce:"Rapporte au discours indirect : Il me demande : « Où vas-tu ? »",rep:"Il me demande où je vais.",choix:["Il me demande où est-ce que je vais.", "Il me demande où je vais.", "Il me demande si je vais où.", "Il me demande où vas-je."],diff:3,hint:"Dans l'interrogative indirecte, pas d'inversion du sujet.",expl:"L'interrogative indirecte garde le mot interrogatif mais supprime l'inversion et le point d'interrogation : « où je vais »."},
{id:"FR-LY-565",classe:"Lycée",cat:"📖",type:"Français",enonce:"Dans « Le ministre serait malade, selon la presse », le conditionnel exprime…",rep:"une information non vérifiée",choix:["une information non vérifiée", "un regret", "une demande polie", "un futur dans le passé"],diff:3,hint:"Le journaliste n'est pas sûr de ce qu'il rapporte.",expl:"C'est le conditionnel journalistique : il présente un fait rapporté sans garantir qu'il est vrai."},
{id:"FR-LY-566",classe:"Lycée",cat:"📖",type:"Français",enonce:"Participe passé suivi d'un infinitif : quelle phrase est correcte ?",rep:"Les musiciens que j'ai entendus jouer",choix:["Les musiciens que j'ai entendu jouer", "Les musiciens que j'ai entendus jouer", "Les musiciens que j'ai entendues jouer", "Les musiciens que j'ai entendue jouer"],diff:4,hint:"Qui fait l'action de jouer ?",expl:"Le COD « que » (les musiciens) fait l'action de jouer : le participe suivi d'un infinitif s'accorde alors avec lui."},
{id:"FR-LY-567",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quelle phrase est correcte ?",rep:"La maison qu'il a fait construire",choix:["La maison qu'il a faite construire", "La maison qu'il a fais construire", "La maison qu'il a fait construire", "La maison qu'il a faits construire"],diff:4,hint:"« Fait » suivi d'un infinitif obéit à une règle spéciale.",expl:"Le participe « fait » suivi d'un infinitif est toujours invariable : la maison qu'il a fait construire."},
{id:"FR-LY-568",classe:"Lycée",cat:"📖",type:"Français",enonce:"Selon la norme, quel mode s'emploie après « après que » ?",rep:"l'indicatif",choix:["le conditionnel", "le subjonctif", "l'indicatif", "l'impératif"],diff:4,hint:"L'action de la subordonnée est réellement accomplie.",expl:"« Après que » introduit un fait réalisé : la norme impose l'indicatif (après qu'il est parti), contrairement à « avant que » + subjonctif."},
{id:"FR-LY-569",classe:"Lycée",cat:"📖",type:"Français",enonce:"Dans « Il y avait quelque cent personnes », « quelque » signifie…",rep:"environ",choix:["certaines", "aucune", "environ", "plusieurs"],diff:4,hint:"Devant un nombre, il est adverbe et invariable.",expl:"Devant un adjectif numéral, « quelque » est un adverbe invariable qui signifie « environ »."},
{id:"FR-LY-570",classe:"Lycée",cat:"📖",type:"Français",enonce:"En grec ancien, le mot dont vient « hypocrite » désignait…",rep:"un acteur",choix:["un juge", "un acteur", "un menteur", "un prêtre"],diff:4,hint:"Le mot vient du monde du théâtre.",expl:"« Hupokritês » désignait l'acteur qui joue un rôle : l'hypocrite est celui qui joue un personnage qu'il n'est pas."},
{id:"FR-LY-571",classe:"Lycée",cat:"📖",type:"Français",enonce:"Au XVIIe siècle, un « libertin » est d'abord…",rep:"un libre-penseur",choix:["un écrivain exilé", "un esclave affranchi", "un libre-penseur", "un séducteur"],diff:4,hint:"Le mot vient du latin « libertinus », affranchi.",expl:"Au XVIIe siècle, le libertin rejette les dogmes religieux et revendique la liberté de pensée ; le sens de séducteur vient plus tard."},
{id:"FR-LY-572",classe:"Lycée",cat:"📖",type:"Français",enonce:"Dans la querelle des Anciens et des Modernes, Charles Perrault défendait…",rep:"les Modernes",choix:["les Modernes", "les jansénistes", "les Anciens", "les précieuses"],diff:4,hint:"Il pensait que son siècle égalait l'Antiquité.",expl:"Perrault défend les Modernes : le siècle de Louis XIV peut égaler l'Antiquité. Boileau, lui, défend les Anciens."},
{id:"FR-LY-573",classe:"Lycée",cat:"📖",type:"Français",enonce:"À qui Victor Hugo s'adresse-t-il dans « Demain, dès l'aube… » ?",rep:"à sa fille morte",choix:["à sa bien-aimée", "à Napoléon III", "à sa mère", "à sa fille morte"],diff:3,hint:"Le poème figure dans « Les Contemplations ».",expl:"Hugo marche vers la tombe de sa fille Léopoldine, noyée en 1843 : on ne le comprend qu'au dernier vers."},
{id:"FR-LY-574",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quel poète écrit « De la musique avant toute chose » dans son « Art poétique » ?",rep:"Verlaine",choix:["Verlaine", "Rimbaud", "Mallarmé", "Boileau"],diff:3,hint:"C'est l'auteur des « Poèmes saturniens ».",expl:"Dans « Art poétique », Verlaine réclame une poésie musicale et suggestive, privilégiant le vers impair."},
{id:"FR-LY-575",classe:"Lycée",cat:"📖",type:"Français",enonce:"Qui écrit « Je est un autre » dans la « Lettre du voyant » (1871) ?",rep:"Rimbaud",choix:["Baudelaire", "Verlaine", "Apollinaire", "Rimbaud"],diff:3,hint:"Il a écrit « Le Bateau ivre » à 16 ans.",expl:"Rimbaud affirme que le poète doit se faire « voyant » par un dérèglement des sens, et découvrir l'autre en lui."},
{id:"FR-LY-576",classe:"Lycée",cat:"📖",type:"Français",enonce:"Sous quelle forme Diderot écrit-il le « Supplément au voyage de Bougainville » ?",rep:"un dialogue",choix:["un dialogue", "un journal intime", "une tragédie", "un poème"],diff:4,hint:"Deux personnages, A et B, discutent.",expl:"Diderot fait dialoguer A et B : le dialogue permet de confronter des idées et de critiquer la morale européenne."},
{id:"FR-LY-577",classe:"Lycée",cat:"📖",type:"Français",enonce:"Selon Rousseau, l'homme naît…",rep:"bon, mais la société le corrompt",choix:["neutre et sans passions", "mauvais, mais l'éducation le sauve", "égoïste par nature", "bon, mais la société le corrompt"],diff:3,hint:"Pense au mythe du « bon sauvage ».",expl:"Rousseau affirme que l'homme est naturellement bon et que la société, avec la propriété et les inégalités, le corrompt."},
{id:"FR-LY-578",classe:"Lycée",cat:"📖",type:"Français",enonce:"Voltaire écrit le « Traité sur la tolérance » (1763) à la suite de…",rep:"l'affaire Calas",choix:["l'affaire Calas", "l'affaire Dreyfus", "la prise de la Bastille", "la Saint-Barthélemy"],diff:4,hint:"Un protestant toulousain est exécuté injustement.",expl:"Jean Calas, protestant, est exécuté à tort en 1762 : Voltaire combat le fanatisme religieux et obtient sa réhabilitation."},
{id:"FR-LY-579",classe:"Lycée",cat:"📖",type:"Français",enonce:"Dans son célèbre monologue, que critique Figaro (Beaumarchais) ?",rep:"les privilèges de la noblesse",choix:["la pauvreté des paysans", "les privilèges de la noblesse", "le pouvoir des femmes", "la guerre contre l'Angleterre"],diff:3,hint:"Figaro est valet ; son maître est un comte.",expl:"Figaro reproche au comte de devoir sa position à sa naissance et non à son mérite : il dénonce les privilèges de la noblesse."},
{id:"FR-LY-580",classe:"Lycée",cat:"📖",type:"Français",enonce:"« La Chanson de Roland » appartient à quel genre médiéval ?",rep:"la chanson de geste",choix:["le roman courtois", "la chanson de geste", "le fabliau", "la farce"],diff:3,hint:"Elle raconte les exploits guerriers des chevaliers de Charlemagne.",expl:"La chanson de geste est un poème épique médiéval qui célèbre les exploits des héros, comme Roland à Roncevaux."},
{id:"FR-LY-581",classe:"Lycée",cat:"📖",type:"Français",enonce:"Quel poète du XVe siècle a écrit la « Ballade des pendus » ?",rep:"François Villon",choix:["Rutebeuf", "Charles d'Orléans", "François Villon", "Clément Marot"],diff:3,hint:"Ce poète a lui-même été condamné à la pendaison.",expl:"Villon, condamné à mort puis gracié, fait parler les pendus qui demandent pitié aux vivants."},
{id:"MA-5E-501",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Calcule 7 + 3 × 5.",rep:"22",choix:["35", "50", "26", "22"],diff:2,hint:"La multiplication est prioritaire sur l'addition.",expl:"On calcule d'abord 3 × 5 = 15, puis 7 + 15 = 22. La multiplication passe avant l'addition."},
{id:"MA-5E-502",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Calcule 20 − 2 × (3 + 4).",rep:"6",choix:["4", "14", "6", "126"],diff:3,hint:"Commence par la parenthèse, puis la multiplication.",expl:"Parenthèse : 3 + 4 = 7 ; multiplication : 2 × 7 = 14 ; enfin 20 − 14 = 6."},
{id:"MA-5E-503",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Calcule (−8) − (−3).",rep:"−5",choix:["−11", "11", "5", "−5"],diff:3,hint:"Soustraire un nombre, c'est ajouter son opposé.",expl:"(−8) − (−3) = (−8) + 3 = −5. Soustraire un relatif revient à ajouter son opposé."},
{id:"MA-5E-504",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Calcule 4 − 9 + 2.",rep:"−3",choix:["−7", "3", "−3", "−15"],diff:2,hint:"Calcule de gauche à droite : commence par 4 − 9.",expl:"4 − 9 = −5, puis −5 + 2 = −3. Additions et soustractions se font de gauche à droite."},
{id:"MA-5E-505",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Quel est le plus petit de ces nombres ?",rep:"−3,5",choix:["−3", "−2,8", "0,5", "−3,5"],diff:2,hint:"Parmi les négatifs, le plus petit est le plus éloigné de zéro.",expl:"−3,5 est le plus à gauche sur la droite graduée. Entre deux négatifs, le plus petit a la plus grande distance à zéro."},
{id:"MA-5E-506",classe:"5ème",cat:"🔢",type:"Maths",enonce:"La température passe de −4 °C à 7 °C. De combien a-t-elle augmenté ?",rep:"11 °C",choix:["3 °C", "−11 °C", "−3 °C", "11 °C"],diff:3,hint:"Calcule valeur finale moins valeur de départ.",expl:"7 − (−4) = 7 + 4 = 11. Une variation se calcule toujours : valeur finale − valeur initiale."},
{id:"MA-5E-507",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Calcule 5/6 + 1/3.",rep:"7/6",choix:["6/6", "6/9", "7/6", "5/18"],diff:3,hint:"Écris 1/3 avec le dénominateur 6.",expl:"1/3 = 2/6, donc 5/6 + 2/6 = 7/6. On met au même dénominateur avant d'additionner les numérateurs."},
{id:"MA-5E-508",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Quelle fraction est égale à 21/35 ?",rep:"3/5",choix:["7/5", "2/5", "3/5", "3/7"],diff:2,hint:"Cherche un diviseur commun à 21 et à 35.",expl:"21 = 7 × 3 et 35 = 7 × 5 : on divise les deux par 7 et on obtient 3/5."},
{id:"MA-5E-509",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Range dans l'ordre croissant : 3/4 ; 5/8 ; 7/8.",rep:"5/8 < 3/4 < 7/8",choix:["5/8 < 3/4 < 7/8", "5/8 < 7/8 < 3/4", "3/4 < 5/8 < 7/8", "7/8 < 3/4 < 5/8"],diff:3,hint:"Écris 3/4 avec le dénominateur 8.",expl:"3/4 = 6/8. Avec le même dénominateur, on compare les numérateurs : 5 < 6 < 7."},
{id:"MA-5E-510",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Quel nombre, multiplié par 7, donne 3 ?",rep:"3/7",choix:["4", "0,4", "3/7", "7/3"],diff:3,hint:"Pense à la définition d'un quotient.",expl:"Par définition, 3/7 est le nombre qui, multiplié par 7, donne 3 : 7 × 3/7 = 3."},
{id:"MA-5E-511",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Sur un plan à l'échelle 1/200, 3 cm représentent en réalité…",rep:"6 m",choix:["0,6 m", "60 m", "2 m", "6 m"],diff:3,hint:"1 cm sur le plan représente 200 cm en vrai.",expl:"3 × 200 = 600 cm, soit 6 m. À l'échelle 1/200, les longueurs réelles sont 200 fois plus grandes."},
{id:"MA-5E-512",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Filles et garçons sont dans le ratio 3 : 2 dans une classe de 25 élèves. Combien de filles ?",rep:"15",choix:["18", "12", "10", "15"],diff:3,hint:"Le ratio 3 : 2 partage la classe en 5 parts égales.",expl:"25 ÷ 5 = 5 élèves par part. Les filles ont 3 parts : 3 × 5 = 15."},
{id:"MA-5E-513",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Un jean à 60 € est soldé à −30 %. Quel est son nouveau prix ?",rep:"42 €",choix:["57 €", "30 €", "42 €", "18 €"],diff:2,hint:"Calcule d'abord 30 % de 60 €.",expl:"30 % de 60 = 0,3 × 60 = 18 € de remise, donc 60 − 18 = 42 €."},
{id:"MA-5E-514",classe:"5ème",cat:"🔢",type:"Maths",enonce:"18 élèves sur 24 ont un vélo. Quel pourcentage cela représente-t-il ?",rep:"75 %",choix:["66 %", "80 %", "18 %", "75 %"],diff:3,hint:"Simplifie la fraction 18/24, puis écris-la sur 100.",expl:"18/24 = 3/4 = 75/100, soit 75 %. Un pourcentage est une fraction de dénominateur 100."},
{id:"MA-5E-515",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Combien font 1,5 h en minutes ?",rep:"90 min",choix:["90 min", "150 min", "75 min", "105 min"],diff:2,hint:"Une heure vaut 60 minutes, pas 100.",expl:"1,5 h = 1 h + 0,5 h = 60 min + 30 min = 90 min. Attention : 1,5 h n'est pas 1 h 50."},
{id:"MA-5E-516",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Pour x = 3, combien vaut 2x² ?",rep:"18",choix:["9", "18", "12", "36"],diff:3,hint:"Le carré ne porte que sur x.",expl:"2x² = 2 × x × x = 2 × 9 = 18. Le carré s'applique à x seul, pas à 2x."},
{id:"MA-5E-517",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Réduis l'expression 5x + 3 − 2x + 4.",rep:"3x + 7",choix:["10x", "3x + 1", "7x + 7", "3x + 7"],diff:2,hint:"Regroupe les termes en x d'un côté, les nombres de l'autre.",expl:"5x − 2x = 3x et 3 + 4 = 7, donc 3x + 7. On ne peut pas additionner des x et des nombres seuls."},
{id:"MA-5E-518",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Quelle expression est égale à 4(2a − 5) ?",rep:"8a − 20",choix:["8a − 5", "8a + 20", "8a − 20", "6a − 20"],diff:2,hint:"Multiplie 4 par chaque terme de la parenthèse.",expl:"4 × 2a = 8a et 4 × (−5) = −20. La distributivité : k(a − b) = ka − kb."},
{id:"MA-5E-519",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Une place coûte 7 € et on paie 2 € de frais en tout. Prix de n places ?",rep:"7n + 2",choix:["2n + 7", "7(n + 2)", "9n", "7n + 2"],diff:3,hint:"Les frais ne sont payés qu'une seule fois.",expl:"n places coûtent 7 × n = 7n, auxquels on ajoute 2 € de frais une seule fois : 7n + 2."},
{id:"MA-5E-520",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Pour quelle valeur de x l'égalité 2x + 3 = 5x − 9 est-elle vraie ?",rep:"4",choix:["4", "2", "3", "6"],diff:3,hint:"Remplace x par chaque valeur et compare les deux membres.",expl:"Pour x = 4 : 2 × 4 + 3 = 11 et 5 × 4 − 9 = 11. Les deux membres sont égaux."},
{id:"MA-5E-521",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Lequel de ces nombres est divisible par 3 ?",rep:"2 541",choix:["2 541", "3 301", "7 103", "1 024"],diff:2,hint:"Additionne les chiffres de chaque nombre.",expl:"2 + 5 + 4 + 1 = 12, multiple de 3. Un nombre est divisible par 3 si la somme de ses chiffres l'est."},
{id:"MA-5E-522",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Lequel de ces nombres est premier ?",rep:"53",choix:["53", "91", "57", "51"],diff:3,hint:"Teste la division par 3 et par 7.",expl:"53 n'a que deux diviseurs, 1 et 53. Les autres : 51 = 3 × 17, 57 = 3 × 19, 91 = 7 × 13."},
{id:"MA-5E-523",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Quelle est la décomposition de 60 en produit de facteurs premiers ?",rep:"2² × 3 × 5",choix:["2 × 3 × 10", "2 × 3² × 5", "4 × 15", "2² × 3 × 5"],diff:3,hint:"Chaque facteur doit être un nombre premier.",expl:"60 = 2 × 2 × 3 × 5 = 2² × 3 × 5. 10, 4 et 15 ne sont pas premiers ; 2 × 3² × 5 vaut 90."},
{id:"MA-5E-524",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Combien le nombre 36 a-t-il de diviseurs ?",rep:"9",choix:["6", "7", "9", "8"],diff:4,hint:"Cherche les paires : 1 × 36, 2 × 18…",expl:"Paires : 1×36, 2×18, 3×12, 4×9, 6×6. Le 6 ne compte qu'une fois : 9 diviseurs."},
{id:"MA-5E-525",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Quelle est la moyenne des notes 12, 15, 9 et 14 ?",rep:"12,5",choix:["13", "12,5", "12", "13,5"],diff:2,hint:"Additionne les notes puis divise par leur nombre.",expl:"12 + 15 + 9 + 14 = 50, et 50 ÷ 4 = 12,5. Moyenne = somme des valeurs ÷ nombre de valeurs."},
{id:"MA-5E-526",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Sur 25 élèves, 5 viennent à pied. Quelle est la fréquence de cette catégorie ?",rep:"0,2",choix:["0,5", "0,25", "0,2", "5"],diff:3,hint:"Fréquence = effectif ÷ effectif total.",expl:"5 ÷ 25 = 0,2 (soit 20 %). Une fréquence est toujours comprise entre 0 et 1."},
{id:"MA-5E-527",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Un sac contient 3 boules rouges et 5 bleues. Probabilité de tirer une rouge ?",rep:"3/8",choix:["1/3", "5/8", "3/5", "3/8"],diff:2,hint:"Compte le nombre total de boules.",expl:"Il y a 3 rouges sur 8 boules en tout, donc 3/8. Probabilité = cas favorables ÷ cas possibles."},
{id:"MA-5E-528",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Le centre du cercle circonscrit à un triangle est le point de concours des…",rep:"médiatrices",choix:["médianes", "bissectrices", "médiatrices", "hauteurs"],diff:3,hint:"Ce point est à égale distance des trois sommets.",expl:"Les médiatrices sont formées des points équidistants de deux sommets ; leur point commun est équidistant des trois : c'est le centre."},
{id:"MA-5E-529",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Peut-on construire un triangle de côtés 3 cm, 4 cm et 8 cm ?",rep:"Non, car 3 + 4 < 8",choix:["Non, car 3 + 4 < 8", "Oui, c'est possible", "Oui, s'il est rectangle"],diff:3,hint:"Compare le plus grand côté à la somme des deux autres.",expl:"Inégalité triangulaire : le plus grand côté doit être inférieur à la somme des deux autres. Or 3 + 4 = 7 < 8."},
{id:"MA-5E-530",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Dans un triangle ABC, Â = 48° et B̂ = 67°. Combien mesure Ĉ ?",rep:"65°",choix:["55°", "75°", "65°", "115°"],diff:2,hint:"La somme des angles d'un triangle vaut 180°.",expl:"180° − (48° + 67°) = 180° − 115° = 65°."},
{id:"MA-5E-531",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Un triangle isocèle a un angle au sommet de 40°. Combien mesure chaque angle à la base ?",rep:"70°",choix:["70°", "140°", "40°", "50°"],diff:3,hint:"Les deux angles à la base sont égaux.",expl:"180° − 40° = 140° pour les deux angles à la base, soit 140° ÷ 2 = 70° chacun."},
{id:"MA-5E-532",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Deux parallèles coupées par une sécante forment deux angles alternes-internes…",rep:"de même mesure",choix:["complémentaires", "de même mesure", "toujours droits", "supplémentaires"],diff:3,hint:"Trace la figure et compare les deux angles.",expl:"Si les droites sont parallèles, les angles alternes-internes ont la même mesure. C'est aussi vrai pour les angles correspondants."},
{id:"MA-5E-533",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Un angle mesure 35°. Combien mesure l'angle qui lui est opposé par le sommet ?",rep:"35°",choix:["35°", "325°", "55°", "145°"],diff:2,hint:"Deux angles opposés par le sommet sont symétriques par rapport au sommet.",expl:"Deux angles opposés par le sommet ont toujours la même mesure : 35°."},
{id:"MA-5E-534",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Dans un parallélogramme, les diagonales…",rep:"se coupent en leur milieu",choix:["se coupent en leur milieu", "sont perpendiculaires", "ont la même longueur", "sont parallèles"],diff:2,hint:"Une seule propriété est vraie pour TOUS les parallélogrammes.",expl:"Tout parallélogramme a des diagonales qui se coupent en leur milieu. Perpendiculaires : losange ; même longueur : rectangle."},
{id:"MA-5E-535",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Dans le parallélogramme ABCD, Â = 110°. Combien mesure B̂ ?",rep:"70°",choix:["110°", "250°", "70°", "90°"],diff:3,hint:"Deux angles consécutifs d'un parallélogramme sont supplémentaires.",expl:"Â et B̂ sont consécutifs, donc Â + B̂ = 180° : B̂ = 180° − 110° = 70°."},
{id:"MA-5E-536",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Quel est le symétrique de A(2 ; 5) par rapport à l'origine du repère ?",rep:"(−2 ; −5)",choix:["(2 ; −5)", "(−2 ; 5)", "(−2 ; −5)", "(5 ; 2)"],diff:3,hint:"La symétrie centrale change le signe des deux coordonnées.",expl:"Par la symétrie de centre O, A(x ; y) a pour image (−x ; −y), donc (−2 ; −5)."},
{id:"MA-5E-537",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Volume d'un prisme droit dont la base a une aire de 12 cm² et la hauteur 5 cm ?",rep:"60 cm³",choix:["30 cm³", "17 cm³", "120 cm³", "60 cm³"],diff:3,hint:"Volume d'un prisme = aire de la base × hauteur.",expl:"V = 12 × 5 = 60 cm³. Pour un prisme droit, pas de division par 2 ni par 3."},
{id:"MA-5E-538",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Combien de litres contient un cube de 2 dm d'arête ?",rep:"8 L",choix:["6 L", "8 L", "4 L", "2 L"],diff:3,hint:"Calcule le volume en dm³ ; 1 dm³ = 1 L.",expl:"V = 2 × 2 × 2 = 8 dm³, et 1 dm³ = 1 L, donc 8 L."},
{id:"MA-5E-539",classe:"5ème",cat:"🔢",type:"Maths",enonce:"Quelle est l'abscisse du point B(−4 ; 1) ?",rep:"−4",choix:["−4", "4", "1", "−1"],diff:2,hint:"Dans un couple (x ; y), l'abscisse vient en premier.",expl:"Pour B(−4 ; 1), l'abscisse est −4 (axe horizontal) et l'ordonnée est 1 (axe vertical)."},
{id:"MA-4E-501",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Calcule (−6) × (−4) × (−1).",rep:"−24",choix:["24", "−24", "11", "−11"],diff:2,hint:"Compte le nombre de facteurs négatifs.",expl:"6 × 4 × 1 = 24 et il y a 3 facteurs négatifs (nombre impair) : le produit est négatif, −24."},
{id:"MA-4E-502",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Combien vaut (−2)⁵ ?",rep:"−32",choix:["10", "32", "−10", "−32"],diff:3,hint:"Un nombre négatif à une puissance impaire reste négatif.",expl:"(−2)⁵ = (−2)×(−2)×(−2)×(−2)×(−2) = −32 : cinq facteurs négatifs donnent un résultat négatif."},
{id:"MA-4E-503",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Calcule 2/3 × 9/4.",rep:"3/2",choix:["18/7", "11/7", "3/2", "8/27"],diff:2,hint:"Multiplie les numérateurs entre eux et les dénominateurs entre eux.",expl:"2/3 × 9/4 = 18/12 = 3/2. Pour multiplier deux fractions, on multiplie « en haut » et « en bas »."},
{id:"MA-4E-504",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Calcule 5/4 ÷ 10/3.",rep:"3/8",choix:["1/2", "50/12", "3/8", "8/3"],diff:3,hint:"Diviser par une fraction, c'est multiplier par son inverse.",expl:"5/4 ÷ 10/3 = 5/4 × 3/10 = 15/40 = 3/8."},
{id:"MA-4E-505",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Calcule 1 − 2/3 × 3/4.",rep:"1/2",choix:["3/4", "1/4", "1/12", "1/2"],diff:3,hint:"La multiplication est prioritaire sur la soustraction.",expl:"2/3 × 3/4 = 6/12 = 1/2, puis 1 − 1/2 = 1/2. On multiplie avant de soustraire."},
{id:"MA-4E-506",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Quel est l'inverse de −3/5 ?",rep:"−5/3",choix:["−3/5", "−5/3", "3/5", "5/3"],diff:3,hint:"Le produit d'un nombre par son inverse vaut 1.",expl:"−3/5 × (−5/3) = 1. L'inverse garde le même signe : on échange seulement numérateur et dénominateur."},
{id:"MA-4E-507",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Écris 10⁵ × 10³ sous la forme d'une seule puissance de 10.",rep:"10⁸",choix:["10¹⁵", "10⁸", "10²", "100⁸"],diff:2,hint:"Quand on multiplie des puissances de 10, que fait-on des exposants ?",expl:"10ᵃ × 10ᵇ = 10ᵃ⁺ᵇ, donc 10⁵ × 10³ = 10⁸. On additionne les exposants."},
{id:"MA-4E-508",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Combien vaut 10⁻³ ?",rep:"0,001",choix:["0,0001", "0,001", "−0,001", "−1 000"],diff:2,hint:"Un exposant négatif donne un inverse, pas un nombre négatif.",expl:"10⁻³ = 1/10³ = 1/1 000 = 0,001. Le chiffre 1 est en 3e position après la virgule."},
{id:"MA-4E-509",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Quelle est l'écriture scientifique de 45 000 ?",rep:"4,5 × 10⁴",choix:["0,45 × 10⁵", "45 × 10³", "4,5 × 10³", "4,5 × 10⁴"],diff:3,hint:"Le premier nombre doit être compris entre 1 et 10 (10 exclu).",expl:"45 000 = 4,5 × 10 000 = 4,5 × 10⁴. En écriture scientifique, la mantisse est entre 1 et 10."},
{id:"MA-4E-510",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Écris 0,0072 en notation scientifique.",rep:"7,2 × 10⁻³",choix:["7,2 × 10⁻⁴", "72 × 10⁻⁴", "7,2 × 10⁻³", "7,2 × 10³"],diff:3,hint:"Compte de combien de rangs la virgule se déplace.",expl:"0,0072 = 7,2 ÷ 1 000 = 7,2 × 10⁻³. La virgule avance de 3 rangs vers la droite."},
{id:"MA-4E-511",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Combien vaut 2⁴ × 2⁻² ?",rep:"4",choix:["1/4", "4", "1/256", "8"],diff:3,hint:"Additionne les exposants : 4 + (−2).",expl:"2⁴ × 2⁻² = 2⁴⁺⁽⁻²⁾ = 2² = 4. On additionne les exposants, on ne les multiplie pas."},
{id:"MA-4E-512",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Développe et réduis (2x + 1)(x − 4).",rep:"2x² − 7x − 4",choix:["2x² − 8x − 4", "2x² + 9x − 4", "2x² − 4", "2x² − 7x − 4"],diff:3,hint:"Multiplie chaque terme de la 1re parenthèse par chaque terme de la 2e.",expl:"2x×x + 2x×(−4) + 1×x + 1×(−4) = 2x² − 8x + x − 4 = 2x² − 7x − 4."},
{id:"MA-4E-513",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Réduis 3x × 4x.",rep:"12x²",choix:["7x²", "7x", "12x", "12x²"],diff:2,hint:"x × x s'écrit x².",expl:"3x × 4x = 3 × 4 × x × x = 12x². Dans un produit, on multiplie les nombres et les lettres."},
{id:"MA-4E-514",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Supprime les parenthèses : −(3x − 2).",rep:"−3x + 2",choix:["−3x − 2", "3x + 2", "3x − 2", "−3x + 2"],diff:2,hint:"Un signe moins devant une parenthèse change tous les signes.",expl:"−(3x − 2) = −3x + 2 : on prend l'opposé de chaque terme de la parenthèse."},
{id:"MA-4E-515",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Factorise 5x² + 10x.",rep:"5x(x + 2)",choix:["5x(x + 2)", "10x(x + 1)", "5x(x + 10)", "5(x² + 10x)"],diff:3,hint:"Cherche le facteur commun aux deux termes.",expl:"5x² = 5x × x et 10x = 5x × 2, donc 5x² + 10x = 5x(x + 2). Vérifie en développant."},
{id:"MA-4E-516",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Résous l'équation 5x + 8 = 2x − 7.",rep:"−5",choix:["−5", "−15", "−1", "5"],diff:3,hint:"Regroupe les x à gauche et les nombres à droite.",expl:"5x − 2x = −7 − 8, donc 3x = −15 et x = −5. Vérification : −25 + 8 = −17 et −10 − 7 = −17."},
{id:"MA-4E-517",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Résous l'équation 7 − 2x = 15.",rep:"−4",choix:["−11", "−4", "11", "4"],diff:3,hint:"Isole d'abord −2x, puis divise par −2.",expl:"−2x = 15 − 7 = 8, donc x = 8 ÷ (−2) = −4. Vérification : 7 − 2 × (−4) = 15."},
{id:"MA-4E-518",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Le triple d'un nombre, augmenté de 4, vaut 25. Quel est ce nombre ?",rep:"7",choix:["7", "21", "8", "9"],diff:2,hint:"Traduis l'énoncé par une équation : 3x + 4 = 25.",expl:"3x + 4 = 25 donne 3x = 21, donc x = 7. Vérification : 3 × 7 + 4 = 25."},
{id:"MA-4E-519",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Un triangle est rectangle ; ses côtés de l'angle droit mesurent 5 cm et 12 cm. Hypoténuse ?",rep:"13 cm",choix:["13 cm", "17 cm", "7 cm", "11 cm"],diff:2,hint:"Utilise le théorème de Pythagore : c² = a² + b².",expl:"5² + 12² = 25 + 144 = 169 et √169 = 13. L'hypoténuse mesure 13 cm."},
{id:"MA-4E-520",classe:"4ème",cat:"🔢",type:"Maths",enonce:"ABC est rectangle en A, BC = 10 cm et AB = 6 cm. Combien mesure AC ?",rep:"8 cm",choix:["4 cm", "16 cm", "11,7 cm", "8 cm"],diff:3,hint:"BC est l'hypoténuse : BC² = AB² + AC².",expl:"AC² = BC² − AB² = 100 − 36 = 64, donc AC = 8 cm. On soustrait car on cherche un côté de l'angle droit."},
{id:"MA-4E-521",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Lequel de ces triangles est rectangle ?",rep:"côtés 7 ; 24 ; 25",choix:["côtés 6 ; 7 ; 9", "côtés 5 ; 6 ; 8", "côtés 4 ; 5 ; 6", "côtés 7 ; 24 ; 25"],diff:3,hint:"Compare le carré du plus grand côté à la somme des deux autres carrés.",expl:"25² = 625 et 7² + 24² = 49 + 576 = 625. D'après la réciproque de Pythagore, ce triangle est rectangle."},
{id:"MA-4E-522",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Quel théorème prouve qu'un triangle est rectangle à partir des longueurs de ses côtés ?",rep:"la réciproque de Pythagore",choix:["l'inégalité triangulaire", "la réciproque de Pythagore", "le théorème de Thalès", "le théorème de Pythagore"],diff:3,hint:"On part des longueurs pour arriver à l'angle droit.",expl:"Le théorème de Pythagore suppose le triangle rectangle ; sa réciproque permet de le démontrer si c² = a² + b²."},
{id:"MA-4E-523",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Entre quels entiers consécutifs se situe √50 ?",rep:"7 et 8",choix:["6 et 7", "8 et 9", "25 et 26", "7 et 8"],diff:3,hint:"Encadre 50 entre deux carrés parfaits.",expl:"7² = 49 < 50 < 64 = 8², donc 7 < √50 < 8."},
{id:"MA-4E-524",classe:"4ème",cat:"🔢",type:"Maths",enonce:"M ∈ [AB], N ∈ [AC], (MN) // (BC), AM = 3 cm, AB = 9 cm et BC = 12 cm. Combien mesure MN ?",rep:"4 cm",choix:["8 cm", "6 cm", "4 cm", "36 cm"],diff:3,hint:"Théorème de Thalès : AM/AB = MN/BC.",expl:"AM/AB = MN/BC donne 3/9 = MN/12, donc MN = 12 × 3 ÷ 9 = 4 cm."},
{id:"MA-4E-525",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Par une translation, une figure est…",rep:"glissée sans être tournée",choix:["retournée comme dans un miroir", "agrandie selon un rapport", "glissée sans être tournée", "tournée autour d'un point"],diff:2,hint:"Pense à un objet qu'on pousse en ligne droite sur une table.",expl:"Une translation fait glisser la figure selon une direction, un sens et une longueur ; elle ne la tourne pas et garde ses dimensions."},
{id:"MA-4E-526",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Une voiture parcourt 150 km en 1 h 30. Quelle est sa vitesse moyenne ?",rep:"100 km/h",choix:["100 km/h", "115 km/h", "90 km/h", "150 km/h"],diff:3,hint:"1 h 30 = 1,5 h.",expl:"v = d ÷ t = 150 ÷ 1,5 = 100 km/h. Attention : 1 h 30 s'écrit 1,5 h et non 1,3 h."},
{id:"MA-4E-527",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Convertis 72 km/h en m/s.",rep:"20 m/s",choix:["259,2 m/s", "20 m/s", "7,2 m/s", "72 m/s"],diff:4,hint:"72 km = 72 000 m et 1 h = 3 600 s.",expl:"72 000 m ÷ 3 600 s = 20 m/s. Pour passer des km/h aux m/s, on divise par 3,6."},
{id:"MA-4E-528",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Si 4/7 = x/21, combien vaut x ?",rep:"12",choix:["3", "18", "12", "84"],diff:2,hint:"Par combien multiplie-t-on 7 pour obtenir 21 ?",expl:"21 = 7 × 3, donc x = 4 × 3 = 12. Produit en croix : x = 4 × 21 ÷ 7 = 12."},
{id:"MA-4E-529",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Un prix passe de 80 € à 92 €. Quel est le pourcentage d'augmentation ?",rep:"15 %",choix:["12 %", "13 %", "15 %", "92 %"],diff:3,hint:"Divise l'augmentation par le prix de départ.",expl:"Hausse : 92 − 80 = 12 €. 12 ÷ 80 = 0,15, soit 15 %. On divise toujours par la valeur initiale."},
{id:"MA-4E-530",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Quelle est la médiane de la série 3 ; 8 ; 5 ; 14 ; 6 ?",rep:"6",choix:["8", "5", "7,2", "6"],diff:3,hint:"Range d'abord les valeurs dans l'ordre croissant.",expl:"Rangée : 3 ; 5 ; 6 ; 8 ; 14. Avec 5 valeurs, la médiane est la 3e : 6."},
{id:"MA-4E-531",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Notes : 12 (coefficient 2) et 18 (coefficient 1). Quelle est la moyenne ?",rep:"14",choix:["14", "16", "15", "13"],diff:3,hint:"La note de coefficient 2 compte deux fois.",expl:"(12 × 2 + 18 × 1) ÷ (2 + 1) = 42 ÷ 3 = 14. On divise par la somme des coefficients."},
{id:"MA-4E-532",classe:"4ème",cat:"🔢",type:"Maths",enonce:"On tire une carte au hasard dans un jeu de 32 cartes. Probabilité de tirer un roi ?",rep:"1/8",choix:["1/4", "1/8", "1/32", "1/13"],diff:2,hint:"Combien y a-t-il de rois dans un jeu ?",expl:"Il y a 4 rois sur 32 cartes : 4/32 = 1/8."},
{id:"MA-4E-533",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Un événement a une probabilité de 0,35. Quelle est la probabilité de son contraire ?",rep:"0,65",choix:["−0,35", "0,35", "0,75", "0,65"],diff:2,hint:"Un événement et son contraire ont des probabilités de somme 1.",expl:"P(contraire) = 1 − 0,35 = 0,65. Une probabilité est toujours comprise entre 0 et 1."},
{id:"MA-4E-534",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Volume d'une pyramide de base 12 cm² et de hauteur 5 cm ?",rep:"20 cm³",choix:["60 cm³", "17 cm³", "20 cm³", "30 cm³"],diff:3,hint:"Pour une pyramide, n'oublie pas de diviser par 3.",expl:"V = (aire de la base × hauteur) ÷ 3 = 12 × 5 ÷ 3 = 20 cm³."},
{id:"MA-4E-535",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Volume d'un cône de rayon 3 cm et de hauteur 4 cm, en prenant π = 3 ?",rep:"36 cm³",choix:["12 cm³", "48 cm³", "36 cm³", "108 cm³"],diff:4,hint:"V = π × r² × h ÷ 3.",expl:"V = 3 × 3² × 4 ÷ 3 = 3 × 9 × 4 ÷ 3 = 36 cm³. Un cône a le tiers du volume du cylindre."},
{id:"MA-4E-536",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Un pavé droit mesure 3 cm × 4 cm × 12 cm. Quelle est la longueur de sa grande diagonale ?",rep:"13 cm",choix:["5 cm", "13 cm", "15 cm", "19 cm"],diff:4,hint:"Applique Pythagore deux fois : d'abord sur la base.",expl:"Diagonale de la base : √(9 + 16) = 5. Puis √(5² + 12²) = √169 = 13 cm."},
{id:"MA-4E-537",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Quel nombre a pour décomposition 2³ × 3 × 7 ?",rep:"168",choix:["84", "168", "42", "126"],diff:3,hint:"2³ = 8.",expl:"2³ × 3 × 7 = 8 × 21 = 168. Attention : 2³ vaut 8, pas 6."},
{id:"MA-4E-538",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Combien vaut (−1)¹⁰⁰ ?",rep:"1",choix:["100", "−100", "−1", "1"],diff:3,hint:"Regarde si l'exposant est pair ou impair.",expl:"100 facteurs (−1) : nombre pair de signes moins, donc le résultat est positif et vaut 1."},
{id:"MA-4E-539",classe:"4ème",cat:"🔢",type:"Maths",enonce:"Calcule 3 × (−2)² − 5.",rep:"7",choix:["−17", "−7", "31", "7"],diff:3,hint:"La puissance se calcule avant la multiplication.",expl:"(−2)² = 4, puis 3 × 4 = 12, et 12 − 5 = 7. Ordre : puissances, multiplications, puis soustraction."},
{id:"MA-3E-501",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Quel est le PGCD de 84 et 126 ?",rep:"42",choix:["21", "14", "252", "42"],diff:3,hint:"Décompose les deux nombres en facteurs premiers.",expl:"84 = 2² × 3 × 7 et 126 = 2 × 3² × 7. Les facteurs communs donnent 2 × 3 × 7 = 42."},
{id:"MA-3E-502",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Combien de diviseurs premiers différents le nombre 90 possède-t-il ?",rep:"3",choix:["3", "2", "4", "12"],diff:3,hint:"Décompose 90 en produit de facteurs premiers.",expl:"90 = 2 × 3² × 5 : les diviseurs premiers sont 2, 3 et 5, soit 3."},
{id:"MA-3E-503",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Avec 48 billes rouges et 60 bleues, nombre maximal de sachets identiques sans reste ?",rep:"12",choix:["24", "12", "4", "6"],diff:3,hint:"Le nombre de sachets doit diviser 48 et 60.",expl:"On cherche le plus grand diviseur commun : PGCD(48 ; 60) = 12. Chaque sachet aura 4 rouges et 5 bleues."},
{id:"MA-3E-504",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Développe (x + 5)².",rep:"x² + 10x + 25",choix:["x² + 5x + 25", "x² + 10x + 25", "2x + 10", "x² + 25"],diff:2,hint:"Utilise (a + b)² = a² + 2ab + b².",expl:"(x + 5)² = x² + 2 × x × 5 + 5² = x² + 10x + 25. Ne pas oublier le double produit."},
{id:"MA-3E-505",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Développe (3x − 2)².",rep:"9x² − 12x + 4",choix:["9x² − 12x + 4", "3x² − 12x + 4", "9x² − 4", "9x² − 6x + 4"],diff:3,hint:"Utilise (a − b)² = a² − 2ab + b² avec a = 3x.",expl:"(3x)² − 2 × 3x × 2 + 2² = 9x² − 12x + 4. Le carré de 3x est 9x²."},
{id:"MA-3E-506",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Développe (2x + 7)(2x − 7).",rep:"4x² − 49",choix:["4x² − 49", "4x² − 28x − 49", "4x² + 49", "2x² − 49"],diff:3,hint:"Reconnais l'identité (a + b)(a − b).",expl:"(a + b)(a − b) = a² − b², donc (2x)² − 7² = 4x² − 49."},
{id:"MA-3E-507",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Factorise 25x² − 4.",rep:"(5x − 2)(5x + 2)",choix:["(25x − 2)(25x + 2)", "(5x − 4)(5x + 4)", "(5x − 2)(5x + 2)", "(5x − 2)²"],diff:3,hint:"25x² et 4 sont des carrés : de quoi ?",expl:"25x² − 4 = (5x)² − 2² = (5x − 2)(5x + 2), avec a² − b² = (a − b)(a + b)."},
{id:"MA-3E-508",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Factorise x² + 6x + 9.",rep:"(x + 3)²",choix:["(x + 3)(x − 3)", "(x − 3)²", "(x + 3)²", "(x + 9)²"],diff:3,hint:"Repère a² + 2ab + b² : 9 est le carré de quel nombre ?",expl:"x² + 6x + 9 = x² + 2 × x × 3 + 3² = (x + 3)²."},
{id:"MA-3E-509",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Factorise (x + 1)(2x − 3) + (x + 1)(x + 5).",rep:"(x + 1)(3x + 2)",choix:["(x + 1)(3x − 8)", "2(x + 1)(3x + 2)", "(x + 1)(3x + 2)", "(x + 1)(x − 8)"],diff:4,hint:"(x + 1) est un facteur commun aux deux termes.",expl:"(x + 1)[(2x − 3) + (x + 5)] = (x + 1)(3x + 2). On additionne ce qui reste dans les crochets."},
{id:"MA-3E-510",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Quelles sont les solutions de (x − 3)(2x + 8) = 0 ?",rep:"3 et −4",choix:["−3 et 4", "3 et −4", "3 et −8", "3 et 4"],diff:3,hint:"Un produit est nul si l'un de ses facteurs est nul.",expl:"x − 3 = 0 donne x = 3 ; 2x + 8 = 0 donne x = −4. Équation produit nul : on annule chaque facteur."},
{id:"MA-3E-511",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Combien de solutions l'équation x² = −9 a-t-elle ?",rep:"Aucune",choix:["Une seule : −3", "Une seule : 3", "Deux : 3 et −3", "Aucune"],diff:3,hint:"Un carré peut-il être négatif ?",expl:"Un carré est toujours positif ou nul, donc x² = −9 n'a aucune solution. Attention : (−3)² = 9, pas −9."},
{id:"MA-3E-512",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Résous l'inéquation −3x + 6 < 0.",rep:"x > 2",choix:["x < −2", "x > −2", "x > 2", "x < 2"],diff:4,hint:"Diviser par un nombre négatif change le sens de l'inégalité.",expl:"−3x < −6, puis on divise par −3 en changeant le sens : x > 2. Vérifie avec x = 3 : −9 + 6 < 0."},
{id:"MA-3E-513",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Résous l'équation 2(x − 4) = 3x + 1.",rep:"−9",choix:["−7", "−9", "−3", "9"],diff:3,hint:"Développe d'abord le membre de gauche.",expl:"2x − 8 = 3x + 1 donne −8 − 1 = 3x − 2x, donc x = −9. Vérification : 2 × (−13) = −26 = −27 + 1."},
{id:"MA-3E-514",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Soit f(x) = x² − 3. Quelle est l'image de −2 par f ?",rep:"1",choix:["−1", "1", "7", "−7"],diff:2,hint:"Remplace x par −2, avec des parenthèses.",expl:"f(−2) = (−2)² − 3 = 4 − 3 = 1. Le carré d'un nombre négatif est positif."},
{id:"MA-3E-515",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Soit g(x) = 4x − 5. Quel est l'antécédent de 11 par g ?",rep:"4",choix:["6", "1,5", "39", "4"],diff:3,hint:"Résous l'équation 4x − 5 = 11.",expl:"4x − 5 = 11 donne 4x = 16, donc x = 4. Un antécédent est un nombre de départ, pas une image."},
{id:"MA-3E-516",classe:"3ème",cat:"🔢",type:"Maths",enonce:"La fonction f définie par f(x) = −2x + 7 est une fonction…",rep:"affine",choix:["du second degré", "linéaire", "affine", "constante"],diff:2,hint:"Compare avec les formes ax et ax + b.",expl:"f(x) = ax + b avec a = −2 et b = 7 : f est affine. Elle n'est pas linéaire car b ≠ 0."},
{id:"MA-3E-517",classe:"3ème",cat:"🔢",type:"Maths",enonce:"On écrit f(x) = 5 − 3x sous la forme ax + b. Combien vaut a ?",rep:"−3",choix:["−3", "3", "−5", "5"],diff:3,hint:"a est le nombre qui multiplie x.",expl:"5 − 3x = −3x + 5, donc a = −3 et b = 5. L'ordre des termes ne change rien, le signe reste attaché."},
{id:"MA-3E-518",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Une fonction linéaire f vérifie f(2) = 7. Combien vaut f(6) ?",rep:"21",choix:["21", "42", "14", "11"],diff:3,hint:"Pour une fonction linéaire, les images sont proportionnelles aux nombres.",expl:"6 = 3 × 2, donc f(6) = 3 × f(2) = 21. Une fonction linéaire traduit une situation de proportionnalité."},
{id:"MA-3E-519",classe:"3ème",cat:"🔢",type:"Maths",enonce:"La droite représentant f(x) = 2x + 3 coupe l'axe des ordonnées au point…",rep:"(0 ; 3)",choix:["(0 ; 2)", "(0 ; 3)", "(3 ; 0)", "(−1,5 ; 0)"],diff:3,hint:"Sur l'axe des ordonnées, l'abscisse vaut 0.",expl:"f(0) = 2 × 0 + 3 = 3 : le point est (0 ; 3). L'ordonnée à l'origine est b."},
{id:"MA-3E-520",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Une fonction affine vérifie f(1) = 5 et f(3) = 11. Combien vaut son coefficient a ?",rep:"3",choix:["2", "8", "6", "3"],diff:4,hint:"a = (différence des images) ÷ (différence des nombres).",expl:"a = (11 − 5) ÷ (3 − 1) = 6 ÷ 2 = 3. Les accroissements de f sont proportionnels à ceux de x."},
{id:"MA-3E-521",classe:"3ème",cat:"🔢",type:"Maths",enonce:"La courbe d'une fonction f passe par le point A(2 ; −1). Cela signifie que…",rep:"f(2) = −1",choix:["f(−1) = 2", "f(1) = 2", "f(2) = f(−1)", "f(2) = −1"],diff:2,hint:"Un point de la courbe a pour coordonnées (x ; f(x)).",expl:"A(2 ; −1) sur la courbe signifie que l'image de 2 est −1 : f(2) = −1."},
{id:"MA-3E-522",classe:"3ème",cat:"🔢",type:"Maths",enonce:"ABC est rectangle en A. Le cosinus de l'angle B̂ est égal à…",rep:"AB/BC",choix:["BC/AB", "AC/BC", "AB/BC", "AB/AC"],diff:3,hint:"Cosinus = côté adjacent ÷ hypoténuse.",expl:"Pour B̂, le côté adjacent est AB et l'hypoténuse BC, donc cos B̂ = AB/BC."},
{id:"MA-3E-523",classe:"3ème",cat:"🔢",type:"Maths",enonce:"ABC est rectangle en A. La tangente de l'angle Ĉ est égale à…",rep:"AB/AC",choix:["AB/BC", "AC/AB", "AC/BC", "AB/AC"],diff:3,hint:"Tangente = côté opposé ÷ côté adjacent.",expl:"Pour Ĉ, le côté opposé est AB et le côté adjacent AC, donc tan Ĉ = AB/AC."},
{id:"MA-3E-524",classe:"3ème",cat:"🔢",type:"Maths",enonce:"ABC est rectangle en A, BC = 10 cm et B̂ = 60°. Combien mesure AB ? (cos 60° = 0,5)",rep:"5 cm",choix:["17,3 cm", "8,7 cm", "5 cm", "20 cm"],diff:4,hint:"AB est le côté adjacent à B̂ ; BC est l'hypoténuse.",expl:"cos B̂ = AB/BC, donc AB = BC × cos 60° = 10 × 0,5 = 5 cm."},
{id:"MA-3E-525",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Une échelle de 5 m a son pied à 1,5 m du mur. Que vaut le cosinus de l'angle échelle-sol ?",rep:"0,3",choix:["0,5", "0,3", "0,7", "3,5"],diff:3,hint:"L'échelle est l'hypoténuse, le sol est le côté adjacent.",expl:"cos = adjacent ÷ hypoténuse = 1,5 ÷ 5 = 0,3. Un cosinus d'angle aigu est toujours entre 0 et 1."},
{id:"MA-3E-526",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Dans un triangle rectangle, sin x = 0,6 et l'hypoténuse mesure 15 cm. Côté opposé à x ?",rep:"9 cm",choix:["25 cm", "9 cm", "6 cm", "12 cm"],diff:3,hint:"Sinus = côté opposé ÷ hypoténuse.",expl:"Opposé = hypoténuse × sin x = 15 × 0,6 = 9 cm."},
{id:"MA-3E-527",classe:"3ème",cat:"🔢",type:"Maths",enonce:"A, M, B et A, N, C sont alignés dans le même ordre et AM/AB = AN/AC. Que peut-on conclure ?",rep:"(MN) et (BC) sont parallèles",choix:["le triangle AMN est rectangle", "(MN) et (BC) sont parallèles", "M est le milieu de [AB]", "(MN) et (BC) sont sécantes en A"],diff:3,hint:"C'est la situation de la réciproque du théorème de Thalès.",expl:"Points alignés dans le même ordre et rapports égaux : d'après la réciproque de Thalès, (MN) // (BC)."},
{id:"MA-3E-528",classe:"3ème",cat:"🔢",type:"Maths",enonce:"A, M, B et A, N, C alignés dans cet ordre ; AM = 2, AB = 5, AN = 3, AC = 7,5. (MN) // (BC) ?",rep:"Oui, les rapports sont égaux",choix:["Oui, les rapports sont égaux", "Non, les rapports sont différents", "On ne peut pas conclure"],diff:3,hint:"Calcule AM/AB et AN/AC.",expl:"AM/AB = 2/5 = 0,4 et AN/AC = 3/7,5 = 0,4. Rapports égaux et points dans le même ordre : (MN) // (BC)."},
{id:"MA-3E-529",classe:"3ème",cat:"🔢",type:"Maths",enonce:"(BD) et (CE) se coupent en A, (BC) // (DE), AB = 4, AD = 6 et BC = 5. Combien vaut DE ?",rep:"7,5",choix:["3,3", "7", "6", "7,5"],diff:4,hint:"Configuration « papillon » de Thalès : AB/AD = BC/DE.",expl:"AB/AD = BC/DE donne 4/6 = 5/DE, donc DE = 5 × 6 ÷ 4 = 7,5."},
{id:"MA-3E-530",classe:"3ème",cat:"🔢",type:"Maths",enonce:"On agrandit une figure à l'échelle 3. Son aire est multipliée par…",rep:"9",choix:["27", "9", "3", "6"],diff:3,hint:"Les deux dimensions sont multipliées par 3.",expl:"Dans un agrandissement de rapport k, les aires sont multipliées par k², soit 3² = 9."},
{id:"MA-3E-531",classe:"3ème",cat:"🔢",type:"Maths",enonce:"On réduit un cube de rapport 1/2. Son volume est multiplié par…",rep:"1/8",choix:["1/6", "1/2", "1/8", "1/4"],diff:3,hint:"Les trois dimensions sont multipliées par 1/2.",expl:"Les volumes sont multipliés par k³ : (1/2)³ = 1/8."},
{id:"MA-3E-532",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Une homothétie de rapport −1 correspond à…",rep:"une symétrie centrale",choix:["une translation", "une symétrie centrale", "une symétrie axiale", "une rotation de 90°"],diff:4,hint:"Chaque point est envoyé à la même distance, de l'autre côté du centre.",expl:"Avec k = −1, l'image de M est le point M' tel que le centre O soit le milieu de [MM'] : c'est la symétrie de centre O."},
{id:"MA-3E-533",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Une homothétie de rapport 0,5 transforme une figure en…",rep:"une réduction",choix:["une figure de même taille", "un agrandissement", "une réduction"],diff:2,hint:"Compare 0,5 à 1.",expl:"Si le rapport est compris entre −1 et 1 (non nul), les longueurs diminuent : 0,5 donne une réduction de moitié."},
{id:"MA-3E-534",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Quel est le volume d'une boule de rayon 3 cm ? (π ≈ 3,14)",rep:"113,04 cm³",choix:["37,68 cm³", "28,26 cm³", "113,04 cm³", "339,12 cm³"],diff:3,hint:"V = 4/3 × π × r³.",expl:"V = 4/3 × 3,14 × 27 = 4 × 3,14 × 9 = 113,04 cm³. Le rayon est au cube."},
{id:"MA-3E-535",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Quelle formule donne l'aire d'une sphère de rayon r ?",rep:"4πr²",choix:["2πr", "πr²", "4πr²", "4/3 πr³"],diff:3,hint:"C'est une aire : le rayon apparaît au carré.",expl:"L'aire d'une sphère vaut 4πr², soit quatre fois l'aire d'un disque de même rayon."},
{id:"MA-3E-536",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Un plan passant par le centre d'une sphère la coupe selon…",rep:"un cercle de même rayon",choix:["une ellipse", "un cercle de rayon plus petit", "un cercle de même rayon"],diff:3,hint:"Tous les points de la section sont à distance r du centre.",expl:"Le centre de la sphère est dans le plan, donc la section est un cercle de centre O et de rayon r : un « grand cercle »."},
{id:"MA-3E-537",classe:"3ème",cat:"🔢",type:"Maths",enonce:"La section d'un pavé droit par un plan parallèle à une face est…",rep:"un rectangle identique à cette face",choix:["un rectangle plus petit que cette face", "un rectangle identique à cette face", "un triangle", "un trapèze"],diff:2,hint:"Imagine une tranche de pain de mie.",expl:"Un plan parallèle à une face découpe un rectangle de mêmes dimensions que cette face."},
{id:"MA-3E-538",classe:"3ème",cat:"🔢",type:"Maths",enonce:"La section d'une pyramide par un plan parallèle à sa base est…",rep:"une réduction de la base",choix:["un agrandissement de la base", "toujours un triangle", "toujours un carré", "une réduction de la base"],diff:3,hint:"Pense à la configuration de Thalès dans chaque face.",expl:"La section a la même forme que la base, en plus petit : c'est une réduction de la base."},
{id:"MA-3E-539",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Sur la Terre, on repère un lieu à l'aide de…",rep:"sa latitude et sa longitude",choix:["son altitude et sa profondeur", "son méridien et son fuseau", "son abscisse et son ordonnée", "sa latitude et sa longitude"],diff:2,hint:"On utilise l'équateur et le méridien de Greenwich.",expl:"La latitude se mesure par rapport à l'équateur, la longitude par rapport au méridien de Greenwich."},
{id:"MA-3E-540",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Une cuve a un volume de 2,5 m³. Combien de litres contient-elle ?",rep:"2 500 L",choix:["250 L", "25 000 L", "2 500 L", "25 L"],diff:2,hint:"1 m³ = 1 000 dm³ et 1 dm³ = 1 L.",expl:"1 m³ = 1 000 L, donc 2,5 m³ = 2,5 × 1 000 = 2 500 L."},
{id:"MA-3E-541",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Un robinet débite 12 L par minute. Combien de temps faut-il pour remplir 300 L ?",rep:"25 min",choix:["36 min", "25 min", "30 min", "20 min"],diff:2,hint:"Durée = volume ÷ débit.",expl:"300 ÷ 12 = 25 min. Le débit est un volume par unité de temps."},
{id:"MA-3E-542",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Une ampoule de 60 W fonctionne pendant 5 h. Quelle énergie consomme-t-elle ?",rep:"300 Wh",choix:["12 Wh", "3 kWh", "300 Wh", "65 Wh"],diff:3,hint:"Énergie = puissance × durée.",expl:"E = P × t = 60 W × 5 h = 300 Wh, soit 0,3 kWh."},
{id:"MA-3E-543",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Un prix augmente de 20 % puis baisse de 20 %. Au final, il a…",rep:"baissé de 4 %",choix:["baissé de 2 %", "augmenté de 4 %", "retrouvé sa valeur", "baissé de 4 %"],diff:4,hint:"Multiplie les coefficients : 1,2 × 0,8.",expl:"1,2 × 0,8 = 0,96 : le prix est multiplié par 0,96, soit une baisse de 4 %. Les pourcentages ne s'ajoutent pas."},
{id:"MA-3E-544",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Multiplier un prix par 0,85 revient à…",rep:"le baisser de 15 %",choix:["le baisser de 0,85 %", "l'augmenter de 85 %", "le baisser de 15 %", "le baisser de 85 %"],diff:3,hint:"Compare 0,85 à 1 − 0,15.",expl:"0,85 = 1 − 0,15 : baisser de t % revient à multiplier par 1 − t/100. Ici, 15 %."},
{id:"MA-3E-545",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Après une hausse de 10 %, un vélo coûte 330 €. Quel était son prix initial ?",rep:"300 €",choix:["320 €", "300 €", "363 €", "297 €"],diff:4,hint:"Le prix initial a été multiplié par 1,1.",expl:"Prix initial × 1,1 = 330, donc prix initial = 330 ÷ 1,1 = 300 €. Retirer 10 % de 330 donne 297 €, c'est faux."},
{id:"MA-3E-546",classe:"3ème",cat:"🔢",type:"Maths",enonce:"On lance deux fois une pièce équilibrée. Quelle est la probabilité d'obtenir deux fois pile ?",rep:"1/4",choix:["1/4", "3/4", "1/3", "1/2"],diff:3,hint:"Liste les issues : PP, PF, FP, FF.",expl:"4 issues équiprobables, une seule favorable (PP) : 1/4. Ou bien 1/2 × 1/2 = 1/4."},
{id:"MA-3E-547",classe:"3ème",cat:"🔢",type:"Maths",enonce:"On lance deux dés équilibrés à 6 faces. Probabilité que la somme soit 12 ?",rep:"1/36",choix:["1/12", "1/36", "1/6", "1/11"],diff:3,hint:"Combien d'issues en tout ? Lesquelles donnent 12 ?",expl:"Il y a 6 × 6 = 36 issues équiprobables ; seule (6 ; 6) donne 12. La probabilité est 1/36."},
{id:"MA-3E-548",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Sac : 4 boules vertes, 6 rouges. On tire une boule, on la remet, puis on en tire une autre. P(deux vertes) ?",rep:"0,16",choix:["0,4", "0,24", "0,16", "0,8"],diff:4,hint:"P(verte) = 0,4 à chaque tirage, car on remet la boule.",expl:"Avec remise, les tirages se répètent à l'identique : 0,4 × 0,4 = 0,16. On multiplie le long d'une branche de l'arbre."},
{id:"MA-3E-549",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Quelle est l'étendue de la série 12 ; 7 ; 19 ; 3 ; 15 ?",rep:"16",choix:["12", "19", "16", "11,2"],diff:2,hint:"Étendue = plus grande valeur − plus petite valeur.",expl:"19 − 3 = 16. L'étendue mesure la dispersion des valeurs."},
{id:"MA-3E-550",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Une série de 9 valeurs est rangée dans l'ordre croissant. Sa médiane est…",rep:"la 5e valeur",choix:["la moyenne des 4e et 5e", "la 9e valeur divisée par 2", "la 5e valeur", "la 4e valeur"],diff:3,hint:"La médiane laisse autant de valeurs avant qu'après elle.",expl:"Avec 9 valeurs, la 5e en a 4 avant et 4 après : c'est la médiane. Pour un effectif pair, on prendrait deux valeurs."},
{id:"MA-3E-551",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Combien vaut (√7)² ?",rep:"7",choix:["14", "7", "49", "√14"],diff:2,hint:"√7 est le nombre positif dont le carré vaut 7.",expl:"Par définition de la racine carrée, (√a)² = a pour a positif, donc (√7)² = 7."},
{id:"MA-3E-552",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Calcule (5 × 10³) × (4 × 10⁻⁵).",rep:"0,2",choix:["0,02", "20", "0,2", "2"],diff:4,hint:"Multiplie 5 × 4, puis les puissances de 10 entre elles.",expl:"5 × 4 = 20 et 10³ × 10⁻⁵ = 10⁻², donc 20 × 10⁻² = 0,2."},
{id:"MA-3E-553",classe:"3ème",cat:"🔢",type:"Maths",enonce:"Programme : choisir x, ajouter 3, multiplier par 2, soustraire 6. Quel résultat obtient-on ?",rep:"2x",choix:["2x", "2x + 6", "x", "2x − 3"],diff:3,hint:"Écris le programme sous forme d'expression puis développe.",expl:"(x + 3) × 2 − 6 = 2x + 6 − 6 = 2x. Le programme donne toujours le double du nombre choisi."},
];
